INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Какая максимальная длина волос (в см) разрешена военнослужащим со звания младший лейтенант до звания капитан?', '[]', '[]', '', 1, 170, '{"meta":{"article":"ВУ, п. 3.8","explanation":"ВУ, п. 3.8: «Со звания Младший Лейтенант до звания Капитан разрешено носить опрятные прически с длиной волос не более 1 см.»","quote":"«Со звания Младший Лейтенант до звания Капитан разрешено носить опрятные прически с длиной волос не более 1 см.»","difficulty":"1"},"answer":1,"tolerance":0,"unit":""}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-017', NULL, 'full', 1, 'vu', 'ВУ, п. 3.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'С какого звания можно носить любые опрятные причёски?', '[{"id":"vM1yY1pI","text":"С лейтенанта"},{"id":"DBAdxYr","text":"С капитана"},{"id":"SYyIFrg","text":"С майора"},{"id":"RuGnyuEX","text":"С полковника"}]', '["SYyIFrg"]', '', 1, 180, '{"meta":{"article":"ВУ, п. 3.8","explanation":"ВУ, п. 3.8: «Со звания Майор и выше можно носить любые опрятные прически.»","quote":"«Со звания Майор и выше можно носить любые опрятные прически.»","difficulty":"1"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-018', NULL, 'simple', 1, 'vu', 'ВУ, п. 3.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Выберите верные утверждения о растительности на лице.', '[{"id":"LiRHsE0L","text":"Со звания младший лейтенант разрешены опрятные усы"},{"id":"fuSW7CJ","text":"Бороды разрешены с майора"},{"id":"iOtvVf04","text":"Бороды, бородки и щетина запрещены независимо от звания"},{"id":"ePWXC77","text":"Усы разрешены всем, включая рядовых"}]', '["LiRHsE0L","iOtvVf04"]', '', 1, 190, '{"meta":{"article":"ВУ, п. 3.9","explanation":"ВУ, п. 3.9: «Военнослужащим со звания Младший Лейтенант разрешено иметь усы опрятного вида.» «Бороды, бородки, щетины запрещены независимо от звания, должности и положения военнослужащего.»","quote":"«Военнослужащим со звания Младший Лейтенант разрешено иметь усы опрятного вида.» … «Бороды, бородки, щетины запрещены независимо от звания, должности и положения военнослужащего.»","difficulty":"1"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-019', NULL, 'simple', 1, 'vu', 'ВУ, п. 3.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте тип дня и окончание служебного дня (начало везде 9:00).', '[]', '[]', '', 1, 200, '{"meta":{"article":"ВУ, п. 4.1","explanation":"ВУ, п. 4.1: «Будние дни с 9:00 до 22:00;» «Выходные с 9:00 до 21:00;» «Праздничные дни с 9:00 до 20:00;»","quote":"«Будние дни с 9:00 до 22:00;» … «Выходные с 9:00 до 21:00;» … «Праздничные дни с 9:00 до 20:00;»","difficulty":"1"},"pairs":[{"l":{"id":"txEmxaU","text":"Будние дни"},"r":{"id":"yZRVDn41","text":"22:00"}},{"l":{"id":"LzyG1Unz","text":"Выходные"},"r":{"id":"3GsJofwM","text":"21:00"}},{"l":{"id":"fNysxoC","text":"Праздничные дни"},"r":{"id":"lDhEAvU","text":"20:00"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-020', NULL, 'medium', 1, 'vu', 'ВУ, п. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-020');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда обеденный перерыв по распорядку дня?', '[{"id":"BvdavKWt","text":"13:00–14:00"},{"id":"VJvCjd6l","text":"14:00–15:00"},{"id":"HBYg2DLr","text":"12:00–13:00"},{"id":"EZ47XKlh","text":"15:00–16:00"}]', '["VJvCjd6l"]', '', 1, 210, '{"meta":{"article":"ВУ, п. 4.1","explanation":"ВУ, п. 4.1: «Обеденный перерыв ежедневно с 14:00 до 15:00.»","quote":"«Обеденный перерыв ежедневно с 14:00 до 15:00.»","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-021', NULL, 'full', 1, 'vu', 'ВУ, п. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Во сколько ежедневно проводится вечерняя поверка?', '[{"id":"m4bksbD","text":"20:00"},{"id":"ZMvFmqC","text":"21:00"},{"id":"1doGshCH","text":"21:30"},{"id":"h2D5Lphz","text":"22:00"}]', '["ZMvFmqC"]', '', 1, 220, '{"meta":{"article":"ВУ, п. 4.3","explanation":"ВУ, п. 4.3: «Ежедневно, в 21:00, проводится вечерняя поверка»","quote":"«Ежедневно, в 21:00, проводится вечерняя поверка»","difficulty":"1"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-022', NULL, 'simple', 1, 'vu', 'ВУ, п. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как поступают постовые на время вечерней поверки?', '[{"id":"CGd79vZ","text":"Все остаются на постах, построение проходит без постовых"},{"id":"7TqkoeZ","text":"Все покидают посты; на КПП№1 и КПП№2 может остаться один постовой"},{"id":"iP9rDsAH","text":"Покидают посты все, кроме постовых КПП и вышек"},{"id":"gsOsy49","text":"Покидают посты все, кроме дежурного по части и его помощника"}]', '["7TqkoeZ"]', '', 2, 230, '{"meta":{"article":"ВУ, п. 4.3","explanation":"ВУ, п. 4.3: «На время проведения вечерней поверки все постовые, в том числе дежурные обязаны покинуть свой пост. На постах КПП№1, КПП№2 допускается остаться одному постовому.»","quote":"«На время проведения вечерней поверки все постовые, в том числе дежурные обязаны покинуть свой пост. На постах КПП№1, КПП№2 допускается остаться одному постовому.»","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-023', NULL, 'full', 2, 'vu', 'ВУ, п. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто может сместить время вечерней поверки?', '[{"id":"xYpAQ3g5","text":"Любой офицер, находящийся в части на момент поверки"},{"id":"fZuk1T7","text":"Военный комендант по согласованию с дежурным по части"},{"id":"2lDN1lMb","text":"Исключительно командир бригады либо его заместители"},{"id":"SPBMIZzf","text":"Командир подразделения — для личного состава своего подразделения"}]', '["2lDN1lMb"]', '', 2, 240, '{"meta":{"article":"ВУ, п. 4.3","explanation":"ВУ, п. 4.3: «Вечерняя поверка может быть смещена исключительно по решению командира бригады либо его заместителей.»","quote":"«Вечерняя поверка может быть смещена исключительно по решению командира бригады либо его заместителей.»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-024', NULL, 'simple', 2, 'vu', 'ВУ, п. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-024');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как работает бригада при коде-4, военном или чрезвычайном положении?', '[{"id":"8GSBR6PR","text":"Служебный день продлевается до 24:00, затем обычный режим"},{"id":"0Mg1UFn","text":"Круглосуточно, весь личный состав находится в расположении части"},{"id":"CkDQSPze","text":"В расположении остаются только ВП и ССО, остальные — по графику"},{"id":"BEwzgQT","text":"В обычном режиме, но увольнительные отменяются"}]', '["0Mg1UFn"]', '', 2, 250, '{"meta":{"article":"ВУ, п. 4.5","explanation":"ВУ, п. 4.5: «бригада переходит в круглосуточный режим работы, весь личный состав находится в расположении части»","quote":"«бригада переходит в круглосуточный режим работы, весь личный состав находится в расположении части»","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-025', NULL, 'medium', 2, 'vu', 'ВУ, п. 4.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Выберите верные правила увольнительной (п. 4.6).', '[{"id":"63P1d89W","text":"Право — со звания ефрейтор"},{"id":"HnfKuRyJ","text":"Раз в сутки, 60 минут"},{"id":"wFYFXKH","text":"Можно разбить на две части по 30 минут"},{"id":"GsnXI6MG","text":"Нельзя брать во время начала вечерней поверки и за 30 минут до и после неё"},{"id":"CtCDcpR","text":"Можно разбить на четыре части по 15 минут"}]', '["63P1d89W","HnfKuRyJ","wFYFXKH","GsnXI6MG"]', '', 2, 260, '{"meta":{"article":"ВУ, п. 4.6","explanation":"ВУ, п. 4.6: «Военнослужащие с звания Ефрейтор имеют право на увольнительную раз в сутки длительностью 60 минут, за исключением времени начала вечерней поверки, а также за 30 минут до и после неё. Увольнительную допускается разбить на две части по 30 минут.»","quote":"«Военнослужащие с звания Ефрейтор имеют право на увольнительную раз в сутки длительностью 60 минут, за исключением времени начала вечерней поверки, а также за 30 минут до и после неё. Увольнительную допускается разбить на две части по 30 минут.»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-026', NULL, 'vp', 2, 'vu', 'ВУ, п. 4.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'С какого звания военнослужащие могут покидать часть по личным делам вне увольнительного времени с устного разрешения Командира бригады?', '[{"id":"FGKlKlko","text":"С майора"},{"id":"vEPFGQui","text":"С подполковника"},{"id":"bDz1dv3","text":"С полковника"},{"id":"z9FN9Ta","text":"С генерал-майора"}]', '["vEPFGQui"]', '', 3, 270, '{"meta":{"article":"ВУ, п. 4.6","explanation":"ВУ, п. 4.6: «Военнослужащие со звания Подполковник обязуются соблюдать круглосуточный режим работы, имеют ненормированный служебный день и могут покидать территорию воинской части по личным делам вне служебной формы независимо от увольнительного времени с устного разрешения Командира бригады.»","quote":"«Военнослужащие со звания Подполковник обязуются соблюдать круглосуточный режим работы, имеют ненормированный служебный день и могут покидать территорию воинской части по личным делам вне служебной формы независимо от увольнительного времени с устного разрешения Командира бригады.»","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-027', NULL, 'full', 3, 'vu', 'ВУ, п. 4.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте звание и право покинуть часть после окончания служебного дня (без особых согласований).', '[]', '[]', '', 1, 280, '{"meta":{"article":"ВУ, п. 4.7; 4.8","explanation":"ВУ, п. 4.7; 4.8: «Военнослужащие до звания Сержант (включительно) не имеют права покидать территорию воинской части по окончании служебного дня.» «После окончания служебного дня военнослужащим со звания Старший сержант и имеющим военный билет разрешено покидать территорию воинской части с соблюдением служебного графика.»","quote":"«Военнослужащие до звания Сержант (включительно) не имеют права покидать территорию воинской части по окончании служебного дня.» … «После окончания служебного дня военнослужащим со звания Старший сержант и имеющим военный билет разрешено покидать территорию воинской части с соблюдением служебного графика.»","difficulty":"1"},"pairs":[{"l":{"id":"KQn5tiLG","text":"Сержант"},"r":{"id":"hLHcP87","text":"не имеет права"}},{"l":{"id":"pQ42DZ3N","text":"Старший сержант с военным билетом"},"r":{"id":"1lJrIwEE","text":"разрешено с соблюдением служебного графика"}},{"l":{"id":"H0ViZ53","text":"Ефрейтор"},"r":{"id":"hLHcP87","text":"не имеет права"}}],"distractors":[],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-028', NULL, 'simple', 1, 'vu', 'ВУ, п. 4.7; 4.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-028');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Рядовые участвуют в тренировке за территорией части. При каком условии им можно выйти?', '[{"id":"gjEG5Ol","text":"Нельзя ни при каких условиях до окончания служебного дня"},{"id":"QsX6wfC","text":"Только в сопровождении организатора тренировочных мероприятий"},{"id":"nVhQFRka","text":"Самостоятельно, если предварительно доложили об этом в рацию"},{"id":"5oQhCVNu","text":"Только на служебном транспорте и с разрешения дежурного по части"}]', '["QsX6wfC"]', '', 2, 290, '{"meta":{"article":"ВУ, п. 4.7","explanation":"ВУ, п. 4.7: «При организации тренировочных мероприятий за территорией воинской части допускается покинуть территорию только в сопровождении организатора тренировочных мероприятий.»","quote":"«При организации тренировочных мероприятий за территорией воинской части допускается покинуть территорию только в сопровождении организатора тренировочных мероприятий.»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-029', NULL, 'simple', 2, 'vu', 'ВУ, п. 4.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На сколько дней (максимум) раз в месяц положен гарантированный отпуск старшему сержанту и выше с военным билетом?', '[]', '[]', '', 1, 300, '{"meta":{"article":"ВУ, п. 4.9","explanation":"ВУ, п. 4.9: «имеют право на гарантированный отпуск длительностью не более 7 дней раз в месяц по усмотрению руководства.»","quote":"«имеют право на гарантированный отпуск длительностью не более 7 дней раз в месяц по усмотрению руководства.»","difficulty":"1"},"answer":7,"tolerance":0,"unit":""}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-030', NULL, 'medium', 1, 'vu', 'ВУ, п. 4.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто может одобрить отпуск на любое количество дней в случае семейных обстоятельств?', '[{"id":"KMvoxHsT","text":"Начальник штаба воинской части"},{"id":"7OmKGuA","text":"Заместитель командира бригады"},{"id":"FropOzR","text":"Командир бригады"},{"id":"dEcJSdDx","text":"Военный комендант"},{"id":"MCGY97FP","text":"Командир батальона ВП"}]', '["KMvoxHsT","7OmKGuA","FropOzR"]', '', 2, 310, '{"meta":{"article":"ВУ, п. 4.9","explanation":"ВУ, п. 4.9: «в случае семейных обстоятельств каждый может написать отпуск на любое количество дней с одобрения Начальника штаба воинской части, Заместителя командира бригады, Командира бригады.»","quote":"«в случае семейных обстоятельств каждый может написать отпуск на любое количество дней с одобрения Начальника штаба воинской части, Заместителя командира бригады, Командира бригады.»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-031', NULL, 'medium', 2, 'vu', 'ВУ, п. 4.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Где предоставляется перерыв для отдыха и питания (60 минут)?', '[{"id":"VggtDfr","text":"казарма"},{"id":"qu10MFXD","text":"раздевалка"},{"id":"ptlG5zCn","text":"военный госпиталь"},{"id":"VA2TZ907","text":"плац"},{"id":"ByuApXsS","text":"КПП №1"}]', '["VggtDfr","qu10MFXD","ptlG5zCn"]', '', 1, 320, '{"meta":{"article":"ВУ, п. 4.10","explanation":"ВУ, п. 4.10: «Перерыв предоставляется в специально отведенных местах: казарма, раздевалка, военный госпиталь.»","quote":"«Перерыв предоставляется в специально отведенных местах: казарма, раздевалка, военный госпиталь.»","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-032', NULL, 'full', 1, 'vu', 'ВУ, п. 4.10', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-032');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник не выполнил норму, но оставил недельный отчёт. Что он получит?', '[{"id":"fxrkYZt","text":"Ничего"},{"id":"EnwfA3QE","text":"Только премию"},{"id":"fEd0qFcp","text":"Премию и дополнительную премию"},{"id":"D0xlWW0g","text":"Выговор"}]', '["EnwfA3QE"]', '', 1, 330, '{"meta":{"article":"ВУ, п. 4.12","explanation":"ВУ, п. 4.12: «Не выполнив норму, но оставив отчёт, сотрудник получит только премию.»","quote":"«Не выполнив норму, но оставив отчёт, сотрудник получит только премию.»","difficulty":"1"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-033', NULL, 'simple', 1, 'vu', 'ВУ, п. 4.12', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кому подают еженедельный отчёт на премирование майоры и подполковники?', '[{"id":"au72pMv2","text":"Командиру подразделения"},{"id":"lus9YIcE","text":"Лично Командиру бригады"},{"id":"ScHGhOU","text":"Помощнику командира бригады"},{"id":"Qy2FFwk","text":"В Отдел кадровой работы"}]', '["lus9YIcE"]', '', 2, 340, '{"meta":{"article":"ВУ, п. 4.11","explanation":"ВУ, п. 4.11: «Сотрудники со звания Майор, Подполковник обязаны подавать еженедельный отчёт на премирование лично Командиру бригады.»","quote":"«Сотрудники со звания Майор, Подполковник обязаны подавать еженедельный отчёт на премирование лично Командиру бригады.»","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-034', NULL, 'full', 2, 'vu', 'ВУ, п. 4.11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой орган является высшим надзорным органом внутри бригады?', '[{"id":"CDaYeuiT","text":"Штаб бригады во главе с начальником штаба"},{"id":"GdqUfh5","text":"Главное управление военной полиции (ГУ ВП)"},{"id":"DxbuHqTD","text":"Отдел кадровой работы и делопроизводства"},{"id":"WQCBJJ49","text":"Военная комендатура как отдельный орган"}]', '["GdqUfh5"]', '', 1, 350, '{"meta":{"article":"ВУ, п. 5.1","explanation":"ВУ, п. 5.1: «Высшим надзорным органом внутри бригады является Главное управление военной полиции (далее — ГУ ВП).»","quote":"«Высшим надзорным органом внутри бригады является Главное управление военной полиции (далее — ГУ ВП).»","difficulty":"1"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-035', NULL, 'simple', 1, 'vu', 'ВУ, п. 5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие полномочия ГУ ВП названы в п. 5.2?', '[{"id":"j96cyCw","text":"привлечение военнослужащих к дисциплинарной ответственности"},{"id":"oRR2Lhe","text":"внесение отметок в личные дела"},{"id":"UMCYXJ6x","text":"возбуждение и проведение расследований"},{"id":"sPHWJHD","text":"формирование материалов дела для отправки в судебные органы"},{"id":"LBCG9K0w","text":"присвоение внеочередных званий"}]', '["j96cyCw","oRR2Lhe","UMCYXJ6x","sPHWJHD"]', '', 2, 360, '{"meta":{"article":"ВУ, п. 5.2","explanation":"ВУ, п. 5.2: «на привлечение военнослужащих к дисциплинарной ответственности, внесение определенных отметок в личные дела военнослужащих, возбуждение и проведение расследований, формирование контрольного дела, формирование материалов дела для последующей их отправки в судебные органы.»","quote":"«на привлечение военнослужащих к дисциплинарной ответственности, внесение определенных отметок в личные дела военнослужащих, возбуждение и проведение расследований, формирование контрольного дела, формирование материалов дела для последующей их отправки в судебные органы.»","difficulty":"2"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-036', NULL, 'simple', 2, 'vu', 'ВУ, п. 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-036');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие меры обеспечения производства по материалам о проступке перечислены в п. 5.4?', '[{"id":"u23lj1Tu","text":"задержание"},{"id":"lwvV3PUa","text":"доставление"},{"id":"FTMmuds","text":"личный досмотр, досмотр вещей и транспорта"},{"id":"oAVMXO8Y","text":"временное отстранение от обязанностей"},{"id":"OA0pcMJe","text":"казарменное положение на время служебной проверки"},{"id":"OKEWi3us","text":"лишение премии"}]', '["u23lj1Tu","lwvV3PUa","FTMmuds","oAVMXO8Y","OA0pcMJe"]', '', 2, 370, '{"meta":{"article":"ВУ, п. 5.4","explanation":"ВУ, п. 5.4: «а) задержание;» «б) доставление;» «г) личный досмотр, досмотр вещей, находящихся при военнослужащем, досмотр личного и служебного транспортного средства военнослужащего;» «д) временное отстранение от исполнения служебных и должностных обязанностей;» «(далее — казарменное положение)»","quote":"«а) задержание;» … «б) доставление;» … «г) личный досмотр, досмотр вещей, находящихся при военнослужащем, досмотр личного и служебного транспортного средства военнослужащего;» … «д) временное отстранение от исполнения служебных и должностных обязанностей;» … «(далее — казарменное положение)»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-037', NULL, 'medium', 2, 'vu', 'ВУ, п. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что означает «казарменное положение» по ВУ?', '[{"id":"w0oOH1LD","text":"Запрет выходить из казармы до окончания служебного дня"},{"id":"9YeqOX2H","text":"Запрет подозреваемому покидать территорию части на время служебной проверки"},{"id":"Rjk7B8me","text":"Обязанность ночевать в казарме в течение срока взыскания"},{"id":"bvKtbp0","text":"Дисциплинарный арест с содержанием на гауптвахте до решения"}]', '["9YeqOX2H"]', '', 2, 380, '{"meta":{"article":"ВУ, п. 5.4","explanation":"ВУ, п. 5.4: «на время проведения служебной проверки подозреваемый может быть ограничен в передвижении в виде запрета покидать территорию воинской части (далее — казарменное положение).»","quote":"«на время проведения служебной проверки подозреваемый может быть ограничен в передвижении в виде запрета покидать территорию воинской части (далее — казарменное положение).»","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-038', NULL, 'vp', 2, 'vu', 'ВУ, п. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-038');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Командир роты применил к подчинённому задержание (мера п. 5.4). Что он обязан сделать?', '[{"id":"nNEKBy5m","text":"Ничего — это право командира в пределах его полномочий"},{"id":"P7H8lMgH","text":"Письменно доложить об этом Военному коменданту"},{"id":"VoPf7ABQ","text":"Получить на это разрешение командира бригады"},{"id":"QZcSVTSL","text":"Устно сообщить об этом дежурному по части в рацию"}]', '["P7H8lMgH"]', '', 3, 390, '{"meta":{"article":"ВУ, п. 5.5","explanation":"ВУ, п. 5.5: «з) командиры (начальники) подразделений, рот, батальонов, соединений, письменно доложив об этом Военному коменданту.»","quote":"«з) командиры (начальники) подразделений, рот, батальонов, соединений, письменно доложив об этом Военному коменданту.»","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-039', NULL, 'medium', 3, 'vu', 'ВУ, п. 5.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-039');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие виды дисциплинарных взысканий установлены ВУ (иные недопустимы)?', '[{"id":"WCBBDjpm","text":"предупреждение (замечание)"},{"id":"wdMS7YmL","text":"дисциплинарный арест не более 30 минут"},{"id":"CPvJF3qr","text":"выговор"},{"id":"Wa8iDO","text":"увольнение с занимаемой должности"},{"id":"1mLvzrkK","text":"лишение премии"}]', '["WCBBDjpm","wdMS7YmL","CPvJF3qr","Wa8iDO"]', '', 1, 400, '{"meta":{"article":"ВУ, п. 5.6","explanation":"ВУ, п. 5.6: «а) предупреждение (замечание);\n\nб) дисциплинарный арест, не превышающий срок 30 минут;\n\nв) выговор;\n\nг) увольнение с занимаемой должности.»","quote":"«а) предупреждение (замечание); … б) дисциплинарный арест, не превышающий срок 30 минут; … в) выговор; … г) увольнение с занимаемой должности.»","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-040', NULL, 'medium', 1, 'vu', 'ВУ, п. 5.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-040');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько предупреждений (замечаний) приравниваются к одному выговору?', '[]', '[]', '', 1, 410, '{"meta":{"article":"ВУ, п. 5.6","explanation":"ВУ, п. 5.6: «три предупреждения (замечания) приравниваются к одному выговору, три выговора влекут увольнение с занимаемой должности.»","quote":"«три предупреждения (замечания) приравниваются к одному выговору, три выговора влекут увольнение с занимаемой должности.»","difficulty":"1"},"answer":3,"tolerance":0,"unit":""}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-041', NULL, 'full', 1, 'vu', 'ВУ, п. 5.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-041');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как снимается выговор?', '[{"id":"qvIV0ONH","text":"Автоматически через сутки после выдачи, если за это время не было новых нарушений"},{"id":"19iKSXmV","text":"После отработки в канале спец. связи либо, в исключительных случаях, по решению Командира бригады и его заместителей"},{"id":"LItymrk","text":"Только по решению Военного коменданта после отработки, но не ранее чем через семь дней с момента выдачи"},{"id":"A14Cb2P9","text":"По рапорту командира подразделения на имя Военного коменданта с приложением характеристики военнослужащего"}]', '["19iKSXmV"]', '', 2, 420, '{"meta":{"article":"ВУ, п. 5.8","explanation":"ВУ, п. 5.8: «Снятие выговора производится после отработки выговора в отдельном канале спец. связи, либо в исключительных случаях по решению Командира бригады и его заместителей.»","quote":"«Снятие выговора производится после отработки выговора в отдельном канале спец. связи, либо в исключительных случаях по решению Командира бригады и его заместителей.»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-042', NULL, 'simple', 2, 'vu', 'ВУ, п. 5.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-042');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда ГУ ВП назначает более строгий вид наказания?', '[{"id":"AUeMk0o6","text":"Всегда при повторном нарушении в течение одних суток"},{"id":"GFrPTQfY","text":"Только если менее строгие виды не обеспечат достижение целей наказания"},{"id":"iyEaX","text":"По письменному ходатайству командира подразделения нарушителя"},{"id":"tJO19PYB","text":"Если нарушитель старше по званию, чем сотрудник, выявивший нарушение"}]', '["GFrPTQfY"]', '', 3, 430, '{"meta":{"article":"ВУ, п. 5.9","explanation":"ВУ, п. 5.9: «Более строгий вид наказания назначается только в случае, если менее строгие виды наказания не смогут обеспечить достижение целей наказания.»","quote":"«Более строгий вид наказания назначается только в случае, если менее строгие виды наказания не смогут обеспечить достижение целей наказания.»","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-043', NULL, 'vp', 3, 'vu', 'ВУ, п. 5.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-043');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие санкции накладываются на военнослужащего при получении взыскания?', '[{"id":"A3DxVgm","text":"запрет на отгул"},{"id":"yDjor8xW","text":"запрет на повышение до снятия выговора"},{"id":"PY659nFx","text":"ограничение на взятие предметов со склада"},{"id":"azFLsy1","text":"запрет на увольнение/перевод"},{"id":"8ReDdJl4","text":"запрет на получение или обновление военного билета до снятия выговора"},{"id":"WxfzqU6p","text":"запрет на участие в вечерней поверке"}]', '["A3DxVgm","yDjor8xW","PY659nFx","azFLsy1","8ReDdJl4"]', '', 2, 440, '{"meta":{"article":"ВУ, п. 5.11","explanation":"ВУ, п. 5.11: «а) запрет на отгул;\n\nб) запрет на повышение до снятия выговора;\n\nв) ограничение на взятие предметов со склада;\n\nг) запрет на увольнение/перевод;\n\nд) запрет на получение или обновление военного билета до снятия выговора.»","quote":"«а) запрет на отгул; … б) запрет на повышение до снятия выговора; … в) ограничение на взятие предметов со склада; … г) запрет на увольнение/перевод; … д) запрет на получение или обновление военного билета до снятия выговора.»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-044', NULL, 'medium', 2, 'vu', 'ВУ, п. 5.11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-044');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте правило и срок.', '[]', '[]', '', 1, 450, '{"meta":{"article":"ВУ, п. 5.12; 5.14","explanation":"ВУ, п. 5.12; 5.14: «Дисциплинарное взыскание может быть применено не позже, чем через 48 часов с момента ситуации.» «Через 7 дней после получения дисциплинарного взыскания и, если более не было получения взысканий, взыскание считается снятым.»","quote":"«Дисциплинарное взыскание может быть применено не позже, чем через 48 часов с момента ситуации.» … «Через 7 дней после получения дисциплинарного взыскания и, если более не было получения взысканий, взыскание считается снятым.»","difficulty":"1"},"pairs":[{"l":{"id":"3WMDNs4T","text":"Предельный срок применения взыскания с момента ситуации"},"r":{"id":"a35wlco","text":"48 часов"}},{"l":{"id":"mxQmGrYP","text":"Срок, после которого взыскание считается снятым (если не было новых)"},"r":{"id":"QL72JCVJ","text":"7 дней"}}],"distractors":[],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-045', NULL, 'simple', 1, 'vu', 'ВУ, п. 5.12; 5.14', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-045');
