INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте роль в отношении ГУ ВП и должность.', '[]', '[]', '', 1, 470, '{"meta":{"article":"ВУ, п. 6.38; 6.39","explanation":"ВУ, п. 6.38; 6.39: «Куратором и прямым начальником ГУ ВП является Первый заместитель командира бригады.» «Руководителем ГУ ВП является Военный комендант гарнизона.»","quote":"«Куратором и прямым начальником ГУ ВП является Первый заместитель командира бригады.» … «Руководителем ГУ ВП является Военный комендант гарнизона.»","difficulty":"1"},"pairs":[{"l":{"id":"s2D5zPNQ","text":"Куратор и прямой начальник ГУ ВП"},"r":{"id":"WabieKh6","text":"Первый заместитель командира бригады"}},{"l":{"id":"jB5P2rY6","text":"Руководитель ГУ ВП"},"r":{"id":"pdj5pHq","text":"Военный комендант гарнизона"}}],"distractors":[],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-047', NULL, 'simple', 1, 'vu', 'ВУ, п. 6.38; 6.39', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-047');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие подразделения входят в ГУ ВП?', '[{"id":"TDp9lZIO","text":"Военная комендатура"},{"id":"bPlUzpsr","text":"Батальон военной полиции"},{"id":"igEKKFxJ","text":"Силы специальных операций"},{"id":"kmAdeJb","text":"Рота охраны и обеспечения"}]', '["TDp9lZIO","bPlUzpsr"]', '', 1, 480, '{"meta":{"article":"ВУ, п. 6.40","explanation":"ВУ, п. 6.40: «контролирует работу входящих в него подразделений — Военной комендатуры и Батальона военной полиции.»","quote":"«контролирует работу входящих в него подразделений — Военной комендатуры и Батальона военной полиции.»","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-048', NULL, 'medium', 1, 'vu', 'ВУ, п. 6.40', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-048');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто, помимо Командира бригады и его заместителей, имеет исключительное право на составление, выдачу, исполнение и контроль дисциплинарных взысканий в отношении всех военнослужащих бригады?', '[{"id":"5ZT1FOrN","text":"Командиры подразделений в отношении своего личного состава"},{"id":"OBR9crzW","text":"ГУ ВП в лице Военной комендатуры и Батальона военной полиции"},{"id":"1IU5qRQH","text":"Отдел кадровой работы совместно с начальником штаба"},{"id":"dYO2EW41","text":"Начальник штаба бригады и дежурный по части"}]', '["OBR9crzW"]', '', 2, 490, '{"meta":{"article":"ВУ, п. 6.42","explanation":"ВУ, п. 6.42: «Главное управление военной полиции в лице Военной комендатуры и Батальона военной полиции имеет исключительное право (помимо Командира бригады и его заместителей) на составление, выдачу, исполнение и контроль дисциплинарных взысканий»","quote":"«Главное управление военной полиции в лице Военной комендатуры и Батальона военной полиции имеет исключительное право (помимо Командира бригады и его заместителей) на составление, выдачу, исполнение и контроль дисциплинарных взысканий»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-049', NULL, 'simple', 2, 'vu', 'ВУ, п. 6.42', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-049');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кем могут быть скорректированы решения и действия ГУ ВП?', '[{"id":"xDHb9WH","text":"Любым офицером штаба бригады по рапорту"},{"id":"pwoZgmgf","text":"Никем, кроме Командира бригады и его заместителей"},{"id":"xGEIzPfP","text":"Командиром подразделения, в котором служит нарушитель"},{"id":"373d0KLs","text":"Военным комиссаром или начальником штаба бригады"}]', '["pwoZgmgf"]', '', 2, 500, '{"meta":{"article":"ВУ, п. 6.43","explanation":"ВУ, п. 6.43: «его решения и действия не могут быть скорректированы никем, кроме Командира бригады и его заместителей.»","quote":"«его решения и действия не могут быть скорректированы никем, кроме Командира бригады и его заместителей.»","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-050', NULL, 'medium', 2, 'vu', 'ВУ, п. 6.43', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-050');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'За что отвечает Военная комендатура (п. 6.45)?', '[{"id":"3qsCZ0","text":"рассмотрение жалоб на действия (бездействие) сотрудников ГУ ВП"},{"id":"hn3tc5bp","text":"рассмотрение рапортов на снятие дисциплинарных взысканий"},{"id":"eKmqTtCj","text":"содержание на гауптвахте военнослужащих, подвергнутых дисциплинарному аресту"},{"id":"Uv4PbyaM","text":"выдача повесток гражданам"},{"id":"JLSx7xjx","text":"проведение лекций для Военной академии"}]', '["3qsCZ0","hn3tc5bp","eKmqTtCj"]', '', 2, 510, '{"meta":{"article":"ВУ, п. 6.45","explanation":"ВУ, п. 6.45: «в) рассмотрение жалоб на действия (бездействие) сотрудников ГУ ВП;\n\nг) рассмотрение рапортов на снятие дисциплинарных взысканий;» «е) содержание военнослужащих на гауптвахте, подвергнутых дисциплинарному аресту;»","quote":"«в) рассмотрение жалоб на действия (бездействие) сотрудников ГУ ВП; … г) рассмотрение рапортов на снятие дисциплинарных взысканий;» … «е) содержание военнослужащих на гауптвахте, подвергнутых дисциплинарному аресту;»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-051', NULL, 'vp', 2, 'vu', 'ВУ, п. 6.45', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-051');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое подразделение является органом дознания бригады?', '[{"id":"YchNcPbi","text":"Военная комендатура"},{"id":"yUF6wSV","text":"Батальон военной полиции"},{"id":"ihmCmEr","text":"Силы специальных операций"},{"id":"YR5EHtu","text":"Штаб бригады"}]', '["yUF6wSV"]', '', 2, 520, '{"meta":{"article":"ВУ, п. 6.47","explanation":"ВУ, п. 6.47: «Батальон военной полиции является органом дознания 1-й Московской мотострелковой бригады»","quote":"«Батальон военной полиции является органом дознания 1-й Московской мотострелковой бригады»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-052', NULL, 'simple', 2, 'vu', 'ВУ, п. 6.47', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-052');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте должностное лицо и подразделение, работу которого оно непосредственно курирует.', '[]', '[]', '', 2, 530, '{"meta":{"article":"ВУ, п. 6.14; 6.21; 6.28","explanation":"ВУ, п. 6.14; 6.21; 6.28: «Первый заместитель командира бригады непосредственно курирует работу Сил специальных операций и Главного управления военной полиции» «непосредственно курирует работу Военного комиссариата и входящих в него отделов.» «Зам.Ком.Бриг. по МТО непосредственно курирует работу Роты охраны и обеспечения.»","quote":"«Первый заместитель командира бригады непосредственно курирует работу Сил специальных операций и Главного управления военной полиции» … «непосредственно курирует работу Военного комиссариата и входящих в него отделов.» … «Зам.Ком.Бриг. по МТО непосредственно курирует работу Роты охраны и обеспечения.»","difficulty":"2"},"pairs":[{"l":{"id":"rqbVUM8v","text":"Первый заместитель командира бригады"},"r":{"id":"UzIxwEDJ","text":"ССО и ГУ ВП"}},{"l":{"id":"ZePDJNRd","text":"Начальник штаба"},"r":{"id":"j1DvmHbL","text":"Военный комиссариат и входящие в него отделы"}},{"l":{"id":"5kMf8jp2","text":"Зам.Ком.Бриг. по МТО"},"r":{"id":"b7L5BUb7","text":"Рота охраны и обеспечения"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-053', NULL, 'medium', 2, 'vu', 'ВУ, п. 6.14; 6.21; 6.28', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-053');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Командир подразделения временно убыл, штатного заместителя нет. Кто принимает командование?', '[{"id":"TOBSflCs","text":"Самый опытный военнослужащий подразделения по выслуге лет"},{"id":"5RB35SYR","text":"Старший по должности, при равных должностях — старший по званию"},{"id":"WBXD94ZN","text":"Сотрудник ВП, назначенный Военным комендантом на время отсутствия"},{"id":"cZSf4zWn","text":"Никто: подразделение подчиняется напрямую начальнику штаба"}]', '["5RB35SYR"]', '', 2, 540, '{"meta":{"article":"ВУ, п. 6.35","explanation":"ВУ, п. 6.35: «При отсутствии штатного заместителя или если заместитель не был утвержден, командование принимает старший по должности, а при равных должностях — старший по воинскому званию.»","quote":"«При отсутствии штатного заместителя или если заместитель не был утвержден, командование принимает старший по должности, а при равных должностях — старший по воинскому званию.»","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-054', NULL, 'full', 2, 'vu', 'ВУ, п. 6.35', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-054');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте ситуацию в общении со старшим по званию и уставную фразу.', '[]', '[]', '', 1, 550, '{"meta":{"article":"ВУ, п. 8.7","explanation":"ВУ, п. 8.7: «Согласие: «Так точно»;» «Несогласие: «Никак нет»;» «Выполнение приказа: «Есть»;» «Незнание ответа на вопрос: «Не могу знать!»;» «Извинения: «Виноват, исправлюсь».»","quote":"«Согласие: «Так точно»;» … «Несогласие: «Никак нет»;» … «Выполнение приказа: «Есть»;» … «Незнание ответа на вопрос: «Не могу знать!»;» … «Извинения: «Виноват, исправлюсь».»","difficulty":"1"},"pairs":[{"l":{"id":"W0AubDB","text":"Согласие"},"r":{"id":"qnxF5Pa2","text":"«Так точно»"}},{"l":{"id":"mxIEuqzl","text":"Несогласие"},"r":{"id":"ypstygn","text":"«Никак нет»"}},{"l":{"id":"J0Pz3Pf","text":"Выполнение приказа"},"r":{"id":"HiqPrjQ","text":"«Есть»"}},{"l":{"id":"6p7KKPn","text":"Незнание ответа"},"r":{"id":"gEXZl61c","text":"«Не могу знать!»"}},{"l":{"id":"2fepr3Dn","text":"Извинение"},"r":{"id":"jXa8xt8","text":"«Виноват, исправлюсь»"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-055', NULL, 'full', 1, 'vu', 'ВУ, п. 8.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-055');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте подразделение и тег в рации.', '[]', '[]', '', 1, 560, '{"meta":{"article":"ВУ, п. 8.10","explanation":"ВУ, п. 8.10: «а) Батальон Военной полиции — [ВП] или ВП |;» «в) Рота Охраны и Обеспечения — [РОиО] или РОиО |;» «д) Медицинская рота — [МР] или МР |;» «е) Военная Академия — [ВА] или ВА |.»","quote":"«а) Батальон Военной полиции — [ВП] или ВП |;» … «в) Рота Охраны и Обеспечения — [РОиО] или РОиО |;» … «д) Медицинская рота — [МР] или МР |;» … «е) Военная Академия — [ВА] или ВА |.»","difficulty":"1"},"pairs":[{"l":{"id":"gzb9sYZS","text":"Батальон Военной полиции"},"r":{"id":"1zOevmR8","text":"[ВП]"}},{"l":{"id":"CkPDGesn","text":"Рота Охраны и Обеспечения"},"r":{"id":"Y42nakg0","text":"[РОиО]"}},{"l":{"id":"BuoKzaK1","text":"Медицинская рота"},"r":{"id":"bZ2bp8X4","text":"[МР]"}},{"l":{"id":"Dzgbu8F8","text":"Военная Академия"},"r":{"id":"feeIsdGE","text":"[ВА]"}}],"distractors":[],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-056', NULL, 'simple', 1, 'vu', 'ВУ, п. 8.10', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-056');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях тег в рации не используется?', '[{"id":"evcXkKsr","text":"Полковники и вышестоящие тегов не имеют"},{"id":"Fr1LW4MJ","text":"Доклад в наряде не требует тега"},{"id":"jHA5Mq11","text":"Рядовые ВА тегов не используют"},{"id":"jgYuzqk5","text":"Ночью теги не нужны"}]', '["evcXkKsr","Fr1LW4MJ"]', '', 2, 570, '{"meta":{"article":"ВУ, п. 8.10","explanation":"ВУ, п. 8.10: «Примечание: Полковники и вышестоящие тэгов не имеют.» «Примечание II: Доклад в наряде не требует тега.»","quote":"«Примечание: Полковники и вышестоящие тэгов не имеют.» … «Примечание II: Доклад в наряде не требует тега.»","difficulty":"2"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-057', NULL, 'simple', 2, 'vu', 'ВУ, п. 8.10', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-057');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте код и его значение.', '[]', '[]', '', 1, 580, '{"meta":{"article":"ВУ, п. 8.11","explanation":"ВУ, п. 8.11: «Код — 1: состояние стабильно, без происшествий, обстановка спокойная;» «Код — 2: скопление подозрительных личностей, нарушение общественного порядка;» «Код — 3: проникновение на территорию, вооруженное нападение, массовое нарушение общественного порядка;» «Код — 4: боевая тревога, объявляется старшим офицерским составом от звания полковник и министром обороны.»","quote":"«Код — 1: состояние стабильно, без происшествий, обстановка спокойная;» … «Код — 2: скопление подозрительных личностей, нарушение общественного порядка;» … «Код — 3: проникновение на территорию, вооруженное нападение, массовое нарушение общественного порядка;» … «Код — 4: боевая тревога, объявляется старшим офицерским составом от звания полковник и министром обороны.»","difficulty":"1"},"pairs":[{"l":{"id":"LKsBJFXq","text":"Код — 1"},"r":{"id":"mmTdnwtl","text":"состояние стабильно, без происшествий"}},{"l":{"id":"fOjcCeNv","text":"Код — 2"},"r":{"id":"5LHYmv","text":"скопление подозрительных личностей, нарушение общественного порядка"}},{"l":{"id":"yyZ8wwo8","text":"Код — 3"},"r":{"id":"5ceEred","text":"проникновение на территорию, вооружённое нападение"}},{"l":{"id":"zyYi9Sye","text":"Код — 4"},"r":{"id":"v2bUihL3","text":"боевая тревога"}}],"distractors":[],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-058', NULL, 'simple', 1, 'vu', 'ВУ, п. 8.11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-058');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте индикатор тревоги и минимальное звание, с которого он объявляется.', '[]', '[]', '', 2, 590, '{"meta":{"article":"ВУ, п. 8.12","explanation":"ВУ, п. 8.12: «Код Синий — всеобщее построение, на которое должны явиться все свободные военнослужащие. Объявляется с Майора.» «Код Красный запрос помощи — объявляется при срочной и необходимой помощи. Объявляется с Прапорщика.» «Код Красный общий — запрос помощи от государственных структур. Объявляется с Майора.»","quote":"«Код Синий — всеобщее построение, на которое должны явиться все свободные военнослужащие. Объявляется с Майора.» … «Код Красный запрос помощи — объявляется при срочной и необходимой помощи. Объявляется с Прапорщика.» … «Код Красный общий — запрос помощи от государственных структур. Объявляется с Майора.»","difficulty":"2"},"pairs":[{"l":{"id":"llzVMmv9","text":"Код Синий (всеобщее построение)"},"r":{"id":"Mdemc6Ds","text":"Майор"}},{"l":{"id":"aS2xRwbk","text":"Код Красный запрос помощи"},"r":{"id":"jJ1kMm2R","text":"Прапорщик"}},{"l":{"id":"tmuVyAlr","text":"Код Красный общий"},"r":{"id":"Mdemc6Ds","text":"Майор"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-059', NULL, 'medium', 2, 'vu', 'ВУ, п. 8.12', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-059');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Где на территории части разрешено пользоваться мобильной связью (кроме случаев обязательного и незамедлительного использования)?', '[{"id":"6TBFZr2","text":"в помещении казармы"},{"id":"faZSI5tV","text":"в гардеробе"},{"id":"GL52CQW5","text":"на построении, если оно затянулось"},{"id":"VjKFwCgn","text":"на посту КПП"}]', '["6TBFZr2","faZSI5tV"]', '', 2, 600, '{"meta":{"article":"ВУ, п. 9.32","explanation":"ВУ, п. 9.32: «Пользоваться средствами мобильной связи на территории Войсковой части, за исключением помещений казармы, гардероба либо в случаях, требующих обязательное и незамедлительное использование средств мобильной связи.»","quote":"«Пользоваться средствами мобильной связи на территории Войсковой части, за исключением помещений казармы, гардероба либо в случаях, требующих обязательное и незамедлительное использование средств мобильной связи.»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-060', NULL, 'vp', 2, 'vu', 'ВУ, п. 9.32', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-060');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как действуют военнослужащие ВК и ВА при объявлении кода-3?', '[{"id":"3h7GmfGq","text":"Прибывают первыми на место объявления кода, берут его под охрану и докладывают в рацию"},{"id":"lGY3qSy","text":"Не прибывают на объявление кода (кроме приказа старшего офицерского состава, Командира бригады и его заместителей)"},{"id":"IHU8IZgr","text":"Занимают вышки и посты КПП и остаются на них до отмены кода по приказу дежурного по части"},{"id":"9SXlej1M","text":"Строятся на плацу и ожидают распоряжения дежурного по части или Военного коменданта о выдвижении"}]', '["lGY3qSy"]', '', 2, 610, '{"meta":{"article":"ВУ, п. 10.17","explanation":"ВУ, п. 10.17: «а) на объявление кода не прибывают.\n\nИсключение: получение приказа от старшего офицерского состава, Командира бригады и его заместителей.»","quote":"«а) на объявление кода не прибывают. … Исключение: получение приказа от старшего офицерского состава, Командира бригады и его заместителей.»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-061', NULL, 'simple', 2, 'vu', 'ВУ, п. 10.17', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-061');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расставьте действия ВП при объявлении военного положения в порядке п. 10.7.', '[]', '[]', '', 2, 620, '{"meta":{"article":"ВУ, п. 10.7","explanation":"ВУ, п. 10.7: «а) назначить оперативного дежурного, который будет оставаться на территории части и будет оперативно доставлять информацию об изменениях;» «б) остальные военнослужащие из состава ВП выдвигаются в патрулирование в близлежащих районах войсковой части, стратегических объектов;» «в) ожидать дальнейших инструкций от начальника подразделения.»","quote":"«а) назначить оперативного дежурного, который будет оставаться на территории части и будет оперативно доставлять информацию об изменениях;» … «б) остальные военнослужащие из состава ВП выдвигаются в патрулирование в близлежащих районах войсковой части, стратегических объектов;» … «в) ожидать дальнейших инструкций от начальника подразделения.»","difficulty":"2"},"items":[{"id":"9gJ9rccB","text":"назначить оперативного дежурного, который остаётся на территории части"},{"id":"WogZnN0","text":"остальные военнослужащие ВП выдвигаются в патрулирование близлежащих районов и стратегических объектов"},{"id":"Hg7AGZNI","text":"ожидать дальнейших инструкций от начальника подразделения"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-062', NULL, 'medium', 2, 'vu', 'ВУ, п. 10.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-062');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Ефрейтор в будний день в 20:45 просит у КПП выпустить его в увольнительную на 60 минут. Сегодня он ещё не брал увольнительную.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сержант в 22:15 в будний день пытается выехать за территорию части, ссылаясь на то, что «рабочий день закончился». Согласования высшего офицерского состава нет.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: На построение пришёл младший лейтенант с щетиной, причёской длиной около 3 см и серебряной цепочкой на шее. На руке — наручные часы.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир роты задержал подчинённого, подозреваемого в выносе имущества со склада, и сам объявил ему «казарменное положение» на время служебной проверки. Коменданту он ничего не сообщил.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Объявлен код-3: проникновение на территорию части. Нарушитель на автомобиле. На месте есть сотрудники ВП, ССО и РОиО; курсанты ВА хотят «помочь».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Рядовой получил выговор. Через 3 дня он просит отгул, хочет перевестись в ССО и подать рапорт на повышение.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин с татуировкой на шее и непогашенной судимостью пришёл на призыв. Сотрудник призыва готов принять его, «раз он хочет служить».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Объявлено военное положение. Сотрудник РОиО остаётся в повседневной форме, сотрудник ВП весь состав увёл в патруль, не оставив никого в части.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие меры входят в закрытый перечень дисциплинарных взысканий?', '[{"id":"S8ygzIEN","text":"предупреждение (замечание)"},{"id":"R4Icn5MZ","text":"понижение в звании"},{"id":"kQSKFomf","text":"выговор"},{"id":"NmfddsG0","text":"денежный штраф"},{"id":"W3jPU4uk","text":"дисциплинарный арест (гауптвахта)"},{"id":"STJMwpy0","text":"увольнение по соответствующему основанию"}]', '["S8ygzIEN","kQSKFomf","W3jPU4uk","STJMwpy0"]', '', 1, 710, '{"meta":{"article":"ДУ, п. 2.1","explanation":"ДУ, п. 2.1: «Закрытый перечень дисциплинарных взысканий:» «• предупреждение (замечание);\n• выговор;\n• дисциплинарный арест (гауптвахта)» «• увольнение по соответствующему основанию.»","quote":"«Закрытый перечень дисциплинарных взысканий:» … «• предупреждение (замечание); … • выговор; … • дисциплинарный арест (гауптвахта)» … «• увольнение по соответствующему основанию.»","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-001', NULL, 'medium', 1, 'du', 'ДУ, п. 2.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в минутах) может быть назначен дисциплинарный арест?', '[]', '[]', '', 1, 720, '{"meta":{"article":"ДУ, п. 2.1","explanation":"ДУ, п. 2.1: «только в отношении военнослужащих ВС РФ и на срок не более 30 минут»","quote":"«только в отношении военнослужащих ВС РФ и на срок не более 30 минут»","difficulty":"1"},"answer":30,"tolerance":0,"unit":""}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-002', NULL, 'full', 1, 'du', 'ДУ, п. 2.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Может ли лишение должности быть назначено как дисциплинарное взыскание по ДУ?', '[{"id":"uGMRwfGw","text":"Да, как более мягкая альтернатива увольнению из части за проступок"},{"id":"ctSh23qA","text":"Да, но назначить его в качестве взыскания может только Командир бригады"},{"id":"8lmCBCxH","text":"Нет — без самостоятельного нормативного основания это не дисциплинарное взыскание"},{"id":"gdzKZlQ2","text":"Да, если нарушение совершено повторно в течение одной недели"}]', '["8lmCBCxH"]', '', 1, 730, '{"meta":{"article":"ДУ, п. 2.2","explanation":"ДУ, п. 2.2: «Понижение в звании, лишение должности, денежный штраф, запрет пользоваться имуществом и иные меры не могут называться дисциплинарным взысканием без самостоятельного нормативного основания.»","quote":"«Понижение в звании, лишение должности, денежный штраф, запрет пользоваться имуществом и иные меры не могут называться дисциплинарным взысканием без самостоятельного нормативного основания.»","difficulty":"1"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-003', NULL, 'simple', 1, 'du', 'ДУ, п. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Одним действием военнослужащий нарушил сразу несколько норм. Как поступают по ДУ?', '[{"id":"Q1XsiCML","text":"Назначают отдельное взыскание за каждую нарушенную норму"},{"id":"bFU1kV8W","text":"Определяют основной состав; несколько взысканий — только за отделимые эпизоды"},{"id":"lJObppNo","text":"Назначают самое строгое взыскание из всех составов плюс предупреждение"},{"id":"9DxdqSFz","text":"Передают материал Командиру бригады для выбора одной нормы"}]', '["bFU1kV8W"]', '', 2, 740, '{"meta":{"article":"ДУ, п. 1.6","explanation":"ДУ, п. 1.6: «Если одним действием нарушено несколько норм, определяется основной состав; несколько взысканий возможны только за самостоятельные, отделимые друг от друга эпизоды.»","quote":"«Если одним действием нарушено несколько норм, определяется основной состав; несколько взысканий возможны только за самостоятельные, отделимые друг от друга эпизоды.»","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-004', NULL, 'full', 2, 'du', 'ДУ, п. 1.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Не позднее скольких часов с момента совершения проступка должно быть применено дисциплинарное взыскание (кроме применяемого по решению суда)?', '[]', '[]', '', 1, 750, '{"meta":{"article":"ДУ, п. 1.7","explanation":"ДУ, п. 1.7: «Дисциплинарное взыскание должно быть применено не позднее 48 часов с момента совершения проступка, кроме взыскания, применяемого по решению суда.»","quote":"«Дисциплинарное взыскание должно быть применено не позднее 48 часов с момента совершения проступка, кроме взыскания, применяемого по решению суда.»","difficulty":"1"},"answer":48,"tolerance":0,"unit":""}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-005', NULL, 'simple', 1, 'du', 'ДУ, п. 1.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что по ДУ само по себе НЕ является основанием для взыскания?', '[{"id":"hzMTZ4en","text":"Конкретно установленное и подтверждённое доказательствами деяние"},{"id":"1L5ySOY9","text":"Нарушение установленного запрета, зафиксированное на бодикамеру"},{"id":"iU4B2eXT","text":"Личная неприязнь или служебный конфликт с военнослужащим"},{"id":"RyqIzYwd","text":"Ненадлежащее исполнение служебных обязанностей военнослужащим"}]', '["iU4B2eXT"]', '', 1, 760, '{"meta":{"article":"ДУ, п. 1.4","explanation":"ДУ, п. 1.4: «Предположение, личная неприязнь, служебный конфликт или отсутствие симпатии к военнослужащему сами по себе основанием взыскания не являются.»","quote":"«Предположение, личная неприязнь, служебный конфликт или отсутствие симпатии к военнослужащему сами по себе основанием взыскания не являются.»","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-006', NULL, 'medium', 1, 'du', 'ДУ, п. 1.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Можно ли за один и тот же проступок назначить дисциплинарный арест и выговор?', '[{"id":"JODCHKdh","text":"Да, если проступок признан грубым и такое решение мотивировано"},{"id":"Wvj1EME0","text":"Да, если так решил Военный комендант после служебной проверки"},{"id":"FWWdYUhg","text":"Нет, арест не назначается вместе с выговором за тот же проступок"},{"id":"ZBuVPqdg","text":"Да, если срок ареста не превышает десяти минут"}]', '["FWWdYUhg"]', '', 2, 770, '{"meta":{"article":"ДУ, п. 2.5","explanation":"ДУ, п. 2.5: «Арест не назначается одновременно с выговором за тот же проступок.»","quote":"«Арест не назначается одновременно с выговором за тот же проступок.»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-007', NULL, 'simple', 2, 'du', 'ДУ, п. 2.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие прямые основания для увольнения как дисциплинарной меры названы в п. 2.6?', '[{"id":"KlCKn8Ow","text":"грубый проступок, предусмотренный Уставом"},{"id":"UpUk9Q5g","text":"два действующих выговора"},{"id":"RRTcjZKL","text":"достижение трех действующих выговоров"},{"id":"eVn4VFbd","text":"иное основание, прямо предусмотренное законодательством"},{"id":"3Y6x1lX1","text":"любое повторное предупреждение"}]', '["KlCKn8Ow","RRTcjZKL","eVn4VFbd"]', '', 2, 780, '{"meta":{"article":"ДУ, п. 2.6","explanation":"ДУ, п. 2.6: «грубый проступок, предусмотренный настоящим Уставом, либо достижение трех действующих выговоров, либо иное основание, прямо предусмотренное законодательством.»","quote":"«грубый проступок, предусмотренный настоящим Уставом, либо достижение трех действующих выговоров, либо иное основание, прямо предусмотренное законодательством.»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-008', NULL, 'medium', 2, 'du', 'ДУ, п. 2.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что из перечисленного по ДУ является мерами обеспечения производства, а не взысканиями?', '[{"id":"JRvYnhN2","text":"задержание"},{"id":"j8VqDrL","text":"личный досмотр"},{"id":"KYaQp2c5","text":"выговор"},{"id":"QCKijSC","text":"временное отстранение"},{"id":"afnM66V","text":"доставление"},{"id":"naqntcB8","text":"предупреждение"}]', '["JRvYnhN2","j8VqDrL","QCKijSC","afnM66V"]', '', 2, 790, '{"meta":{"article":"ДУ, п. 2.7","explanation":"ДУ, п. 2.7: «Мерами обеспечения производства, а не взысканиями, являются: задержание, доставление, личный досмотр, досмотр вещей и транспорта, временное отстранение»","quote":"«Мерами обеспечения производства, а не взысканиями, являются: задержание, доставление, личный досмотр, досмотр вещей и транспорта, временное отстранение»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-du-009', NULL, 'vp', 2, 'du', 'ДУ, п. 2.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Для чего по ДУ применяется временное отстранение?', '[{"id":"tBVfBptk","text":"Как дополнительное наказание к выговору за тот же проступок"},{"id":"qHFgcweU","text":"Для проверки и обеспечения производства, но не как скрытое наказание"},{"id":"5R7khLlu","text":"Вместо дисциплинарного ареста, когда арест применить нельзя"},{"id":"eeiZLd33","text":"Как обязательная мера при любом выявленном проступке"}]', '["qHFgcweU"]', '', 2, 800, '{"meta":{"article":"ДУ, п. 2.8","explanation":"ДУ, п. 2.8: «Временное отстранение не должно использоваться как скрытое наказание. Оно применяется для проверки и обеспечения производства»","quote":"«Временное отстранение не должно использоваться как скрытое наказание. Оно применяется для проверки и обеспечения производства»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-010', NULL, 'simple', 2, 'du', 'ДУ, п. 2.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-010');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник выявил проступок, но не имеет полномочия на окончательное решение. Что он должен сделать?', '[{"id":"uTHk4mIk","text":"Выдать предупреждение от своего имени и доложить командиру"},{"id":"WNjVqLdi","text":"Зафиксировать нарушение и передать материал уполномоченному лицу"},{"id":"2rNnNhc","text":"Ничего не делать, раз решение принимает не он"},{"id":"30bkAFkF","text":"Сразу направить военнослужащего на гауптвахту до решения"}]', '["WNjVqLdi"]', '', 1, 810, '{"meta":{"article":"ДУ, п. 3.3","explanation":"ДУ, п. 3.3: «фиксирует нарушение и передает материал уполномоченному лицу. Самовольная выдача взыскания вне компетенции запрещена.»","quote":"«фиксирует нарушение и передает материал уполномоченному лицу. Самовольная выдача взыскания вне компетенции запрещена.»","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-011', NULL, 'full', 1, 'du', 'ДУ, п. 3.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-011');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто принимает решение об увольнении за дисциплинарное нарушение военнослужащего в звании старшины и выше?', '[{"id":"Dd5uRrlX","text":"Командир батальона военной полиции после проверки"},{"id":"GYkPDHq","text":"Военный комендант по представлению командира подразделения"},{"id":"vdCKw8u","text":"Исключительно Командир бригады или его заместители"},{"id":"mAuI8C8d","text":"Командир подразделения, в котором служит военнослужащий"}]', '["vdCKw8u"]', '', 2, 820, '{"meta":{"article":"ДУ, п. 3.4","explanation":"ДУ, п. 3.4: «Для военнослужащих от старшины и выше решение об увольнении за дисциплинарное нарушение принимается исключительно Командиром бригады или его заместителями после оценки доказательств»","quote":"«Для военнослужащих от старшины и выше решение об увольнении за дисциплинарное нарушение принимается исключительно Командиром бригады или его заместителями после оценки доказательств»","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-012', NULL, 'medium', 2, 'du', 'ДУ, п. 3.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-012');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто по ДУ вправе пересмотреть и отменить взыскание?', '[{"id":"NxNAJnCg","text":"Командир бригады"},{"id":"w5uCiw15","text":"заместители Командира бригады"},{"id":"IWoUbfEp","text":"Военный комендант"},{"id":"524i8lA6","text":"любой офицер ВП"},{"id":"xCQWtFh2","text":"командир роты нарушителя"}]', '["NxNAJnCg","w5uCiw15","IWoUbfEp"]', '', 2, 830, '{"meta":{"article":"ДУ, п. 3.5","explanation":"ДУ, п. 3.5: «Командир бригады, его заместители и Военный комендант вправе пересмотреть взыскание и отменить его»","quote":"«Командир бригады, его заместители и Военный комендант вправе пересмотреть взыскание и отменить его»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-013', NULL, 'full', 2, 'du', 'ДУ, п. 3.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расставьте стадии производства по дисциплинарному проступку в порядке главы IV.', '[]', '[]', '', 2, 840, '{"meta":{"article":"ДУ, п. 4.1; 4.2; 4.3; 4.4; 4.5; 4.6; 4.7; 4.8","explanation":"ДУ, п. 4.1; 4.2; 4.3; 4.4; 4.5; 4.6; 4.7; 4.8: «Выявление и фиксация.» «Проверка компетенции.» «Проверка срока.» «Квалификация.» «Оценка обстоятельств.» «Решение.» «Объявление и публикация.» «Учет.»","quote":"«Выявление и фиксация.» … «Проверка компетенции.» … «Проверка срока.» … «Квалификация.» … «Оценка обстоятельств.» … «Решение.» … «Объявление и публикация.» … «Учет.»","difficulty":"2"},"items":[{"id":"lxKGaadW","text":"Выявление и фиксация"},{"id":"S95rUVZ4","text":"Проверка компетенции"},{"id":"2RZf5BDO","text":"Проверка срока"},{"id":"ACd4NWv8","text":"Квалификация"},{"id":"ia44DZC4","text":"Оценка обстоятельств"},{"id":"9lGqpNKw","text":"Решение"},{"id":"UrUIHzV","text":"Объявление и публикация"},{"id":"RQRqsKFj","text":"Учет"}],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-014', NULL, 'simple', 2, 'du', 'ДУ, п. 4.1; 4.2; 4.3; 4.4; 4.5; 4.6; 4.7; 4.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-014');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что фиксируется на стадии «Выявление и фиксация»?', '[{"id":"NvLyuY1N","text":"дата, время, место"},{"id":"BLyuC1H","text":"военнослужащий"},{"id":"4R0YiYHd","text":"фактическое действие/бездействие"},{"id":"VlfvB6Rb","text":"конкретный нарушенный пункт"},{"id":"EN0byxqP","text":"мнение сослуживцев о нарушителе"}]', '["NvLyuY1N","BLyuC1H","4R0YiYHd","VlfvB6Rb"]', '', 1, 850, '{"meta":{"article":"ДУ, п. 4.1","explanation":"ДУ, п. 4.1: «Фиксируются дата, время, место, военнослужащий, фактическое действие/бездействие и конкретный нарушенный пункт.»","quote":"«Фиксируются дата, время, место, военнослужащий, фактическое действие/бездействие и конкретный нарушенный пункт.»","difficulty":"1"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-015', NULL, 'simple', 1, 'du', 'ДУ, п. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-015');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что обязательно указывается в решении о взыскании?', '[{"id":"l5TjCgiO","text":"факты"},{"id":"lJ3cM1Eu","text":"нарушенный пункт"},{"id":"HU9Uk3rw","text":"доказательства"},{"id":"xXPZlfy4","text":"выбранная мера"},{"id":"DpRtnov","text":"должностное лицо"},{"id":"vQwn6fs9","text":"срок, через который взыскание станет повторным"}]', '["l5TjCgiO","lJ3cM1Eu","HU9Uk3rw","xXPZlfy4","DpRtnov"]', '', 2, 860, '{"meta":{"article":"ДУ, п. 4.6","explanation":"ДУ, п. 4.6: «В решении указываются факты, нарушенный пункт, доказательства, выбранная мера и должностное лицо.»","quote":"«В решении указываются факты, нарушенный пункт, доказательства, выбранная мера и должностное лицо.»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-016', NULL, 'medium', 2, 'du', 'ДУ, п. 4.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Где публикуется приказ (распоряжение) о взыскании?', '[{"id":"9lSjUp09","text":"На форуме в открытом разделе, доступном всем гражданам"},{"id":"uqLhEa3q","text":"Во внутреннем канале аудита, доступном военнослужащему"},{"id":"eI8TwIMB","text":"Только в личном деле военнослужащего, без объявления ему"},{"id":"ILt6EXof","text":"Объявляется по рации части во время вечерней поверки"}]', '["uqLhEa3q"]', '', 1, 870, '{"meta":{"article":"ДУ, п. 4.7","explanation":"ДУ, п. 4.7: «Приказ (распоряжение) объявляется военнослужащему и публикуется во внутреннем канале аудита, доступном ему для ознакомления.»","quote":"«Приказ (распоряжение) объявляется военнослужащему и публикуется во внутреннем канале аудита, доступном ему для ознакомления.»","difficulty":"1"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-017', NULL, 'simple', 1, 'du', 'ДУ, п. 4.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что запрещено на стадии квалификации?', '[{"id":"YAAUcqUu","text":"Учитывать дополнительные эпизоды, выявленные при проверке"},{"id":"ziADyGog","text":"Искусственно дробить одно действие на несколько взысканий"},{"id":"R4zXLnh","text":"Устанавливать основной состав при нескольких нарушенных нормах"},{"id":"3CvoVm95","text":"Ссылаться на таблицу главы VI при выборе меры взыскания"}]', '["ziADyGog"]', '', 2, 880, '{"meta":{"article":"ДУ, п. 4.4","explanation":"ДУ, п. 4.4: «Запрещено искусственно дробить одно действие на несколько взысканий.»","quote":"«Запрещено искусственно дробить одно действие на несколько взысканий.»","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-du-018', NULL, 'vp', 2, 'du', 'ДУ, п. 4.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Отнесите обстоятельства к смягчающим (С) или отягчающим (О).', '[]', '[]', '', 2, 890, '{"meta":{"article":"ДУ, п. 5.1; 5.2","explanation":"ДУ, п. 5.1; 5.2: «Смягчающими обстоятельствами могут признаваться: первое нарушение; добровольное прекращение проступка; предотвращение или устранение последствий; содействие проверке» «положительная служебная характеристика» «совершение проступка в карауле, на посту, построении, поставке, при коде-4 или иной особой обстановке» «вовлечение подчиненных; существенные последствия; попытка скрыть нарушение или сфальсифицировать материалы»","quote":"«Смягчающими обстоятельствами могут признаваться: первое нарушение; добровольное прекращение проступка; предотвращение или устранение последствий; содействие проверке» … «положительная служебная характеристика» … «совершение проступка в карауле, на посту, построении, поставке, при коде-4 или иной особой обстановке» … «вовлечение подчиненных; существенные последствия; попытка скрыть нарушение или сфальсифицировать материалы»","difficulty":"2"},"pairs":[{"l":{"id":"T0guTdU","text":"добровольное прекращение проступка"},"r":{"id":"eNmlbQdy","text":"Смягчающим (С)"}},{"l":{"id":"1GqsAUVt","text":"совершение проступка в карауле, на посту"},"r":{"id":"6ZyKVKdt","text":"Отягчающим (О)"}},{"l":{"id":"67dFfMSg","text":"содействие проверке"},"r":{"id":"eNmlbQdy","text":"Смягчающим (С)"}},{"l":{"id":"QEa8Gbb","text":"вовлечение подчиненных"},"r":{"id":"6ZyKVKdt","text":"Отягчающим (О)"}},{"l":{"id":"Rh1yyH8q","text":"попытка скрыть нарушение"},"r":{"id":"6ZyKVKdt","text":"Отягчающим (О)"}},{"l":{"id":"gFo4S9nj","text":"положительная служебная характеристика"},"r":{"id":"eNmlbQdy","text":"Смягчающим (С)"}}],"distractors":[],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-019', NULL, 'simple', 2, 'du', 'ДУ, п. 5.1; 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как действуют смягчающие обстоятельства?', '[{"id":"je16m3xh","text":"Полностью освобождают от ответственности, если нарушение совершено впервые"},{"id":"sDV6A6T9","text":"Не отменяют основание ответственности, но позволяют выбрать менее строгую меру в диапазоне"},{"id":"syiLjpTD","text":"Снимают уже наложенное взыскание после рапорта военнослужащего на имя коменданта"},{"id":"PZvyNLs2","text":"Позволяют назначить меру ниже предупреждения или не назначать взыскание вовсе"}]', '["sDV6A6T9"]', '', 3, 900, '{"meta":{"article":"ДУ, п. 5.3","explanation":"ДУ, п. 5.3: «Смягчающие обстоятельства не отменяют прямое основание для ответственности, но позволяют выбрать менее строгую меру в установленном диапазоне.»","quote":"«Смягчающие обстоятельства не отменяют прямое основание для ответственности, но позволяют выбрать менее строгую меру в установленном диапазоне.»","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-020', NULL, 'full', 3, 'du', 'ДУ, п. 5.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-020');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что означает «повторно» в таблице главы VI?', '[{"id":"6Hq7jX9Y","text":"Любое второе нарушение за время службы"},{"id":"KCQTVO20","text":"Новое аналогичное нарушение при действующем взыскании"},{"id":"F1Ym7b","text":"Второе нарушение в течение суток"},{"id":"p3aGZXv","text":"Нарушение, совершенное в присутствии командира"}]', '["KCQTVO20"]', '', 2, 910, '{"meta":{"article":"ДУ, п. 6.0","explanation":"ДУ, п. 6.0: ««повторно» — новое аналогичное нарушение при действующем взыскании»","quote":"««повторно» — новое аналогичное нарушение при действующем взыскании»","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-021', NULL, 'medium', 2, 'du', 'ДУ, п. 6.0', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что требуется, чтобы применить графу «грубый случай»?', '[{"id":"N8coMqR","text":"Достаточно сослаться на тяжесть проступка"},{"id":"ThQ7bDH","text":"Конкретное обоснование последствий или опасности"},{"id":"aaTGehaN","text":"Наличие трёх предупреждений"},{"id":"ljcdZI1c","text":"Согласие самого военнослужащего"}]', '["ThQ7bDH"]', '', 3, 920, '{"meta":{"article":"ДУ, п. 6.0","explanation":"ДУ, п. 6.0: «Грубый случай требует конкретного обоснования последствий или опасности, а не формальной ссылки на тяжесть.»","quote":"«Грубый случай требует конкретного обоснования последствий или опасности, а не формальной ссылки на тяжесть.»","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-022', NULL, 'medium', 3, 'du', 'ДУ, п. 6.0', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте нарушение и меру «первично» по таблице главы VI.', '[]', '[]', '', 2, 930, '{"meta":{"article":"ДУ, п. 6.1; 6.2; 6.11; 6.21","explanation":"ДУ, п. 6.1; 6.2; 6.11; 6.21: «Оскорбление других военнослужащих, сотрудников государственных структур, а также всех гражданских лиц без исключений.\n\nВзыскание (таблица гл. VI):\n▸ Первично — Предупреждение» «Хранение, употребление, распространение запрещенных законодательством наркотических или психотропных веществ.» «Сон и отдых вне специально предназначенных для этого мест» «Самовольное оставление части (СОЧ) в рабочее время без одобренного рапорта на отгул или отпуск.» «▸ Первично — Выговор»","quote":"«Оскорбление других военнослужащих, сотрудников государственных структур, а также всех гражданских лиц без исключений. … Взыскание (таблица гл. VI): … ▸ Первично — Предупреждение» … «Хранение, употребление, распространение запрещенных законодательством наркотических или психотропных веществ.» … «Сон и отдых вне специально предназначенных для этого мест» … «Самовольное оставление части (СОЧ) в рабочее время без одобренного рапорта на отгул или отпуск.» … «▸ Первично — Выговор»","difficulty":"2"},"pairs":[{"l":{"id":"eRHa6LxY","text":"6.1 Оскорбление военнослужащих, сотрудников госструктур, гражданских"},"r":{"id":"81KxXJU5","text":"Предупреждение"}},{"l":{"id":"RkvhWjpc","text":"6.2 Хранение/употребление/распространение наркотических веществ"},"r":{"id":"HP0rf2ZI","text":"Выговор"}},{"l":{"id":"VTtEAalJ","text":"6.11 Сон и отдых вне отведённых мест / на посту"},"r":{"id":"HP0rf2ZI","text":"Выговор"}},{"l":{"id":"NWTjLUc8","text":"6.21 Самовольное оставление части (СОЧ)"},"r":{"id":"HP0rf2ZI","text":"Выговор"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-023', NULL, 'full', 2, 'du', 'ДУ, п. 6.1; 6.2; 6.11; 6.21', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-023');
