INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько минут Военной полиции разрешено оставить автомобиль на плацу у здания комендатуры при доставке задержанного?', '[]', '[]', '', 2, 970, '{"meta":{"article":"ДУ, п. 6.14","explanation":"ДУ, п. 6.14: «Военной полиции разрешено оставить автомобиль у здания комендатуры при доставке задержанного (не более 5 минут)»","quote":"«Военной полиции разрешено оставить автомобиль у здания комендатуры при доставке задержанного (не более 5 минут)»","difficulty":"2"},"answer":5,"tolerance":0,"unit":""}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-du-027', NULL, 'vp', 2, 'du', 'ДУ, п. 6.14', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-027');
