INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда военнослужащий может находиться на плацу, если построения нет?', '[{"id":"6GYdp9d1","text":"Никогда — находиться на плацу вне построения запрещено полностью"},{"id":"AoDqwBDN","text":"Плац разрешается переходить пешком по кратчайшему пути"},{"id":"iIUTkhSN","text":"В любое время, если военнослужащий в форменном обмундировании"},{"id":"CbjsTa8","text":"Только на служебном автомобиле по пути к парковке"}]', '["AoDqwBDN"]', '', 1, 990, '{"meta":{"article":"ДУ, п. 6.15","explanation":"ДУ, п. 6.15: «Исключение: плац разрешается переходить пешком по кратчайшему пути.»","quote":"«Исключение: плац разрешается переходить пешком по кратчайшему пути.»","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-029', NULL, 'full', 1, 'du', 'ДУ, п. 6.15', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-029');
