INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: У гражданина накопились неоплаченные штрафы на 45 000 руб. При остановке патрулём он отказался их платить.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин на КПП предлагает дежурному 50 000 руб., чтобы тот пропустил его на территорию части без пропуска. Дежурный деньги принял и пропустил.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сотрудник ВП задержал гражданина, не представился, не огласил статьи, а на просьбу о телефонном звонке ответил отказом.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин угнал служебный УАЗ ВП с цветографической схемой, чтобы покататься, и, нарушив ПДД, сбил пешехода, который без медицинской помощи не может прийти в сознание.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: А. организовал нападение на часового, Б. передал исполнителю пистолет, В. выстрелил в часового с целью убить его, чтобы помешать охране объекта; часовой выжил благодаря бронежилету.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин купил отмычки, чтобы тайно украсть имущество из гаража, но передумал и вернулся домой, хотя мог довести дело до конца. Через 7 дней об этом узнала полиция.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Группа из трёх лиц по предварительному сговору повредила мемориал погибшим в Великой Отечественной войне на территории гарнизона и сорвала Государственный флаг РФ с флагштока, надругавшись над ним.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие положения входят в презумпцию невиновности по ст. 1.4?', '[{"id":"JazXWwV","text":"Лицо считается невиновным, пока вина не доказана и не установлена вступившим в силу постановлением"},{"id":"5bAWM3e","text":"Неустранимые сомнения в виновности толкуются в пользу лица"},{"id":"Woxwx2th","text":"Лицо обязано доказывать свою невиновность"},{"id":"TwQoqz73","text":"Лицо отвечает только за правонарушения, в отношении которых установлена его вина"},{"id":"wzk2EFg","text":"Сомнения толкуются в пользу сотрудника, составившего протокол"},{"id":"RounMSpi","text":"Вина презюмируется при отказе от объяснений"}]', '["JazXWwV","5bAWM3e","TwQoqz73"]', '', 2, 3450, '{"meta":{"article":"Статья 1.4","explanation":"Ч. 1.4.1–1.4.3.","quote":"1.4.3. Неустранимые сомнения в виновности лица, привлекаемого к административной ответственности, толкуются в пользу этого лица.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q002', NULL, 'full', 2, 'koap', 'Статья 1.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На основании какого закона несёт ответственность лицо, совершившее административное правонарушение?', '[{"id":"o1PtBQjd","text":"Наиболее строгого из действовавших"},{"id":"fprKJWBQ","text":"Закона, действующего на момент рассмотрения дела судом"},{"id":"Mdjql6EG","text":"Закона, действовавшего во время совершения правонарушения"},{"id":"FePVWTXC","text":"Закона, действующего на момент составления протокола"}]', '["Mdjql6EG"]', '', 1, 3460, '{"meta":{"article":"Статья 1.5, ч. 1.5.1","explanation":"Ч. 1.5.1.","quote":"1.5.1. Лицо, совершившее административное правонарушение, подлежит ответственности на основании закона, действовавшего во время совершения административного правонарушения.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q003', NULL, 'medium', 1, 'koap', 'Статья 1.5, ч. 1.5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте форму вины с её признаками по ст. 2.2.', '[]', '[]', '', 2, 3470, '{"meta":{"article":"Статья 2.2","explanation":"Ч. 2.2.1, 2.2.2.","quote":"но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение таких последствий либо не предвидело возможности наступления таких последствий, хотя должно было и могло их предвидеть.","difficulty":"2"},"pairs":[{"l":{"id":"OjdHQtlb","text":"Умысел"},"r":{"id":"pXA858PI","text":"Осознавало противоправность, предвидело последствия и желало их, сознательно допускало либо относилось безразлично"}},{"l":{"id":"p6RF6uqL","text":"Неосторожность (самонадеянность)"},"r":{"id":"xTW7f8Ye","text":"Предвидело возможность последствий, но без достаточных оснований рассчитывало их предотвратить"}},{"l":{"id":"C2jkQp","text":"Неосторожность (небрежность)"},"r":{"id":"sWVTXSgy","text":"Не предвидело возможности последствий, хотя должно было и могло их предвидеть"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q004', NULL, 'vp', 2, 'koap', 'Статья 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Чем может ограничиться ответственность при малозначительности правонарушения?', '[{"id":"dzU3FAOz","text":"Штрафом в минимальном размере"},{"id":"SbuOpSq1","text":"Предупреждением в письменной форме"},{"id":"jUeWCEeb","text":"Административным арестом на 1 сутки"},{"id":"MjNy4EU","text":"Устным замечанием"}]', '["MjNy4EU"]', '', 2, 3480, '{"meta":{"article":"Статья 3.2","explanation":"Ст. 3.2.","quote":"может быть освобождено от административной ответственности и ограничиться устным замечанием.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q006', NULL, 'full', 2, 'koap', 'Статья 3.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите действия сотрудника/военнослужащего при предупреждении в порядке ст. 3.3.', '[]', '[]', '', 2, 3490, '{"meta":{"article":"Статья 3.3","explanation":"Ст. 3.3: неисполнение требований предупреждения может приравниваться к неподчинению.","quote":"После, если результатов оно не повлекло, то есть лицо не направило свои действия на устранение нарушения или отказалось в их пресечении со своей стороны, применяются иные виды административных наказаний.","difficulty":"2"},"items":[{"id":"iREZQnS","text":"Вынести предупреждение (устно или письменно) с просьбой прекратить проступок"},{"id":"s621TRGg","text":"Убедиться, что лицо не устранило нарушение или отказалось его пресечь"},{"id":"mZH3h2iU","text":"Применить иные виды административных наказаний"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q007', NULL, 'full', 2, 'koap', 'Статья 3.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'К чему может приравниваться неисполнение лицом требований, оговорённых в предупреждении?', '[{"id":"e0VosJuq","text":"К смягчающему обстоятельству"},{"id":"OMr4k7LH","text":"К неподчинению"},{"id":"8CDKoeJ3","text":"К малозначительному правонарушению"},{"id":"XXx9Xd0L","text":"К добровольному прекращению поведения"}]', '["OMr4k7LH"]', '', 3, 3500, '{"meta":{"article":"Статья 3.3","explanation":"Ст. 3.3, последнее предложение.","quote":"Неисполнение требований, оговоренных в предупреждении, лицом могут приравниваться к неподчинению.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q008', NULL, 'vp', 3, 'koap', 'Статья 3.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое соотношение игрового и реального времени установлено для административного ареста (ст. 3.6)?', '[{"id":"XZ8Q887d","text":"1 игровой день — 1 реальный час"},{"id":"zmKs3qC3","text":"1 игровой день — 1 реальная минута"},{"id":"lHIslJuX","text":"1 игровые сутки — 5 реальных минут"},{"id":"k8vpNCH0","text":"1 игровой день — 10 реальных минут"}]', '["zmKs3qC3"]', '', 2, 3510, '{"meta":{"article":"Статья 3.6","explanation":"Ст. 3.6.","quote":"((1 игровой день - 1 реальная минута))","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q009', NULL, 'vp', 2, 'koap', 'Статья 3.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие наказания КоАП относит к основным (ч. 4.1.2)?', '[{"id":"thW907FT","text":"Административный арест"},{"id":"mweSEcwE","text":"Административный штраф"},{"id":"aXEa9lzn","text":"Предупреждение"},{"id":"Mrn8NHNG","text":"Лишение права на управление ТС"},{"id":"Rvu5plg9","text":"Дисквалификация"},{"id":"tWebxLg","text":"Конфискация орудия совершения правонарушения"},{"id":"tynfalGm","text":"Обязательные работы"}]', '["thW907FT","mweSEcwE","aXEa9lzn","Mrn8NHNG"]', '', 2, 3520, '{"meta":{"article":"Статья 4.1, ч. 4.1.2","explanation":"Конфискация — дополнительное наказание; основное может назначаться только одно.","quote":"Основными наказания являются: предупреждение, лишение права на управление транспортным средством, административный штраф, административный арест.","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q011', NULL, 'medium', 2, 'koap', 'Статья 4.1, ч. 4.1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q011');
