INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что признаётся смягчающими обстоятельствами по ч. 4.2.1?', '[{"id":"OhUDkQA6","text":"Добровольное прекращение противоправного поведения"},{"id":"2RZGiKzL","text":"Совершение правонарушения в состоянии опьянения"},{"id":"l76lZ1nd","text":"Раскаяние лица"},{"id":"uLtttJXu","text":"Добровольное сообщение о совершённом правонарушении в уполномоченный орган"},{"id":"5mN2QhEC","text":"Совершение правонарушения впервые"},{"id":"Eii8sKc2","text":"Содействие органу в установлении обстоятельств дела"},{"id":"vxCE45Ar","text":"Наличие государственной службы"}]', '["OhUDkQA6","l76lZ1nd","uLtttJXu","Eii8sKc2"]', '', 2, 3540, '{"meta":{"article":"Статья 4.2","explanation":"Ч. 4.2.1, пп. 1–4; судья может признать и иные (ч. 4.2.2).","quote":"1) раскаяние лица, совершившего административное правонарушение; 2) добровольное прекращение противоправного поведения лицом, совершившим административное правонарушение;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q013', NULL, 'full', 2, 'koap', 'Статья 4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что признаётся отягчающими обстоятельствами по ч. 4.3.1?', '[{"id":"rZfbLDUc","text":"Совершение в условиях стихийного бедствия или при других чрезвычайных обстоятельствах"},{"id":"kxBg7oWd","text":"Раскаяние лица"},{"id":"ZH4fgx2y","text":"Совершение правонарушения военнослужащим"},{"id":"5VPXpdpT","text":"Совершение правонарушения группой лиц"},{"id":"bMfFVQB","text":"Совершение в состоянии опьянения либо отказ от медосвидетельствования"},{"id":"UTWgWQ4y","text":"Продолжение противоправного поведения несмотря на требование уполномоченных лиц прекратить его"},{"id":"kq7bMSr","text":"Совершение правонарушения в ночное время"}]', '["rZfbLDUc","5VPXpdpT","bMfFVQB","UTWgWQ4y"]', '', 2, 3550, '{"meta":{"article":"Статья 4.3","explanation":"Ч. 4.3.1, пп. 1, 3, 4, 5 (п. 2 — повторность).","quote":"1) продолжение противоправного поведения, несмотря на требование уполномоченных на то лиц прекратить его;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q014', NULL, 'full', 2, 'koap', 'Статья 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q014');
