INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Водитель пересёк организованную транспортную колонну (например, военную). По какой статье и какой штраф?', '[{"id":"0abAU8i","text":"Ст. 9.37 — 20 000 руб."},{"id":"35UaYdJc","text":"Ст. 9.25 — 5 000 руб."},{"id":"E2uTnXu","text":"Ст. 9.44 — 40 000 руб."},{"id":"ulp4ecbK","text":"Ст. 9.27 — 40 000 руб."}]', '["35UaYdJc"]', '', 2, 3710, '{"meta":{"article":"Статья 9.25","explanation":"Ст. 9.25 включает пересечение организованной колонны или занятие места в ней.","quote":"или пересечение организованной транспортной или пешей колонны либо занятие места в ней (см. статья 7.7 ПДД), -","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q042', NULL, 'medium', 2, 'koap', 'Статья 9.25', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q042');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой штраф за непредоставление преимущества ТС с включённым синим и(или) красным маячком и спецсигналом?', '[{"id":"kOPyreQp","text":"50 000 руб."},{"id":"p5Plpb4L","text":"10 000 руб."},{"id":"qdI4T6s","text":"20 000 руб."},{"id":"29tPR5JG","text":"40 000 руб."}]', '["qdI4T6s"]', '', 2, 3720, '{"meta":{"article":"Статья 9.37","explanation":"Ст. 9.37; обгон такого ТС — ст. 9.27 (40 000 руб.).","quote":"Непредоставление преимущества транспортному средству с включенным проблесковым маячком синего цвета и(или) красного цвета и специальным звуковым сигналом (см. статья 3.2 ПДД); влечет наложение административного штрафа в размере двадцати тысяч (20.000) рублей.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q043', NULL, 'full', 2, 'koap', 'Статья 9.37', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q043');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите части ст. 9.45 по возрастанию штрафа.', '[]', '[]', '', 3, 3730, '{"meta":{"article":"Статья 9.45","explanation":"Ч. 9.45.1–9.45.4.","quote":"9.45.4. Превышение установленной скорости движения транспортного средства на величину более 80 километров в час -","difficulty":"3"},"items":[{"id":"9wfLgeby","text":"Превышение не более 20 км/ч — 5 000 руб."},{"id":"Mr1zFCzu","text":"Более 20, но не более 40 км/ч — 10 000 руб."},{"id":"gReq5iq0","text":"Более 40, но не более 80 км/ч — 15 000 руб."},{"id":"H4rJoa8y","text":"Более 80 км/ч — 25 000 руб. или лишение права"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q044', NULL, 'vp', 3, 'koap', 'Статья 9.45', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q044');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какая ответственность за проникновение на территорию частной собственности без разрешения собственника?', '[{"id":"3js6Ije9","text":"Арест на 14 суток"},{"id":"qL98Huil","text":"Штраф от 20 000 до 50 000 руб."},{"id":"f0GjZFxH","text":"Штраф от 10 000 до 20 000 руб."},{"id":"ePlD0dsr","text":"Штраф 5 000 руб."}]', '["f0GjZFxH"]', '', 2, 3740, '{"meta":{"article":"Статья 7.1","explanation":"Ст. 7.1; взлом с целью проникновения — арест 14 суток (ст. 7.2).","quote":"Проникновение на территорию, в помещения частной собственности без разрешения собственника или уполномоченного лица, -","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q046', NULL, 'vp', 2, 'koap', 'Статья 7.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q046');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что из перечисленного прямо названо в составе мелкого хулиганства (ст. 8.1)?', '[{"id":"SSoO3BpM","text":"Попрошайничество"},{"id":"Ap69RGX","text":"Ношение маски, скрывающей лицо"},{"id":"oQJIVXJy","text":"Непристойное или оскорбительное приставание к гражданам"},{"id":"nvXkL4m2","text":"Уничтожение или повреждение чужого имущества"},{"id":"e90Eyn6H","text":"Курение в общественном месте"},{"id":"sCpDYbio","text":"Нахождение в общественных местах в нижнем белье (кроме водоёмов, бассейнов, спортзалов)"},{"id":"PUqAaT0C","text":"Нецензурная лексика в общественных местах"}]', '["oQJIVXJy","nvXkL4m2","sCpDYbio","PUqAaT0C"]', '', 2, 3750, '{"meta":{"article":"Статья 8.1","explanation":"Ст. 8.1; курение — 8.14, маски — 8.12, попрошайничество — 8.4.","quote":"сопровождающееся нецензурной лексикой в общественных местах, непристойным или оскорбительным приставанием к гражданам","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q047', NULL, 'medium', 2, 'koap', 'Статья 8.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q047');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой штраф за оскорбление (ст. 5.2)?', '[{"id":"RiBTBXCV","text":"От 10 000 до 20 000 руб."},{"id":"FEjcNBle","text":"Арест на 7 суток"},{"id":"71DwlLnQ","text":"От 5 000 до 15 000 руб."},{"id":"1ol7Hgz","text":"От 20 000 до 50 000 руб."}]', '["RiBTBXCV"]', '', 2, 3760, '{"meta":{"article":"Статья 5.2","explanation":"Ст. 5.2.","quote":"влечет наложение административного штрафа в размере от десяти тысяч (10.000) до двадцати тысяч (20.000) рублей.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q048', NULL, 'full', 2, 'koap', 'Статья 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q048');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Патруль ВП требует от гражданина, стоящего у КПП В/Ч, отойти с проезжей части. Гражданин в наушниках не реагирует. Военнослужащий сразу составляет протокол по ст. 8.7.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: У КПП В/Ч гражданин в маске-балаклаве с открыто висящим на поясе мачете фотографирует посты. На требование отойти и снять маску отвечает отказом и продолжает.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Военнослужащий контрактной службы в выходной, в гражданской одежде, проехал на красный свет. Инспектор ГИБДД выписывает штраф 25 000 руб. Военнослужащий утверждает, что «не при исполнении».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Во время введённого комендантского часа (режим ЧП) пьяный гражданин выходит на улицу, на требование патруля ВП вернуться отвечает отказом, затем отказывается платить штраф.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Пилот вертолёта ВС РФ взлетел с площадки части, забыв уведомить частоту госструктур, а затем пролетел над территорией ФСБ без разрешения.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Военнослужащий ВП, получив требование следователя СК предоставить журнал выдачи оружия по делу о хищении, игнорирует его. Позже игнорирует и требование прокурора явиться для дачи объяснений по проверке ношения формы.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин дважды подряд в течение 5 минут нарушил правила поведения на охраняемой территории у КПП части. Протокол после первого эпизода не составлялся. Военнослужащий хочет выписать два штрафа по ст. 8.11.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Колонна военной техники движется с включёнными синими маячками и спецсигналами. Водитель легкового автомобиля обгоняет головную машину, а другой водитель не уступает дорогу.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'С какого возраста, по общему правилу ТК, лица имеют право вступать в трудовые отношения в качестве работников?', '[{"id":"INswU4Kb","text":"С четырнадцати лет"},{"id":"Ckowj0SN","text":"С двадцати одного года"},{"id":"mGomF73W","text":"С восемнадцати лет"},{"id":"1cIgB0es","text":"С шестнадцати лет"}]', '["mGomF73W"]', '', 1, 3850, '{"meta":{"article":"Статья 10, ч. 10.3","explanation":"Если иное не предусмотрено ТК и другими федеральными законами — с 18 лет.","quote":"Если иное не предусмотрено настоящим Кодексом, другими федеральными законами, вступать в трудовые отношения в качестве работников имеют право лица, достигшие возраста восемнадцати лет.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q001', NULL, 'full', 1, 'tk', 'Статья 10, ч. 10.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в часах) по общему правилу допускается отстранить работника от работы?', '[]', '[]', '', 1, 3860, '{"meta":{"article":"Статья 15, ч. 15.1","explanation":"Отстранение — временная мера, не более 72 часов (исключение — тяжкие/особо тяжкие преступления на основании судебного решения).","quote":"Отстранить работника допускается только на срок, составляющий не более семидесяти двух (72) часов.","difficulty":"1"},"answer":72,"tolerance":0,"unit":"часов"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q002', NULL, 'full', 1, 'tk', 'Статья 15, ч. 15.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в часах) разрешено отстранять работника на основании оперативно-розыскных и иных следственных мероприятий (п. «б» ч. 3 ст. 15)?', '[]', '[]', '', 2, 3870, '{"meta":{"article":"Статья 15, ч. 15.5","explanation":"По основанию п. «б» ч. 15.3 срок отстранения — не более трёх часов.","quote":"На основании пункта \"б\" части 3 настоящей статьи разрешено отстранять работника на срок не более трех часов.","difficulty":"2"},"answer":3,"tolerance":0,"unit":"часа"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q003', NULL, 'full', 2, 'tk', 'Статья 15, ч. 15.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что из перечисленного является основанием для отстранения работника от работы? (выберите все верные)', '[{"id":"RHuYpIRQ","text":"Нахождение работника в отпуске"},{"id":"XaK6hjFc","text":"Судебное решение или судебный акт"},{"id":"bw0IyYV0","text":"Переаттестация работника"},{"id":"tYUthgLV","text":"Опоздание на построение"},{"id":"O3rD5ym4","text":"Досудебное разбирательство"},{"id":"4dRmz6T","text":"Жалоба гражданина на грубость работника"},{"id":"qVdJwUz","text":"Оперативно-розыскные и иные следственные мероприятия"}]', '["XaK6hjFc","bw0IyYV0","O3rD5ym4","qVdJwUz"]', '', 2, 3880, '{"meta":{"article":"Статья 15, ч. 15.3","explanation":"Перечень оснований ч. 15.3 закрытый: четыре пункта а–г.","quote":"15.3. Основаниями для отстранения от работы признаются: а) досудебное разбирательство; б) оперативно-розыскные и иные следственные мероприятия; в) переаттестация работника; г) судебное решение или судебный акт.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q004', NULL, 'vp', 2, 'tk', 'Статья 15, ч. 15.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что происходит с заработной платой и должностью работника в период отстранения от работы?', '[{"id":"RntLnTNG","text":"Начисляется половина заработной платы"},{"id":"yu7Z8Lmg","text":"Работник переводится на нижестоящую должность"},{"id":"7lZwzo6","text":"Заработная плата и должность сохраняются"},{"id":"Av4O49q","text":"Заработная плата не начисляется, должность сохраняется"}]', '["7lZwzo6"]', '', 1, 3890, '{"meta":{"article":"Статья 15, ч. 15.1, 15.6","explanation":"Отстранение — запрет осуществления полномочий с сохранением заработной платы и должности.","quote":"Отстранение от работы - временная мера, применяемая к работнику, в виде запрета осуществления должностных полномочий работником с сохранением заработной платы и должности, до принятия окончательного решения.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q006', NULL, 'full', 1, 'tk', 'Статья 15, ч. 15.1, 15.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Какую продолжительность (в часах в день) не может превышать рабочее время, за исключением случаев, установленных ТК?', '[]', '[]', '', 1, 3900, '{"meta":{"article":"Статья 17, ч. 17.2","explanation":"Ч. 17.2: не более 12 часов в день.","quote":"Продолжительность рабочего времени не может превышать 12 часов в день, за исключением случаев, установленных настоящими Кодексом.","difficulty":"1"},"answer":12,"tolerance":0,"unit":"часов"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q008', NULL, 'full', 1, 'tk', 'Статья 17, ч. 17.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На сколько часов уменьшается продолжительность рабочего дня (смены) в праздничный или выходной день?', '[]', '[]', '', 1, 3910, '{"meta":{"article":"Статья 18, ч. 18.1","explanation":"Ч. 18.1: уменьшается на один час.","quote":"Продолжительность рабочего дня или смены в праздничный или выходной день уменьшается на один час.","difficulty":"1"},"answer":1,"tolerance":0,"unit":"час"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q009', NULL, 'full', 1, 'tk', 'Статья 18, ч. 18.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях работодатель может привлечь работника к сверхурочной работе без его согласия?', '[{"id":"YMHvjexU","text":"При нехватке личного состава в мирное время"},{"id":"FGIgHdmJ","text":"При производстве работ, необходимость которых обусловлена введением чрезвычайного или военного положения"},{"id":"AQ6Adpa","text":"Для выполнения плана подразделения в обычном режиме"},{"id":"WeNTtsOw","text":"Для отработки дисциплинарного взыскания"},{"id":"IlKDvRG5","text":"В любой выходной день"},{"id":"W9ksxQ3","text":"При производстве неотложных работ в условиях чрезвычайных обстоятельств (бедствие или угроза бедствия)"}]', '["FGIgHdmJ","W9ksxQ3"]', '', 2, 3920, '{"meta":{"article":"Статья 19, ч. 19.2","explanation":"Ч. 19.2 содержит только два случая (пп. «а», «б») и случаи, предусмотренные ТК.","quote":"Привлечение работника по инициативе работодателя к сверхурочной работе допускается без его согласия в следующих случаях: а) при производстве работ, необходимость которых обусловлена введением чрезвычайного или военного положения;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q010', NULL, 'full', 2, 'tk', 'Статья 19, ч. 19.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q010');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте параметр перерыва для отдыха и питания с его значением по ТК.', '[]', '[]', '', 2, 3930, '{"meta":{"article":"Статья 24","explanation":"Ст. 24: перерыв не более двух часов и не менее 30 минут, в рабочее время не включается; может не предоставляться, если смена не превышает 4 часов.","quote":"В течение рабочего дня (смены) работнику должен быть предоставлен перерыв для отдыха и питания продолжительностью не более двух часов и не менее 30 минут, который в рабочее время не включается.","difficulty":"2"},"pairs":[{"l":{"id":"wUQIqAw8","text":"Минимальная продолжительность перерыва"},"r":{"id":"ghmx8i4","text":"30 минут"}},{"l":{"id":"Zw75i7Y","text":"Максимальная продолжительность перерыва"},"r":{"id":"TQpoP0Q","text":"2 часа"}},{"l":{"id":"ktX4Iyg9","text":"Продолжительность смены, при которой (не превышая её) перерыв может не предоставляться"},"r":{"id":"BqdPl95J","text":"4 часа"}},{"l":{"id":"GVq2SPtT","text":"Включается ли перерыв в рабочее время"},"r":{"id":"b8M7ihb7","text":"Не включается"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q011', NULL, 'full', 2, 'tk', 'Статья 24', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q011');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте дату и праздник по ТК РФ.', '[]', '[]', '', 1, 3940, '{"meta":{"article":"Статья 25, ч. 25.1","explanation":"Перечень праздничных дней ч. 25.1.","quote":"в) 23 февраля - День защитника Отечества;","difficulty":"1"},"pairs":[{"l":{"id":"xUluxCsH","text":"23 февраля"},"r":{"id":"5brWjtY","text":"День защитника Отечества"}},{"l":{"id":"VzdbcSiK","text":"9 мая"},"r":{"id":"HqHBNZeK","text":"День Победы"}},{"l":{"id":"npBdw3Tf","text":"12 июня"},"r":{"id":"8v8VwBm0","text":"День России"}},{"l":{"id":"K5SBgMc5","text":"4 ноября"},"r":{"id":"bwFiNN2","text":"День народного единства"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q012', NULL, 'full', 1, 'tk', 'Статья 25, ч. 25.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q012');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Какова минимальная продолжительность отпуска (в днях в месяц) по ТК?', '[]', '[]', '', 2, 3950, '{"meta":{"article":"Статья 27","explanation":"Ст. 27: устанавливается уставом и составляет не менее пяти дней в месяц.","quote":"Продолжительность отпуска устанавливается уставом организации и составляет не менее пяти дней в месяц.","difficulty":"2"},"answer":5,"tolerance":0,"unit":"дней в месяц"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q013', NULL, 'vp', 2, 'tk', 'Статья 27', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'В течение какого срока (в часах) работодатель обязан рассмотреть заявление работника на отпуск?', '[]', '[]', '', 1, 3960, '{"meta":{"article":"Статья 26, ч. 26.2","explanation":"Ч. 26.2: в течение 24 часов.","quote":"Заявление работника на отпуск должно быть рассмотрено работодателем в течение 24 часов.","difficulty":"1"},"answer":24,"tolerance":0,"unit":"часа"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q014', NULL, 'full', 1, 'tk', 'Статья 26, ч. 26.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q014');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие дисциплинарные взыскания предусмотрены ТК? (выберите все верные)', '[{"id":"aYPmL8Cb","text":"Выговор"},{"id":"wuhYbJBs","text":"Денежный штраф из заработной платы"},{"id":"tUdc7A","text":"Увольнение по соответствующим основаниям"},{"id":"UVQkSZtl","text":"Дисциплинарный арест"},{"id":"DI6WDlf","text":"Наряд вне очереди"},{"id":"OJYI1h3","text":"Лишение очередного отпуска"},{"id":"NPk85u2S","text":"Предупреждение (замечание)"}]', '["aYPmL8Cb","tUdc7A","UVQkSZtl","NPk85u2S"]', '', 1, 3970, '{"meta":{"article":"Статья 30, ч. 30.1","explanation":"Ч. 30.1 — четыре вида; ч. 30.2 запрещает взыскания, не предусмотренные федеральными законами.","quote":"а) предупреждение (замечание); б) выговор; в) увольнение по соответствующим основаниям; г) дисциплинарный арест.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q015', NULL, 'full', 1, 'tk', 'Статья 30, ч. 30.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q015');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в минутах) может быть применён дисциплинарный арест?', '[]', '[]', '', 2, 3980, '{"meta":{"article":"Статья 30, ч. 30.5","explanation":"Ч. 30.5: не более 30 минут.","quote":"на срок не более 30 минут.","difficulty":"2"},"answer":30,"tolerance":0,"unit":"минут"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q016', NULL, 'full', 2, 'tk', 'Статья 30, ч. 30.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В отношении кого может применяться дисциплинарный арест?', '[{"id":"VEUXhpxW","text":"В отношении любых государственных служащих"},{"id":"UnmfP7xE","text":"В отношении любых работников, имеющих два выговора"},{"id":"4VtWuhop","text":"В отношении сотрудников полиции и Росгвардии"},{"id":"AD3fjqH2","text":"Только в отношении военнослужащих Вооружённых Сил РФ"},{"id":"cq28ZpPx","text":"В отношении гражданских лиц, задержанных на территории части"}]', '["AD3fjqH2"]', '', 2, 3990, '{"meta":{"article":"Статья 30, ч. 30.5","explanation":"Ч. 30.5: только военнослужащие ВС РФ, в порядке федерального законодательства и устава территориальных органов ВС.","quote":"Дисциплинарный арест как дисциплинарное взыскание может быть применен только в отношении военнослужащих Вооруженных Сил Российской Федерации","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q017', NULL, 'full', 2, 'tk', 'Статья 30, ч. 30.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите этапы накопления дисциплинарных взысканий в правильном порядке — от первого к итоговому последствию.', '[]', '[]', '', 2, 4000, '{"meta":{"article":"Статья 30, ч. 30.3; Статья 16, ч. 16.4 п. «д»","explanation":"Ч. 30.3: три замечания = один выговор; три выговора — основание для увольнения по инициативе работодателя.","quote":"По достижению работником трех предупреждений (замечаний), три предупреждения (замечания) заменяются одним выговором. Достижение работником трёх выговоров является основанием для расторжения трудового договора по инициативе работодателя.","difficulty":"2"},"items":[{"id":"LffNJiYV","text":"Работник получает три предупреждения (замечания)"},{"id":"WMGRGOOL","text":"Три предупреждения заменяются одним выговором"},{"id":"Xa2g5F6","text":"Работник достигает трёх выговоров"},{"id":"l5M54Avr","text":"Основание для расторжения трудового договора по инициативе работодателя"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q018', NULL, 'vp', 2, 'tk', 'Статья 30, ч. 30.3; Статья 16, ч. 16.4 п. «д»', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Не позднее скольких часов с момента совершения проступка применяется дисциплинарное взыскание (кроме случаев применения по решению суда)?', '[]', '[]', '', 1, 4010, '{"meta":{"article":"Статья 31, ч. 31.1","explanation":"Ч. 31.1: не позднее 48 часов.","quote":"Дисциплинарное взыскание применяется не позднее 48 часов с момента совершения проступка, кроме случаев когда взыскание применяется по решению суда.","difficulty":"1"},"answer":48,"tolerance":0,"unit":"часов"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q019', NULL, 'full', 1, 'tk', 'Статья 31, ч. 31.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сколько дисциплинарных взысканий может быть применено за один дисциплинарный проступок?', '[{"id":"00Rqwqtn","text":"Не более трёх"},{"id":"mzpXUy1J","text":"Количество не ограничено при тяжком проступке"},{"id":"XqYeRgwq","text":"Только одно"},{"id":"QmOFKgO","text":"Не более двух"}]', '["XqYeRgwq"]', '', 1, 4020, '{"meta":{"article":"Статья 31, ч. 31.2","explanation":"Ч. 31.2.","quote":"За каждый дисциплинарный проступок может быть применено только одно дисциплинарное взыскание.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q020', NULL, 'full', 1, 'tk', 'Статья 31, ч. 31.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q020');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Через сколько дней со дня применения взыскания работник считается не имеющим его, если за это время не подвергался новому взысканию?', '[]', '[]', '', 1, 4030, '{"meta":{"article":"Статья 32, ч. 32.1","explanation":"Ч. 32.1: неделя (семь дней).","quote":"Если в течение недели (семи дней) со дня применения дисциплинарного взыскания работник не будет подвергнут новому дисциплинарному взысканию, то он считается не имеющим дисциплинарного взыскания.","difficulty":"1"},"answer":7,"tolerance":0,"unit":"дней"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q021', NULL, 'full', 1, 'tk', 'Статья 32, ч. 32.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'По чьей инициативе (просьбе, ходатайству) работодатель вправе досрочно снять дисциплинарное взыскание?', '[{"id":"OGgT1Tg","text":"По собственной инициативе работодателя"},{"id":"iywSqsQG","text":"По ходатайству непосредственного руководителя работника"},{"id":"fRvnKy6","text":"По заявлению средств массовой информации"},{"id":"FsMhMiU5","text":"По просьбе родственников работника"},{"id":"F34PA70W","text":"По ходатайству представительного органа работников"},{"id":"KUfkfQ1G","text":"По просьбе самого работника"},{"id":"8Yrl0UEH","text":"По требованию потерпевшего гражданина"}]', '["OGgT1Tg","iywSqsQG","F34PA70W","KUfkfQ1G"]', '', 2, 4040, '{"meta":{"article":"Статья 32, ч. 32.2","explanation":"Ч. 32.2 содержит закрытый перечень.","quote":"Работодатель до истечения недели (семи дней) со дня применения дисциплинарного взыскания имеет право снять его с работника по собственной инициативе, просьбе самого работника, ходатайству его непосредственного руководителя или представительного органа работников.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q022', NULL, 'full', 2, 'tk', 'Статья 32, ч. 32.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком порядке могут быть сняты дисциплинарные взыскания, назначенные сотрудниками прокуратуры?', '[{"id":"L9jBg7PX","text":"Только в порядке, предусмотренном приказом Генерального прокурора РФ"},{"id":"Ugl1BZ6U","text":"Командиром войсковой части по ходатайству непосредственного начальника"},{"id":"QWJJPwcZ","text":"Только решением Губернатора ФО"},{"id":"4lJN0P7P","text":"Любым работодателем по собственной инициативе"},{"id":"xjsiP1Fg","text":"Автоматически через 48 часов"}]', '["L9jBg7PX"]', '', 3, 4050, '{"meta":{"article":"Статья 32, ч. 32.4","explanation":"Ч. 32.4.","quote":"Дисциплинарные взыскания назначенные сотрудниками прокуратуры могут быть сняты только в порядке предусмотренном приказом Генерального прокурора Российской Федерации","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q023', NULL, 'full', 3, 'tk', 'Статья 32, ч. 32.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что из перечисленного является основанием расторжения трудового договора работодателем?', '[{"id":"sBRlEchy","text":"Достижение работником трёх выговоров"},{"id":"BpziwyV","text":"Профнепригодность (некомпетентность) работника"},{"id":"jxHqKrq","text":"Разжигание конфликтов внутри организации"},{"id":"SkiMPwKl","text":"Обращение работника в суд за защитой трудовых прав"},{"id":"mo1hGG3P","text":"Запрос работником отпуска меньшей продолжительности"},{"id":"XMTtROe4","text":"Досрочный выход работника из отпуска"},{"id":"ZBJZ3","text":"Отсутствие на рабочем месте в течение недели без действующего отпуска"}]', '["sBRlEchy","BpziwyV","jxHqKrq","ZBJZ3"]', '', 2, 4060, '{"meta":{"article":"Статья 16, ч. 16.4","explanation":"Ч. 16.4, пп. «д», «е», «ж», «з». Обращение в суд и досрочный выход из отпуска — права работника (ст. 26, 40).","quote":"е) отсутствие на рабочем месте в течение недели без действующего отпуска;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q025', NULL, 'vp', 2, 'tk', 'Статья 16, ч. 16.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте категорию преступления (совершённого во время работы в госорганизации) со сроком запрета на работу в госорганизациях, накладываемого судом.', '[]', '[]', '', 3, 4070, '{"meta":{"article":"Статья 16-1, ч. 16-1.7","explanation":"Ч. 16-1.7.","quote":"в) тяжкие преступления влекут наложение запрета на работу в государственных организациях на срок от двенадцати (12) до восемнадцати (18) дней, в зависимости от решения суда;","difficulty":"3"},"pairs":[{"l":{"id":"JwD71hXr","text":"Преступление небольшой тяжести"},"r":{"id":"HWQuRel","text":"Запрет не накладывается"}},{"l":{"id":"S46aIguK","text":"Преступление средней тяжести"},"r":{"id":"cmP1Es","text":"От 6 до 12 дней"}},{"l":{"id":"yduYkjmx","text":"Тяжкое преступление"},"r":{"id":"YrUrHS1m","text":"От 12 до 18 дней"}},{"l":{"id":"nQUeDi4O","text":"Особо тяжкое преступление"},"r":{"id":"SbTe171R","text":"От 18 до 24 дней"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q026', NULL, 'vp', 3, 'tk', 'Статья 16-1, ч. 16-1.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является основанием для наложения запрета на работу в госорганизациях БЕЗ судебного решения?', '[{"id":"WDDB32gX","text":"Систематическое (три и более в течение недели) неисполнение законного требования сотрудника прокуратуры"},{"id":"7ByCsfC7","text":"Совершение преступления небольшой тяжести"},{"id":"NYZSA4py","text":"Кража государственного имущества работником государственной организации"},{"id":"WWisf4e","text":"Кража денежных средств работником государственной организации"},{"id":"vfecnu0","text":"Не отработка семи дней на руководящих должностях / провал работы на руководящих должностях"},{"id":"oNGBQbMd","text":"Получение одного выговора"},{"id":"JSVXL2hM","text":"Увольнение по собственному желанию"}]', '["WDDB32gX","NYZSA4py","WWisf4e","vfecnu0"]', '', 2, 4080, '{"meta":{"article":"Статья 16-1, ч. 16-1.8","explanation":"Ч. 16-1.8, пп. «а»–«г».","quote":"а) кража государственного имущества работником государственной организации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q027', NULL, 'full', 2, 'tk', 'Статья 16-1, ч. 16-1.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в днях) Губернатор ФО может внести гражданина в реестр уволенных по отрицательным мотивам по основаниям ч. 16-1.8 без суда?', '[]', '[]', '', 3, 4090, '{"meta":{"article":"Статья 16-1, ч. 16-1.8","explanation":"Губернатор — не более 5 дней, Генеральный прокурор — не более 7 дней.","quote":"принимает Губернатор Федерального округа Российской Федерации на срок не более пяти (5) дней или Генеральный прокурор Российской Федерации на срок не более семи (7) дней.","difficulty":"3"},"answer":5,"tolerance":0,"unit":"дней"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q028', NULL, 'full', 3, 'tk', 'Статья 16-1, ч. 16-1.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q028');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой порядок установлен для командира (начальника) воинской части в вопросе внесения подчинённого в реестр уволенных по отрицательным мотивам?', '[{"id":"jA4WFtcM","text":"Командир сам вносит военнослужащего в реестр приказом"},{"id":"LyKVUbXf","text":"Командир вносит предложение в Совет Федерации"},{"id":"c9zF0eOJ","text":"Командир вносит предложение на рассмотрение Губернатора ФО, решение принимает Губернатор"},{"id":"H7iHWuf2","text":"Командир не вправе участвовать в этом процессе"},{"id":"nD0u1m5H","text":"Командир направляет предложение Министру обороны, который принимает окончательное решение"}]', '["c9zF0eOJ"]', '', 2, 4100, '{"meta":{"article":"Статья 16-1, ч. 16-1.5","explanation":"Ч. 16-1.5.","quote":"командир (начальник) воинской части вносят предложения по внесению в реестр лиц уволенных по отрицательным мотивам на основаниях, предусмотренных настоящим Федеральным законом, на рассмотрение Губернатором Федерального округа Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q030', NULL, 'full', 2, 'tk', 'Статья 16-1, ч. 16-1.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что может входить в испытание при приёме на работу?', '[{"id":"sqIjKKlH","text":"Медицинская операция"},{"id":"uohzX8mz","text":"Аттестация"},{"id":"PpUf1c2X","text":"Анкетирование"},{"id":"hkw4pvc","text":"Неоплачиваемая стажировка сроком месяц"},{"id":"TeVFUNu7","text":"Полиграф (детектор лжи)"},{"id":"h4KHYD0","text":"Экзаменирование"}]', '["uohzX8mz","PpUf1c2X","h4KHYD0"]', '', 1, 4110, '{"meta":{"article":"Статья 14, ч. 14.2","explanation":"Ч. 14.2: «только» три формы.","quote":"В испытание может входить только: анкетирование, экзаменирование, аттестация.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q032', NULL, 'full', 1, 'tk', 'Статья 14, ч. 14.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q032');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является основанием для проведения переаттестации работника?', '[{"id":"fGCiBtp","text":"Личная просьба сослуживцев"},{"id":"lrIkD0eD","text":"Однократное опоздание"},{"id":"DtfrA4F","text":"Неоднократное виновное нарушение трудовых норм в связи с недостаточностью знаний и навыков"},{"id":"j8RB6wZW","text":"Истечение 7 дней с момента приёма на работу"},{"id":"0o7i6SoY","text":"Решение прокурора по итогам комплексной прокурорской проверки"},{"id":"7beRYpZj","text":"Решение суда"}]', '["DtfrA4F","0o7i6SoY","7beRYpZj"]', '', 2, 4120, '{"meta":{"article":"Статья 35, ч. 35.4","explanation":"Ч. 35.4, пп. «а»–«в».","quote":"в) решение прокурора по итогам проведения комплексной прокурорской проверки;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q034', NULL, 'full', 2, 'tk', 'Статья 35, ч. 35.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Какой максимальный размер (в рублях) денежной компенсации морального вреда за незаконное увольнение может определить суд?', '[]', '[]', '', 2, 4130, '{"meta":{"article":"Статья 40-2, ч. 40-2.5","explanation":"Ч. 40-2.5: не более 100 000 рублей.","quote":"Размер этой компенсации определяется судом, но не может превышать сто тысяч (100.000) рублей.","difficulty":"2"},"answer":100000,"tolerance":0,"unit":"рублей"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q035', NULL, 'full', 2, 'tk', 'Статья 40-2, ч. 40-2.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите структурные элементы (главы) устава организации в порядке, установленном ТК.', '[]', '[]', '', 2, 4140, '{"meta":{"article":"Статья 39, ч. 39.1","explanation":"Ч. 39.1, пп. «а»–«д»; уставы госорганизаций, не соответствующие структуре, не применяются (ч. 39.2).","quote":"б) порядок приема и увольнения работников организации; в) права и обязанности работников организации; г) режим работы и время отдыха работников организации, оплата труда; д) положение о взысканиях и поощрениях;","difficulty":"2"},"items":[{"id":"0KgF5ESn","text":"Общее положение"},{"id":"WHPxFXeM","text":"Порядок приема и увольнения работников организации"},{"id":"5cqJQbB","text":"Права и обязанности работников организации"},{"id":"t99UiPU3","text":"Режим работы и время отдыха работников организации, оплата труда"},{"id":"nbjzU1MV","text":"Положение о взысканиях и поощрениях"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q036', NULL, 'vp', 2, 'tk', 'Статья 39, ч. 39.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q036');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кем утверждается устав государственных организаций и учреждений (если иное не предусмотрено федеральными законами)?', '[{"id":"8CkiiJJ2","text":"Генеральным прокурором РФ"},{"id":"BU6qwK6k","text":"Представительным органом работников"},{"id":"YNehS5b","text":"Правительством Федерального округа РФ"},{"id":"36jqBQZc","text":"Командиром бригады"}]', '["YNehS5b"]', '', 1, 4150, '{"meta":{"article":"Статья 38, ч. 38.1","explanation":"Ч. 38.1.","quote":"устав государственных организаций и учреждений утверждается Правительством Федерального округа Российской Федерации, если иное не предусмотрено федеральными законами.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q037', NULL, 'full', 1, 'tk', 'Статья 38, ч. 38.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Рядовой ВП 1-й мсбр (В/Ч №12132) опоздал на развод. Командир роты объявил ему дисциплинарный арест на 1 час, а через 30 минут за то же опоздание дополнительно объявил выговор.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Военнослужащий ВП допустил нарушение в понедельник в 10:00. Командир узнал о нём, но приказ о выговоре издал в четверг в 12:00 (через 74 часа).
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: За 4 дня ефрейтор получил: выговор (день 1), выговор (день 2), три замечания (дни 3–4). Командир на 5-й день подготовил приказ об увольнении по инициативе работодателя. Ефрейтор утверждает, что у него «только два выговора».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Младший сержант ВП подал командиру заявление на увольнение по собственному желанию. Командир не рассматривает его уже трое суток. У сержанта есть непогашенный выговор.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир батальона, узнав о проверке СК в отношении сержанта ВП, лично «отстранил» его от службы на 5 суток без сохранения денежного довольствия.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Военнослужащий ВП похитил со склада части ящик государственного имущества. Командир бригады желает, чтобы виновный был «занесён в чёрный список» госорганизаций.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Суд признал увольнение старшего сержанта ВП незаконным. Работник просит восстановить его и компенсировать моральный вред в 150 000 рублей.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: В мирное время, без введения ЧП или военного положения, командир роты ВП оставил личный состав на службе на 15 часов подряд без перерыва на питание, ссылаясь на «нехватку людей». Один из военнослужащих заявил, что это «принудительный труд».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: 9 мая (День Победы) сержант ВП несёт службу в смену. Он спрашивает, сокращается ли его смена и что будет, если сократить её невозможно.
