INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие службы включает служба войск?', '[{"id":"LrVjl158","text":"Конвойная служба МВД"},{"id":"WXCMxarp","text":"Караульная служба"},{"id":"k2yiGqVi","text":"Гарнизонная служба"},{"id":"b9WfMD9","text":"Патрульно-постовая служба полиции"},{"id":"dx9S89Hm","text":"Служба судебных приставов"},{"id":"iGUTzvJO","text":"Внутренняя служба"}]', '["WXCMxarp","k2yiGqVi","iGUTzvJO"]', '', 1, 4390, '{"meta":{"article":"Статья 16, ч. 16.2","explanation":"Ч. 16.2; организуется на основе общевоинских уставов и актов Минобороны.","quote":"Служба войск включает внутреннюю, гарнизонную и караульную службы","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q030', NULL, 'full', 1, 'fz_oborona', 'Статья 16, ч. 16.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте полномочие и субъекта, которому оно принадлежит по ФЗ «Об обороне».', '[]', '[]', '', 2, 4400, '{"meta":{"article":"Статьи 3, 10, 13, 19","explanation":"Ч. 3.1, 3.3, 10.3, 19.1.","quote":"Обеспечение Вооруженных Сил Российской Федерации вооружением, военной техникой и другими материальными средствами организует командир войсковой части.","difficulty":"2"},"pairs":[{"l":{"id":"Y0kxtpD2","text":"Общее руководство ВС РФ"},"r":{"id":"5hpuChAw","text":"Губернатор Федерального округа РФ"}},{"l":{"id":"QWRYeHkS","text":"Управление войсковыми частями"},"r":{"id":"NWAybD65","text":"Командиры бригад"}},{"l":{"id":"bTtrVPVY","text":"Ответственность за призыв на военную службу"},"r":{"id":"pz6KqG5g","text":"Военный Комиссариат"}},{"l":{"id":"nmxr5OYp","text":"Организация обеспечения ВС вооружением и материальными средствами"},"r":{"id":"RfDTANha","text":"Командир войсковой части"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oborona-q032', NULL, 'vp', 2, 'fz_oborona', 'Статьи 3, 10, 13, 19', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q032');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Не менее скольких раз в месяц военнослужащие обязаны проходить комплексный медицинский осмотр?', '[]', '[]', '', 1, 4410, '{"meta":{"article":"Статья 21","explanation":"Ст. 21: регулярно, не менее раза в месяц, у сотрудников государственных медицинских организаций.","quote":"регулярно (не менее раза в месяц) проходить комплексный медицинский осмотр у сотрудников государственных медицинских организаций.","difficulty":"1"},"answer":1,"tolerance":0,"unit":"раз в месяц"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oborona-q033', NULL, 'medium', 1, 'fz_oborona', 'Статья 21', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Куда могут быть обжалованы действия (бездействие) сотрудника ВС РФ, нарушающие права гражданина?', '[{"id":"3A5CPvre","text":"В суд"},{"id":"qEFOBh3O","text":"В органы прокуратуры РФ"},{"id":"0ftAP5a8","text":"В средства массовой информации"},{"id":"pHAf7RDh","text":"В профсоюз"},{"id":"m2qkhZIl","text":"Командиру другой бригады"},{"id":"khYGfz9D","text":"В вышестоящий орган или вышестоящему должностному лицу"}]', '["3A5CPvre","qEFOBh3O","khYGfz9D"]', '', 2, 4420, '{"meta":{"article":"Статья 22, ч. 22.3","explanation":"Ч. 22.3.","quote":"могут быть обжалованы в вышестоящий орган или вышестоящему должностному лицу, в органы прокуратуры Российской Федерации либо в суд.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q035', NULL, 'full', 2, 'fz_oborona', 'Статья 22, ч. 22.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто осуществляет государственный контроль за деятельностью ВС РФ?', '[{"id":"E5mSaE8","text":"Министр внутренних дел"},{"id":"4De367hV","text":"Губернатор Федерального округа РФ и Вице-губернаторы"},{"id":"3VUk2yzb","text":"Командир бригады"},{"id":"BN043O8Z","text":"Председатель Следственного комитета"},{"id":"0MkFJjVt","text":"Директор ФСБ"},{"id":"0lst1frW","text":"Правительство Федерального округа РФ"},{"id":"18WwLcgL","text":"Министр обороны Федерального округа"}]', '["4De367hV","0lst1frW","18WwLcgL"]', '', 3, 4430, '{"meta":{"article":"Статья 23, ч. 23.1","explanation":"Ч. 23.1 (надзор — прокуратура и суд, ст. 22; ведомственный контроль — порядок Минобороны, ч. 23.2).","quote":"Государственный контроль за деятельностью Вооруженных Сил Российской Федерации осуществляют Губернатор Федерального округа Российской Федерации и Вице-губернаторы Федерального округа, Правительство Федерального округа Российской Федерации в пределах полномочий, Министр обороны Федерального округа в пределах полномочий","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q036', NULL, 'full', 3, 'fz_oborona', 'Статья 23, ч. 23.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q036');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто осуществляет надзор за исполнением законов Вооружёнными Силами РФ?', '[{"id":"tapxVQQR","text":"Командиры бригад"},{"id":"A9CPfqL","text":"Органы прокуратуры"},{"id":"LSYR3zy","text":"Министерство внутренних дел"},{"id":"lxpKSeIS","text":"Военный комиссариат"}]', '["A9CPfqL"]', '', 1, 4440, '{"meta":{"article":"Статья 22, ч. 22.2","explanation":"Ч. 22.2.","quote":"Надзор за исполнением Вооруженных Сил Российской Федерации законов осуществляют органы прокуратуры","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q037', NULL, 'full', 1, 'fz_oborona', 'Статья 22, ч. 22.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кого ВС РФ обеспечивают вооружением и боеприпасами, организуя и проводя поставки?', '[{"id":"AV1FGcs","text":"Любых граждан по заявлению"},{"id":"Ah5ozpaX","text":"Только иностранные армии"},{"id":"Y0qwx6ml","text":"Частные охранные предприятия"},{"id":"cfkzBXWe","text":"Силовые государственные организации"}]', '["cfkzBXWe"]', '', 2, 4450, '{"meta":{"article":"Статья 19, ч. 19.3","explanation":"Ч. 19.3; см. также п. 2 ч. 11.1.","quote":"Вооруженные Силы Российской Федерации обеспечивают силовые государственные организации вооружением, боеприпасами, организуют и проводят поставки.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q038', NULL, 'full', 2, 'fz_oborona', 'Статья 19, ч. 19.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q038');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите звенья руководства и управления ВС РФ сверху вниз.', '[]', '[]', '', 3, 4460, '{"meta":{"article":"Статья 3, ч. 3.1–3.3","explanation":"Ч. 3.1–3.3: Министр обороны ФО подчиняется Губернатору; командиры бригад подчинены Губернатору, Вице-губернаторам, Министру обороны ФО.","quote":"Министр обороны Федерального округа подчиняется непосредственно Губернатору Федерального округа Российской Федерации и Вице-губернаторам Федерального округа.","difficulty":"3"},"items":[{"id":"2ewX220G","text":"Губернатор Федерального округа РФ (общее руководство)"},{"id":"x3Q4noE1","text":"Министр обороны Федерального округа (руководство)"},{"id":"ddZ5o6FY","text":"Командиры бригад (управление войсковыми частями)"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oborona-q039', NULL, 'vp', 3, 'fz_oborona', 'Статья 3, ч. 3.1–3.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q039');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Патруль ВП 1-й мсбр на территории части остановил гражданского водителя. Тот требует: «Представьтесь и покажите удостоверение!» Старший патруля отказывается, ссылаясь на то, что «военные не обязаны».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Ночью гражданин перелез через забор В/Ч №12132 и проник на склад. Наряд ВП обнаружил его внутри; на складе вскрыт ящик.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: На КПП охраняемого важного государственного объекта водитель нарушил установленные правила въезда. Военнослужащие ВП хотят досмотреть автомобиль и провести личный обыск водителя прямо на парковке у магазина в городе, куда он уехал.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: В мирное время (ЧП и военное положение не введены) командир роты ВП приказал патрулировать город на БТР и выставить блокпост в центре города.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Группа граждан перекрыла въезд в военный городок, не пропуская технику части на выезд для выполнения задач.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сержант полиции хочет пройти ускоренную военную подготовку в 1-й мсбр. Он спрашивает, что будет с его службой в полиции, званием и что он получит по окончании.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Рядовой ВП не проходил медицинский осмотр уже два месяца, ссылаясь на то, что «чувствует себя нормально».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин недоволен тем, что патруль ВП удерживал его на КПП 40 минут, и хочет пожаловаться.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: На охраняемом объекте к гражданину обратился военнослужащий ССО в маске (средства сокрытия личности). Гражданин требует назвать фамилию и показать удостоверение.
