INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что относится к основным частям огнестрельного оружия по 34-ФЗ?', '[{"id":"psFBQDyD","text":"Барабан"},{"id":"3D7I5SuU","text":"Ствол"},{"id":"S65qDHQ","text":"Прицел"},{"id":"orvq3QOY","text":"Приклад"},{"id":"kOKqbPu0","text":"Магазин"},{"id":"s2JIfn7Z","text":"Затвор"},{"id":"98PEfO9V","text":"Ствольная коробка"}]', '["psFBQDyD","3D7I5SuU","s2JIfn7Z","98PEfO9V"]', '', 2, 4570, '{"meta":{"article":"Статья 2, ч. 2.1, п. 8","explanation":"П. 8: ствол, затвор, барабан, рамка, ствольная коробка.","quote":"8) основные части огнестрельного оружия — ствол, затвор, барабан, рамка, ствольная коробка.","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q004', NULL, 'medium', 2, 'fz_oruzhie', 'Статья 2, ч. 2.1, п. 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'На какие виды подразделяется оружие по цели применения (ст. 3)?', '[{"id":"Bi5vpw9p","text":"Самозарядное"},{"id":"w6DhpWWA","text":"Гражданское"},{"id":"B9EGL4Gx","text":"Спортивное"},{"id":"dWcsKipk","text":"Коллекционное (или используемое в культурных целях)"},{"id":"y0uJHU01","text":"Служебное"},{"id":"piVneSW3","text":"Огнестрельное"},{"id":"sshscNRo","text":"Боевое ручное стрелковое"}]', '["w6DhpWWA","dWcsKipk","y0uJHU01","sshscNRo"]', '', 2, 4580, '{"meta":{"article":"Статья 3, п. 1","explanation":"П. 1 ст. 3; «огнестрельное» — это критерий функционального назначения, «самозарядное» — принципа действия.","quote":"1) По цели применения: гражданское, служебное, боевое ручное стрелковое, коллекционное (или используемое в культурных целях).","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q008', NULL, 'full', 2, 'fz_oruzhie', 'Статья 3, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q008');
