INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое ограничение установлено для гражданского огнестрельного оружия по ч. 4.1?', '[{"id":"eLEXgmGr","text":"Его ёмкость магазина — не более 5 патронов"},{"id":"lSiQixvp","text":"Оно должно храниться только в оружейном сейфе"},{"id":"INiO0WcS","text":"Оно должно быть только гладкоствольным"},{"id":"KM72ztK","text":"Оно должно исключать ведение огня очередями"}]', '["KM72ztK"]', '', 1, 4600, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1.","quote":"Гражданское огнестрельное оружие должно исключать ведение огня очередями.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q010', NULL, 'medium', 1, 'fz_oruzhie', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q010');
