INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кому ч. 5.3 предоставляет право на ношение, хранение и применение огнестрельного оружия при исполнении служебных обязанностей?', '[{"id":"bXkFONhm","text":"Служащим войск национальной гвардии"},{"id":"Ftjhicq4","text":"Сотрудникам органов Следственного комитета РФ"},{"id":"UQY0wKLJ","text":"Сотрудникам средств массовой информации"},{"id":"VtHG2Ps2","text":"Сотрудникам частных охранных предприятий"},{"id":"020SpVce","text":"Служащим Вооружённых сил РФ"},{"id":"OERnzhWo","text":"Сотрудникам государственных бюджетных учреждений здравоохранения"}]', '["bXkFONhm","Ftjhicq4","020SpVce"]', '', 2, 4630, '{"meta":{"article":"Статья 5, ч. 5.3","explanation":"Перечень ч. 5.3: полиция, ФСИН, Росгвардия, ФСБ, ФСО, ВС РФ, прокуратура, СК, сотрудники Правительства (определённые актами).","quote":"Вооружённых сил Российской Федерации, органов прокуратуры Российской Федерации, органов Следственного комитета Российской Федерации","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q014', NULL, 'full', 2, 'fz_oruzhie', 'Статья 5, ч. 5.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q014');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях военнослужащий ВС РФ обязан сдать служебное оружие, бронежилет и иные полученные предметы (ч. 5.4)?', '[{"id":"aPBOZUs","text":"При выезде за пределы части по служебному заданию"},{"id":"nNpeoH2C","text":"При заступлении в наряд"},{"id":"rf1eiZU8","text":"При переводе в другое подразделение той же части"},{"id":"U91luEBv","text":"При уходе в увольнительную"},{"id":"PnCRHI1u","text":"При уходе в отгул или отпуск"},{"id":"ZdQ2ph7d","text":"При окончании рабочей смены"}]', '["U91luEBv","PnCRHI1u","ZdQ2ph7d"]', '', 2, 4640, '{"meta":{"article":"Статья 5, ч. 5.4","explanation":"Ч. 5.4: окончание смены, увольнительная, отгул, отпуск, иные причины окончания служебных полномочий.","quote":"при окончании рабочей смены, при уходе в увольнительную, отгул, отпуск, а также по иным причинам окончания служебных полномочий сотрудника (служащего).","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q015', NULL, 'full', 2, 'fz_oruzhie', 'Статья 5, ч. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q015');
