INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'При каких условиях сотрудник зарегистрированного ЧОП вправе носить средний бронежилет (3-го класса)?', '[{"id":"BpkAd4y6","text":"Наличие соответствующей записи в трудовой книжке"},{"id":"8UoVM9Dd","text":"Наличие удостоверения сотрудника СМИ"},{"id":"twedd4Vn","text":"Нахождение на охраняемой территории"},{"id":"m5HaEGqx","text":"Разрешение командира войсковой части"},{"id":"CyGkgZY4","text":"Наличие лицензии на ношение оружия"}]', '["BpkAd4y6","CyGkgZY4"]', '', 3, 4700, '{"meta":{"article":"Статья 7, ч. 7.1, п. 2","explanation":"П. 2 ч. 7.1.","quote":"сотрудники зарегистрированных частных охранных предприятий и организаций — при наличии соответствующей записи в трудовой книжке и лицензии на ношение оружия;","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q025', NULL, 'vp', 3, 'fz_oruzhie', 'Статья 7, ч. 7.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Каким правом пользуются военнослужащие (сотрудники силовых, военизированных структур) при исполнении должностных обязанностей по ч. 7.2?', '[{"id":"2WusOWR","text":"Правом на ношение СИЗ только при ЧП или военном положении"},{"id":"nNG4Ol0J","text":"Правом на ношение только лёгких и средних бронежилетов"},{"id":"sloCtKk2","text":"Правом на ношение всех видов СИЗ"},{"id":"DoYom7De","text":"Правом на ношение СИЗ только по приказу Губернатора"}]', '["sloCtKk2"]', '', 2, 4710, '{"meta":{"article":"Статья 7, ч. 7.2","explanation":"Ч. 7.2.","quote":"7.2. Сотрудники силовых, военизированных, правоохранительных государственных структур, а также органы Правительства Российской Федерации и органы Правительств Федеральных округов Российской Федерации при исполнении должностных обязанностей имеют право на ношение всех видов средств индивидуальной защиты (СИЗ).","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q027', NULL, 'full', 2, 'fz_oruzhie', 'Статья 7, ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'С какого возраста граждане имеют право на приобретение гражданского огнестрельного оружия?', '[]', '[]', '', 1, 4720, '{"meta":{"article":"Статья 8, ч. 8.1","explanation":"Ч. 8.1.","quote":"8.1. Право на приобретение гражданского огнестрельного оружия и оружия ограниченного поражения имеют граждане, достигшие возраста 18 лет.","difficulty":"1"},"answer":18,"tolerance":0,"unit":"лет"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q029', NULL, 'full', 1, 'fz_oruzhie', 'Статья 8, ч. 8.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Каков срок действия лицензии на приобретение, хранение и ношение оружия (в месяцах)?', '[]', '[]', '', 1, 4730, '{"meta":{"article":"Статья 8, ч. 8.2","explanation":"Ч. 8.2: три месяца, может быть продлена.","quote":"Срок действия лицензии — три месяца. По окончании срока действия лицензии она может быть продлена.","difficulty":"1"},"answer":3,"tolerance":0,"unit":"месяца"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q030', NULL, 'medium', 1, 'fz_oruzhie', 'Статья 8, ч. 8.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кому лицензия на приобретение оружия не выдаётся (ч. 8.4)?', '[{"id":"o6hhjMLu","text":"Лицам, лишённым судом права на приобретение оружия на установленный срок"},{"id":"b2H8Njtu","text":"Лицам, не достигшим установленного возраста"},{"id":"tAoacDBm","text":"Лицам с погашенной судимостью за преступление небольшой тяжести без оружия"},{"id":"zrFpJvH","text":"Военнослужащим ВС РФ"},{"id":"UOiqvECk","text":"Лицам с непогашенной судимостью за умышленное преступление"},{"id":"jpmwAYzn","text":"Лицам, ранее добровольно отказавшимся от лицензии"},{"id":"ksJts0OZ","text":"Лицам с погашенной судимостью за тяжкое преступление, совершённое с применением оружия"}]', '["o6hhjMLu","b2H8Njtu","UOiqvECk","ksJts0OZ"]', '', 3, 4740, '{"meta":{"article":"Статья 8, ч. 8.4","explanation":"Ч. 8.4.","quote":"2) имеющим непогашенную судимость за преступление, совершённое умышленно, либо имеющим погашенную судимость за тяжкое преступление, совершённое с применением оружия;","difficulty":"3"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q032', NULL, 'medium', 3, 'fz_oruzhie', 'Статья 8, ч. 8.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q032');
