INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой срок (в днях) лишается права на приобретение оружия лицо за особо тяжкое преступление с применением оружия?', '[]', '[]', '', 2, 4760, '{"meta":{"article":"Статья 8, ч. 8.5, п. 3","explanation":"П. 3 ч. 8.5.","quote":"3) особо тяжкие преступления, совершённые с применением оружия, влекут за собой лишение права на приобретение оружия на срок 25 дней.","difficulty":"2"},"answer":25,"tolerance":0,"unit":"дней"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q034', NULL, 'medium', 2, 'fz_oruzhie', 'Статья 8, ч. 8.5, п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие сведения должны быть указаны в реестрах лицензий (ч. 9.2)?', '[{"id":"CJNqnMKH","text":"Модель и серийный номер оружия"},{"id":"pcTs3hf4","text":"Фамилия и имя гражданина, реквизиты документа, удостоверяющего личность"},{"id":"YigKKTm","text":"Дата аннулирования лицензии"},{"id":"IxOPe8Pe","text":"Место службы гражданина"},{"id":"qh3UXp1B","text":"Наименование органа, выдавшего лицензию"},{"id":"MK4SktkF","text":"Основание и дата выдачи, номер и срок действия лицензии"},{"id":"cWoabnm","text":"Адрес места хранения оружия"}]', '["pcTs3hf4","YigKKTm","qh3UXp1B","MK4SktkF"]', '', 2, 4770, '{"meta":{"article":"Статья 9, ч. 9.2","explanation":"Ч. 9.2.","quote":"1) фамилия и имя гражданина, которому выдана лицензия, наименование и реквизиты документа, удостоверяющего его личность;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q035', NULL, 'full', 2, 'fz_oruzhie', 'Статья 9, ч. 9.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q035');
