INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях лицензия аннулируется органами, выдающими лицензии (ч. 11.1)?', '[{"id":"xDOHft0","text":"Поступление на военную службу"},{"id":"cEcV8rL","text":"Добровольный отказ от лицензии либо прекращение её действия"},{"id":"OskfBY4B","text":"Утрата военного билета"},{"id":"1HNuDQen","text":"Установление факта нарушения законодательства в сфере оборота стрелкового оружия"},{"id":"uQf6CxY","text":"Смена места жительства"},{"id":"1PAFRrHX","text":"Судебное решение о лишении гражданина соответствующего специального права"}]', '["cEcV8rL","1HNuDQen","1PAFRrHX"]', '', 2, 4790, '{"meta":{"article":"Статья 11, ч. 11.1","explanation":"Ч. 11.1.","quote":"3) установления факта нарушения гражданином законодательства Российской Федерации в сфере производства, продажи, передачи, владения, хранения и использования стрелкового оружия.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q038', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 11, ч. 11.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q038');
