INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие документы необходимо иметь при себе для пользования лицензией на оружие (ч. 12.5)?', '[{"id":"frNVeH","text":"Медицинская книжка"},{"id":"MgkOkWqG","text":"Военный билет"},{"id":"mtycENl","text":"Свидетельство о регистрации ТС"},{"id":"RZlykhev","text":"Паспорт и/или удостоверение, выданное органом государственной власти"},{"id":"NlslhCq","text":"Справка о прохождении медосмотра у врача-нарколога"},{"id":"ibq7u5h5","text":"Справка об отсутствии судимости"}]', '["frNVeH","RZlykhev","NlslhCq"]', '', 1, 4810, '{"meta":{"article":"Статья 12, ч. 12.5","explanation":"Ч. 12.5.","quote":"1) паспорт и/или удостоверение, выданное органом государственной власти; 2) медицинская книжка; 3) справка о прохождении медицинского осмотра у врача-нарколога.","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q042', NULL, 'medium', 1, 'fz_oruzhie', 'Статья 12, ч. 12.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q042');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'От предоставления какого документа освобождаются сотрудники правоохранительных структур (п. 5.3) при подаче заявления на лицензию?', '[{"id":"hFqbm2SN","text":"Справки врача-нарколога"},{"id":"mtoYKma","text":"Военного билета"},{"id":"rBZBkPIf","text":"Паспорта"},{"id":"w13UURJb","text":"Удостоверения сотрудника"}]', '["mtoYKma"]', '', 2, 4820, '{"meta":{"article":"Статья 13, ч. 13.1","explanation":"Ч. 13.1: основание — удостоверение сотрудника действующего состава.","quote":"освобождаются от обязанности предоставления военного билета при подаче заявления на получение лицензии на приобретение, хранение и ношение оружия.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q043', NULL, 'full', 2, 'fz_oruzhie', 'Статья 13, ч. 13.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q043');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что обязаны предоставить сотрудники в рамках упрощённой процедуры получения лицензии (ч. 13.2)?', '[{"id":"dRUkj5ff","text":"Справку о прохождении медосмотра (врач-нарколог)"},{"id":"hTM33JqL","text":"Удостоверение сотрудника, выданное соответствующим органом"},{"id":"8Q6RKJ0s","text":"Характеристику от командира"},{"id":"rXGhbA6","text":"Военный билет"},{"id":"yflqIcO","text":"Медицинскую карту"}]', '["dRUkj5ff","hTM33JqL"]', '', 2, 4830, '{"meta":{"article":"Статья 13, ч. 13.2","explanation":"Ч. 13.2.","quote":"1) удостоверение сотрудника, выданное соответствующим органом; 2) справку о прохождении медицинского осмотра (врач-нарколог).","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q044', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 13, ч. 13.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q044');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Рядовой ВП после окончания смены направляется в увольнительную, не сдав автомат и бронежилет, ссылаясь на то, что «завтра снова на службу».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Наряд ВП у КПП части задерживает гражданина, у которого под курткой средний бронежилет 3-го класса. Лицензии на оружие нет, он не сотрудник ЧОП или СМИ.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: На посту ВП у гражданина при досмотре в машине найдены: Taurus PT92 с лицензией (действует 2 месяца), 300 патронов разного калибра без отдельной лицензии и 150 единиц материалов для создания оружия.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Контрактник ВС РФ хочет получить лицензию на гражданское оружие для личных целей. Военного билета у него нет под рукой.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин, осуждённый ранее за кражу с применением ножа (преступление средней тяжести), через 15 дней после приговора, которым суд лишил его права на приобретение оружия, пытается подать документы на лицензию.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Во время согласованного митинга у здания Правительства ВП оцепляет площадь. Среди участников — гражданин с лицензионным ружьём за спиной, ещё один — в состоянии опьянения с ножом-клинком на поясе.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Офицер ВП проверяет у сослуживца документы перед выходом на патрулирование с табельным оружием. Лицензии ФСВНГ у сослуживца нет — «просрочилась».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин нанёс удар по голове монтировкой, сертифицированной как хозяйственно-бытовое изделие. Его защитник утверждает, что монтировка не оружие и квалификация «с использованием оружия» невозможна.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте понятие с определением по ч. 1.1 ст. 1.', '[]', '[]', '', 1, 4920, '{"meta":{"article":"Статья 1, ч. 1.1","explanation":"Пп. 1, 2, 4, 7 ч. 1.1.","quote":"2) закрытая территория - это место с закрытым доступом для гражданских лиц, а также с частично ограниченным доступом для государственных сотрудников.","difficulty":"1"},"pairs":[{"l":{"id":"4Vbmwman","text":"Охраняемая территория"},"r":{"id":"HAN5Oqde","text":"Место под охраной структуры с ограниченным или запрещённым доступом гражданским лицам"}},{"l":{"id":"CixDaXPQ","text":"Закрытая территория"},"r":{"id":"ZQ7khzcO","text":"Место с закрытым доступом для гражданских и частично ограниченным для госсотрудников"}},{"l":{"id":"BZsU70k","text":"Зелёная зона"},"r":{"id":"hITN8ydl","text":"Свободное передвижение граждан, зона общего порядка"}},{"l":{"id":"Ci2oOUU6","text":"Доступ"},"r":{"id":"X6RZIth","text":"Право прохода, проезда и пролёта на территорию"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q001', NULL, 'full', 1, 'fz_territorii', 'Статья 1, ч. 1.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте цвет зоны в приложении к 86-ФЗ с её режимом.', '[]', '[]', '', 2, 4930, '{"meta":{"article":"Статья 1, ч. 1.1, пп. 5, 6","explanation":"Пп. 4–6 ч. 1.1.","quote":"6) зона строгого режима, отмеченная в приложении к настоящему Федеральному закону красным цветом - закрытая для общего пользования территория для посещения.","difficulty":"2"},"pairs":[{"l":{"id":"reFktJs","text":"Жёлтый"},"r":{"id":"lRn4bV5C","text":"Зона ограниченного доступа — охраняемая территория"}},{"l":{"id":"RYW81sq","text":"Красный"},"r":{"id":"MQSEj3Vl","text":"Зона строгого режима — закрытая для общего пользования территория"}},{"l":{"id":"4DAXWlx","text":"Зелёный"},"r":{"id":"bxcldUZN","text":"Зона общего порядка, свободное передвижение"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q002', NULL, 'full', 2, 'fz_territorii', 'Статья 1, ч. 1.1, пп. 5, 6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что охватывает понятие «доступ» по 86-ФЗ?', '[{"id":"IDkrbk","text":"Только право прохода пешком"},{"id":"DdYaH7EH","text":"Право нахождения на территории в рабочее время"},{"id":"9GC6SmNp","text":"Право прохода, проезда и пролёта на территорию"},{"id":"NrHdYt1E","text":"Право прохода и проезда, но не пролёта"}]', '["9GC6SmNp"]', '', 2, 4940, '{"meta":{"article":"Статья 1, ч. 1.1, п. 7","explanation":"П. 7 ч. 1.1 — включая пролёт (важно для воздушных судов).","quote":"7) доступ - право прохода, проезда и пролёта на территорию.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q003', NULL, 'full', 2, 'fz_territorii', 'Статья 1, ч. 1.1, п. 7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто осуществляет права собственника от имени РФ при отсутствии соответствующих актов Губернатора?', '[{"id":"0cWE6kzv","text":"Министр обороны"},{"id":"NnLMplW4","text":"Губернатор Федерального округа РФ"},{"id":"nk04DP8t","text":"Председатель Совета Федерации"},{"id":"5sDeTaw","text":"Председатель Правительства РФ"}]', '["NnLMplW4"]', '', 2, 4950, '{"meta":{"article":"Статья 2, ч. 2.3","explanation":"Ч. 2.3.","quote":"В случае отсутствия соответствующих актов права собственника осуществляет Губернатор Федерального округа Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q005', NULL, 'vp', 2, 'fz_territorii', 'Статья 2, ч. 2.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто вправе присваивать государственной собственности статус охраняемой и (или) закрытой территории?', '[{"id":"G2OcLsXK","text":"Командир любой войсковой части"},{"id":"1fHqoSjV","text":"Начальник УВД по ЦАО"},{"id":"9MBKRM1y","text":"Министерство юстиции"},{"id":"oy1V1CJ7","text":"Губернатор ФО РФ, Правительство ФО РФ"}]', '["oy1V1CJ7"]', '', 2, 4960, '{"meta":{"article":"Статья 3, ч. 3.3","explanation":"Ч. 3.3.","quote":"3.3. Губернатор Федерального округа Российской Федерации, Правительство Федерального округа Российской Федерации вправе присваивать статус охраняемой и (или) закрытой территории в отношении государственной собственности","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q006', NULL, 'medium', 2, 'fz_territorii', 'Статья 3, ч. 3.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто имеет доступ на все закрытые и охраняемые территории по ч. 4.1 (кроме случаев, предусмотренных законом)?', '[{"id":"unVmbV6l","text":"Министры Федерального округа"},{"id":"1fMkuFnr","text":"Любые сотрудники ФСО без сопровождения"},{"id":"x69nF0Gw","text":"Губернатор ФО, Председатель Совета Федерации, Председатель законодательного собрания ФО"},{"id":"nElkxmgF","text":"Генеральный прокурор РФ, его заместители и их помощники"},{"id":"VgRARXNv","text":"Сотрудники ГБУЗ при любой цели визита"},{"id":"kZZ2fl9H","text":"Прокуроры субъектов РФ и их заместители"},{"id":"fDpHaLU","text":"Судьи РФ"}]', '["x69nF0Gw","nElkxmgF","kZZ2fl9H","fDpHaLU"]', '', 3, 4970, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1; министры — только на закреплённые территории (ч. 4.2); ФСО — в сопровождении (ч. 4.5); медики — с целью медпомощи (ч. 4.6).","quote":"4.1. Губернатор Федерального округа Российской Федерации, Председатель Совета Федерации, Председатель законодательного собрания Федерального округа имеют доступ на все закрытые и охраняемые территории","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q007', NULL, 'vp', 3, 'fz_territorii', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой статьёй установлен иной порядок входа на закрытую территорию войсковых частей при проверках и надзорных мероприятиях?', '[{"id":"gXtGRSNR","text":"Статьёй 4 (общий порядок)"},{"id":"VSJnHYF","text":"Уставом гарнизонной службы, без ссылки в законе"},{"id":"XcfvqRnl","text":"Статьёй 21 86-ФЗ"},{"id":"o5aZkRgw","text":"Статьёй 30"}]', '["XcfvqRnl"]', '', 3, 4980, '{"meta":{"article":"Статья 4, ч. 4.3, 4.4","explanation":"Ч. 4.3 и 4.4.","quote":"Иной порядок входа на закрытую территорию войсковых частей в рамках проведения проверок установлен статьей 21 настоящего Федерального закона.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q009', NULL, 'medium', 3, 'fz_territorii', 'Статья 4, ч. 4.3, 4.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q009');
