INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На сколько метров от ограждений учреждения исполнения наказаний отступает прилегающая (охраняемая) территория?', '[]', '[]', '', 2, 5140, '{"meta":{"article":"Статья 24, ч. 24.2, п. 2","explanation":"П. 2 ч. 24.2.","quote":"Прилегающей территорией считается территория отступающая на 15 метров от ограждений учреждения исполнения наказаний.","difficulty":"2"},"answer":15,"tolerance":0,"unit":"метров"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q037', NULL, 'medium', 2, 'fz_territorii', 'Статья 24, ч. 24.2, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите действия при проходе адвоката в учреждение исполнения наказаний в порядке ст. 26.', '[]', '[]', '', 2, 5150, '{"meta":{"article":"Статья 26","explanation":"Ст. 26.","quote":"Сотрудники уголовно-исполнительной системы обязаны сопроводить адвоката в комнату свиданий, затем доставить туда лицо, отбывающее наказание.","difficulty":"2"},"items":[{"id":"XxQpLhyc","text":"Адвокат предъявляет удостоверение адвоката и паспорт"},{"id":"W3bZoAMk","text":"Адвокат называет имя и фамилию лица, к которому прибыл"},{"id":"ng864zcf","text":"Сотрудники УИС сопровождают адвоката в комнату свиданий"},{"id":"mAEJGQLi","text":"Сотрудники УИС доставляют туда лицо, отбывающее наказание"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q039', NULL, 'full', 2, 'fz_territorii', 'Статья 26', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q039');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие объекты относятся к стратегически важным государственным объектам (ч. 28.2)?', '[{"id":"sw2QJJoV","text":"Объект №7"},{"id":"3d1I3z16","text":"Военные комиссариаты"},{"id":"98WIUPpl","text":"Зарайский кремль"},{"id":"g3GhB6F","text":"Государственные склады медицинского оборудования, военные склады"},{"id":"6lRsgdfC","text":"Холл УФСБ"},{"id":"tbrr91Hf","text":"Радиолокационная станция «Орбита»"},{"id":"luk2KfjR","text":"КПП войсковых частей"}]', '["sw2QJJoV","98WIUPpl","g3GhB6F","tbrr91Hf"]', '', 3, 5160, '{"meta":{"article":"Статья 28, ч. 28.2","explanation":"Ч. 28.2 (7 пунктов).","quote":"4) Объект №7 5) Радиолокационная станция \"Орбита\" 6) Зарайский кремль","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q040', NULL, 'full', 3, 'fz_territorii', 'Статья 28, ч. 28.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q040');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте вид пропуска с его назначением (ч. 31.1).', '[]', '[]', '', 2, 5170, '{"meta":{"article":"Статья 31, ч. 31.1","explanation":"Ч. 31.1.","quote":"4) разовый пропуск – документ, предоставляющий право однократного доступа на территорию объекта.","difficulty":"2"},"pairs":[{"l":{"id":"aUJFRFJk","text":"Постоянный"},"r":{"id":"48qHxo","text":"Многократный доступ на установленный срок лицам с постоянной трудовой/служебной деятельностью на объекте"}},{"l":{"id":"39ixDy","text":"Временный"},"r":{"id":"j0fujE6e","text":"Многократный доступ на период выполнения работ временного характера"}},{"l":{"id":"onR3tEBT","text":"Разовый"},"r":{"id":"vwPbYsn","text":"Однократный доступ посетителям и представителям организаций"}},{"l":{"id":"n5H9Rbp3","text":"Материальный"},"r":{"id":"VlDMc0G7","text":"Перемещение материальных ценностей (ввоз, вывоз, внос, вынос)"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q044', NULL, 'medium', 2, 'fz_territorii', 'Статья 31, ч. 31.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q044');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой пропуск предоставляет право постоянного доступа на территорию объекта, а также на отдельные режимные территории или помещения в соответствии с должностными обязанностями?', '[{"id":"6HEuTGh","text":"Материальный пропуск"},{"id":"DLgzRcr","text":"Временный пропуск"},{"id":"rpyUihyj","text":"Постоянный пропуск"},{"id":"7opuXQB","text":"Служебный пропуск"}]', '["7opuXQB"]', '', 3, 5180, '{"meta":{"article":"Статья 31, ч. 31.1, п. 2","explanation":"П. 2 ч. 31.1.","quote":"2) служебный пропуск – документ, предоставляющий право постоянного доступа на территорию объекта, а также на отдельные режимные территории или помещения в соответствии с должностными обязанностями.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q045', NULL, 'medium', 3, 'fz_territorii', 'Статья 31, ч. 31.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q045');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Нужен ли пропуск лицам, определённым ст. 4 (Губернатор, судьи, прокуроры и др.), для доступа на территории с пропускным режимом?', '[{"id":"FeOxUtaz","text":"Да, служебный пропуск соответствующей организации"},{"id":"R5BR7BTr","text":"Да, постоянный пропуск"},{"id":"HTOmFQtw","text":"Да, разовый пропуск в каждом случае"},{"id":"MBKwL7M4","text":"Нет, они имеют доступ без пропуска в порядке ст. 4"}]', '["MBKwL7M4"]', '', 2, 5190, '{"meta":{"article":"Статья 30, ч. 30.2","explanation":"Ч. 30.2.","quote":"30.2. Лица, определенные статьей 4 настоящего Федерального закона, имеют доступ в порядке, определенном статьей 4, к территориям с пропускным режимом без пропуска.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q046', NULL, 'full', 2, 'fz_territorii', 'Статья 30, ч. 30.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q046');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите полномочия сотрудников, охраняющих территорию с пропускным режимом, в порядке их применения к лицу (ч. 31.3).', '[]', '[]', '', 2, 5200, '{"meta":{"article":"Статья 31, ч. 31.3","explanation":"Ч. 31.3, пп. 1–3.","quote":"3) в случае отказа лица от осуществления в отношении него указанных процедур, сотрудники органов государственной власти с пропускным режимом имеют право отказать лицу в посещении таковой территории либо потребовать от него её покинуть.","difficulty":"2"},"items":[{"id":"eHXfg3gb","text":"Проверка документов, удостоверяющих личность"},{"id":"DLKsvcKH","text":"Личный обыск и обыск транспортного средства лица"},{"id":"doa5UegL","text":"При отказе лица от процедур — отказ в посещении либо требование покинуть территорию"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q047', NULL, 'full', 2, 'fz_territorii', 'Статья 31, ч. 31.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q047');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: К КПП В/Ч №12132 подходит гражданин и фотографирует парковку перед КПП. Затем пытается пройти через КПП внутрь части, пропуска нет.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: На КПП В/Ч прибывает помощник Генерального прокурора без пропуска и заявляет о проведении надзорного мероприятия. Дежурный требует оформить разовый пропуск.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Бригада скорой помощи ГБУЗ ЦГБ №3 въезжает на территорию части к раненому военнослужащему. После оказания помощи медик начинает осматривать склады; дежурный требует уйти, медик отказывается.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Офицер ВП прибыл на территорию УВД по ЦАО (закрытая зона, задний двор) для передачи задержанного. Сотрудник полиции требует объяснить цель нахождения.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Подразделение ВП сопровождает груз на РЛС «Орбита». Сотрудник ФСО на месте сомневается, вправе ли военные находиться внутри объекта.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: В военном комиссариате проходят призывные мероприятия. Гражданин без повестки проходит в помещение призывного пункта и снимает видео. После окончания мероприятий он возвращается снова.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Родственник осуждённого прибывает в учреждение исполнения наказаний, предъявляет только паспорт и просит свидания, затем пытается выйти из здания администрации на территорию.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сотрудник Росгвардии без приглашения проходит за забор В/Ч, заявляя, что «все госсотрудники имеют свободный доступ к госсобственности». Также ссылается на сбор для снабжения, но в рацию ничего не сообщал.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких областях деятельности государства защищаемые сведения могут составлять государственную тайну?', '[{"id":"0FboBi3k","text":"Бытового обслуживания населения"},{"id":"zpFEcpw","text":"Внешнеполитической"},{"id":"12OgdBV","text":"Военной"},{"id":"6ZzKos7u","text":"Частной жизни граждан"},{"id":"K3oDrCo7","text":"Оперативно-розыскной"},{"id":"9WGz8fAC","text":"Разведывательной и контрразведывательной"},{"id":"UkfH9za3","text":"Спортивной"}]', '["zpFEcpw","12OgdBV","K3oDrCo7","9WGz8fAC"]', '', 1, 5290, '{"meta":{"article":"Статья 2, п. 1","explanation":"Ст. 2 п. 1: военная, внешнеполитическая, экономическая, разведывательная, контрразведывательная, оперативно-розыскная деятельность.","quote":"государственная тайна - защищаемые государством сведения в области его военной, внешнеполитической, экономической, разведывательной, контрразведывательной и оперативно-розыскной деятельности, распространение которых может нанести ущерб безопасности Российской Федерации;","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q001', NULL, 'medium', 1, 'fz_gostayna', 'Статья 2, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте термин и его определение по ФЗ «О государственной тайне».', '[]', '[]', '', 2, 5300, '{"meta":{"article":"Статья 2, пп. 4–6, 8","explanation":"Ст. 2 пп. 4, 5, 6, 8.","quote":"доступ к сведениям, составляющим государственную тайну, - санкционированное полномочным должностным лицом ознакомление конкретного лица со сведениями, составляющими государственную тайну;","difficulty":"2"},"pairs":[{"l":{"id":"qWhWpg0H","text":"Допуск к государственной тайне"},"r":{"id":"AwO27cGT","text":"Процедура оформления права граждан на доступ к сведениям, составляющим гостайну"}},{"l":{"id":"vId9qUr","text":"Доступ к сведениям, составляющим гостайну"},"r":{"id":"phESixL","text":"Санкционированное полномочным должностным лицом ознакомление конкретного лица со сведениями"}},{"l":{"id":"21y4Xt2t","text":"Гриф секретности"},"r":{"id":"sZDAYdTX","text":"Реквизиты, свидетельствующие о степени секретности сведений в носителе"}},{"l":{"id":"NV31NuxT","text":"Жетон государственного служащего"},"r":{"id":"Apwf43eS","text":"Личный знак с номером, позволяющий идентифицировать госслужащего"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q003', NULL, 'medium', 2, 'fz_gostayna', 'Статья 2, пп. 4–6, 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие органы и должностные лица способны относить сведения к государственной тайне и присваивать гриф секретности?', '[{"id":"IQlcNrSL","text":"Командир бригады"},{"id":"MRw9w9YG","text":"Начальники региональных управлений ФСБ"},{"id":"FYAz7WwG","text":"Начальник управления ФСО"},{"id":"g81kitQ","text":"Министр внутренних дел Федерального округа"},{"id":"cJecF6IM","text":"Министр обороны Федерального округа"},{"id":"3ORhIGYS","text":"Губернатор Федерального округа РФ"},{"id":"tL0eBp1O","text":"Прокуроры субъектов РФ"}]', '["MRw9w9YG","FYAz7WwG","3ORhIGYS","tL0eBp1O"]', '', 3, 5310, '{"meta":{"article":"Статья 3","explanation":"Ст. 3 содержит 8 пунктов; Минобороны и командиры в нём не названы.","quote":"7) Начальники региональных управлений Федеральной службы безопасности Российской Федерации.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gostayna-q005', NULL, 'vp', 3, 'fz_gostayna', 'Статья 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Составляют ли гостайну сведения о лицах, сотрудничающих на конфиденциальной основе с органами, ведущими разведывательную, контрразведывательную и ОРД?', '[{"id":"BjXvWBg","text":"Нет, это открытая информация"},{"id":"L4ertFe","text":"Да, в том числе о лицах, сотрудничавших ранее"},{"id":"5G3TRrW9","text":"Только если лицо является военнослужащим"},{"id":"9cpsHbYt","text":"Только в военное время"}]', '["L4ertFe"]', '', 2, 5320, '{"meta":{"article":"Статья 4, ч. 4.2 п. 3","explanation":"Ч. 4.2 п. 3.","quote":"3) о лицах, сотрудничающих или сотрудничавших на конфиденциальной основе с органами, осуществляющими разведывательную, контрразведывательную и оперативно-розыскную деятельность;","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q008', NULL, 'full', 2, 'fz_gostayna', 'Статья 4, ч. 4.2 п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q008');
