INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите грифы секретности от высшей степени к низшей.', '[]', '[]', '', 1, 5350, '{"meta":{"article":"Статья 6, ч. 6.2","explanation":"Ч. 6.2: три степени.","quote":"Устанавливаются три степени секретности сведений, составляющих государственную тайну, и соответствующие этим степеням грифы секретности для носителей указанных сведений: \"особой важности\", \"совершенно секретно\" и \"секретно\".","difficulty":"1"},"items":[{"id":"BSr4RkfR","text":"«Особой важности»"},{"id":"cTBFy51O","text":"«Совершенно секретно»"},{"id":"UUZABKqg","text":"«Секретно»"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q012', NULL, 'full', 1, 'fz_gostayna', 'Статья 6, ч. 6.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q012');
