INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Военнослужащий имеет допуск к сведениям «совершенно секретно». К каким сведениям он может получить доступ на основании этого допуска?', '[{"id":"prb41MSZ","text":"Ко всем сведениям любой степени"},{"id":"7l3qw96w","text":"Только к совершенно секретным"},{"id":"4BNb7l7Q","text":"К совершенно секретным и секретным"},{"id":"Gd4nx26p","text":"К сведениям особой важности"}]', '["4BNb7l7Q"]', '', 2, 5410, '{"meta":{"article":"Статья 11, ч. 11.3","explanation":"Ч. 11.3: допуск к более высокой степени — основание для доступа к более низкой.","quote":"Наличие у должностных лиц и граждан допуска к сведениям более высокой степени секретности является основанием для доступа их к сведениям более низкой степени секретности.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q021', NULL, 'full', 2, 'fz_gostayna', 'Статья 11, ч. 11.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько форм допуска к государственной тайне установлено законом?', '[]', '[]', '', 1, 5420, '{"meta":{"article":"Статья 11, ч. 11.3","explanation":"Ч. 11.3: соответствуют трём степеням секретности.","quote":"Устанавливаются три формы допуска к государственной тайне должностных лиц и граждан, соответствующие трем степеням секретности сведений","difficulty":"1"},"answer":3,"tolerance":0,"unit":"формы"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q022', NULL, 'full', 1, 'fz_gostayna', 'Статья 11, ч. 11.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто допускается к сведениям, составляющим гостайну, без проведения проверочных мероприятий?', '[{"id":"Ls8dmOgd","text":"Адвокаты-защитники по уголовным делам, связанным с гостайной"},{"id":"iV2TqKJG","text":"Судьи на период исполнения полномочий"},{"id":"6WE6eUL","text":"Руководящий состав ФСО РФ"},{"id":"5reEqP6c","text":"Военнослужащие военной полиции"},{"id":"nHKtWh58","text":"Следователи Следственного комитета РФ при исполнении полномочий, связанных с гостайной"},{"id":"2p5C6ZYX","text":"Журналисты государственных СМИ"},{"id":"FqV2AZ3R","text":"Командиры рот"}]', '["Ls8dmOgd","iV2TqKJG","6WE6eUL","nHKtWh58"]', '', 3, 5430, '{"meta":{"article":"Статья 12, ч. 12.1–12.2-1","explanation":"Особая форма допуска — ст. 12.","quote":"Депутаты Законодательного Собрания Федерального округа, судьи на период исполнения ими своих полномочий, а также адвокаты, участвующие в качестве защитников в уголовном судопроизводстве по делам, связанным со сведениями, составляющими государственную тайну","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q024', NULL, 'full', 3, 'fz_gostayna', 'Статья 12, ч. 12.1–12.2-1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q024');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько нарушений взятых на себя обязательств по защите гостайны достаточно для прекращения допуска (минимальное число)?', '[]', '[]', '', 2, 5440, '{"meta":{"article":"Статья 14, п. 1","explanation":"П. 1 ст. 14: однократное нарушение.","quote":"однократного нарушения им взятых на себя предусмотренных трудовым договором (контрактом) обязательств, связанных с защитой государственной тайны;","difficulty":"2"},"answer":1,"tolerance":0,"unit":"нарушение (однократное)"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q027', NULL, 'medium', 2, 'fz_gostayna', 'Статья 14, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Освобождает ли прекращение допуска к гостайне от обязательств по неразглашению?', '[{"id":"OtMJBGba","text":"Нет, не освобождает"},{"id":"rLVaR0MN","text":"Освобождает через 7 дней"},{"id":"9YGF7ja5","text":"Освобождает только при увольнении по собственному желанию"},{"id":"WHqG3lMj","text":"Да, полностью освобождает"}]', '["OtMJBGba"]', '', 2, 5450, '{"meta":{"article":"Статья 14, п. 4","explanation":"П. 4 ст. 14.","quote":"4) прекращение допуска к государственной тайне не освобождает должностное лицо или гражданина от взятых ими обязательств по неразглашению сведений, составляющих государственную тайну;","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q028', NULL, 'full', 2, 'fz_gostayna', 'Статья 14, п. 4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q028');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какую ответственность несут лица, виновные в нарушении законодательства о государственной тайне?', '[{"id":"a836MrV7","text":"Уголовную"},{"id":"9gy0b8b4","text":"Гражданско-правовую"},{"id":"8X07Warq","text":"Конституционно-правовую"},{"id":"XqCStlK9","text":"Только моральную"},{"id":"K77jZ4QZ","text":"Административную"},{"id":"4dmhWmMy","text":"Дисциплинарную"},{"id":"DowS6vMe","text":"Международно-правовую"}]', '["a836MrV7","9gy0b8b4","K77jZ4QZ","4dmhWmMy"]', '', 1, 5460, '{"meta":{"article":"Статья 15, ч. 15.1","explanation":"Ч. 15.1.","quote":"несут уголовную, административную, гражданско-правовую или дисциплинарную ответственность в соответствии с действующим законодательством.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q030', NULL, 'full', 1, 'fz_gostayna', 'Статья 15, ч. 15.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кем организуется контроль за обеспечением защиты гостайны в судебных органах и органах прокуратуры?', '[{"id":"jd9VyZPO","text":"ФСБ"},{"id":"yjAlZbVb","text":"Губернатором лично в каждом случае"},{"id":"kK2LdQV","text":"Министерством обороны"},{"id":"4MX9Rgl6","text":"Руководителями этих органов"}]', '["4MX9Rgl6"]', '', 3, 5470, '{"meta":{"article":"Статья 17, ч. 17.3","explanation":"Ч. 17.3.","quote":"Контроль за обеспечением защиты государственной тайны в судебных органах и органах прокуратуры организуется руководителями этих органов.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q033', NULL, 'medium', 3, 'fz_gostayna', 'Статья 17, ч. 17.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Где обязательны для исполнения положения ФЗ «О государственной тайне»?', '[{"id":"YparD1F8","text":"Только на территории РФ"},{"id":"YaE5s0PI","text":"Только в зданиях органов власти"},{"id":"8unSvkB5","text":"На территории РФ и за её пределами"},{"id":"0vag12kU","text":"Только на территории воинских частей"}]', '["8unSvkB5"]', '', 2, 5480, '{"meta":{"article":"Статья 1, ч. 1.2","explanation":"Ч. 1.2.","quote":"Положения настоящего Федерального закона обязательны для исполнения на территории Российской Федерации и за ее пределами","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q034', NULL, 'medium', 2, 'fz_gostayna', 'Статья 1, ч. 1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Составляют ли гостайну сведения о системе правительственной, шифрованной и засекреченной связи, о шифрах?', '[{"id":"5wnG6BCw","text":"Да"},{"id":"e9IpAhtF","text":"Только в военное время"},{"id":"3pwoOQCJ","text":"Нет"},{"id":"EhdReFsD","text":"Только если они касаются ФСО"}]', '["5wnG6BCw"]', '', 2, 5490, '{"meta":{"article":"Статья 4, ч. 4.2 п. 5","explanation":"Ч. 4.2 п. 5.","quote":"5) о системе правительственной, шифрованной, в том числе кодированной и засекреченной связи, о шифрах","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q035', NULL, 'full', 2, 'fz_gostayna', 'Статья 4, ч. 4.2 п. 5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин снимает на видео КПП и технику 1-й мсбр, а затем публикует в соцсети пост с указанием дислокации, реального наименования и численности подразделений части.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир войсковой части решил собственным приказом присвоить гриф «совершенно секретно» плану учений.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир бригады хочет рассекретить старый приказ с грифом «секретно», чтобы опубликовать его к юбилею части.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сотрудник Росгвардии в балаклаве и форме спецподразделения отказывается назвать себя, ссылаясь на «государственную тайну». НПА Губернатора о его подразделении не издавался.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Адвокат подзащитного военнослужащего, обвиняемого по делу, связанному со сведениями, составляющими гостайну, требует ознакомиться с материалами. Следователь отказывает: «у вас нет проверки».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сержант ВП имеет допуск «секретно». Ему передали для ознакомления документ «совершенно секретно», а товарищу с допуском «особой важности» — документ «секретно».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Контракт старшины с допуском к гостайне расторгнут в связи с сокращением штатов, допуск прекращён. Через неделю он рассказывает знакомым о системе шифрованной связи части.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Военнослужащему, желающему получить допуск, руководитель отказал, а другого военнослужащего пытаются оформить на допуск принудительно, не ознакомив с нормами об ответственности.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Прокурор субъекта присвоил гриф «секретно» материалам проверки по воинской части, а затем Генеральный прокурор решил их рассекретить. Параллельно встал вопрос, кто контролирует защиту гостайны в органах прокуратуры.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто такой работник государственной организации по 54-ФЗ?', '[{"id":"PXbm9YD7","text":"Только лицо, имеющее воинское или специальное звание"},{"id":"hddyveGR","text":"Только руководитель государственного органа"},{"id":"0jn8zYtI","text":"Физическое лицо, которое работает в государственной организации"},{"id":"ECMCb4yI","text":"Любой гражданин, получающий пособие от государства"}]', '["0jn8zYtI"]', '', 1, 5590, '{"meta":{"article":"Статья 1, п. 2","explanation":"Ст. 1 п. 2.","quote":"работник государственной организации - физическое лицо, которое работает в государственной организации.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q001', NULL, 'medium', 1, 'fz_gossluzhba', 'Статья 1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что запрещено работнику государственной организации согласно ч. 2.3?', '[{"id":"dvnLUTnn","text":"Делать грубые и оскорбительные замечания, реплики либо жесты"},{"id":"LLk88Tr","text":"Делать оскорбительные сравнения (например, с животными или неодушевлёнными предметами)"},{"id":"B3st80Z9","text":"Использовать в адрес конкретного лица ненормативную лексику, нецензурные выражения"},{"id":"EJezqlB3","text":"Обращаться к гражданам на «Вы»"},{"id":"fMSRSN2W","text":"Носить классические наручные часы"},{"id":"0SDfFcfl","text":"Выдвигать инициативы руководству"}]', '["dvnLUTnn","LLk88Tr","B3st80Z9"]', '', 1, 5600, '{"meta":{"article":"Статья 2, ч. 2.3","explanation":"Ч. 2.3, пп. 1–3.","quote":"3) делать оскорбительные сравнения (например, с животными или неодушевленными предметами).","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q002', NULL, 'full', 1, 'fz_gossluzhba', 'Статья 2, ч. 2.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как закон оценивает целенаправленные действия или бездействие (в т.ч. халатность), повлёкшие репутационные потери для государственной организации?', '[{"id":"epE18S1V","text":"Не влекут ответственности, если нет материального ущерба"},{"id":"kJhfeNNo","text":"Наказываются исключительно по решению коллектива"},{"id":"g7BWl8G0","text":"Влекут только устное замечание"},{"id":"HTFJpLSD","text":"Наказываются в соответствии с законодательством РФ"}]', '["HTFJpLSD"]', '', 2, 5610, '{"meta":{"article":"Статья 4","explanation":"Ст. 4.","quote":"Целенаправленно совершенные действия или бездействия, в том числе халатность, повлекшие за собой репутационные потери для государственной организации, наказываются в соответствии с законодательством Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q004', NULL, 'full', 2, 'fz_gossluzhba', 'Статья 4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких органах исполняется военная служба согласно ч. 5.1?', '[{"id":"gBc7JzHa","text":"В Вооружённых Силах РФ"},{"id":"ta7QK4WQ","text":"В органах внутренних дел"},{"id":"iJHvmSJ","text":"В уголовно-исполнительной системе"},{"id":"tOTfwSrp","text":"В органах прокуратуры"},{"id":"zvZ7tPfu","text":"В органах государственной охраны"},{"id":"fDatRS0p","text":"В органах федеральной службы безопасности"}]', '["gBc7JzHa","zvZ7tPfu","fDatRS0p"]', '', 2, 5620, '{"meta":{"article":"Статья 5, ч. 5.1","explanation":"Ч. 5.1: военная служба — особый вид федеральной госслужбы.","quote":"Военная служба - особый вид федеральной государственной службы, исполняемой в Вооруженных Силах Российской Федерации, в органах федеральной службы безопасности, органах государственной охраны.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gossluzhba-q005', NULL, 'vp', 2, 'fz_gossluzhba', 'Статья 5, ч. 5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что относится к основам субординации военнослужащих?', '[{"id":"cwPlSHTp","text":"К гражданским лицам обращаться на «Вы» в любом случае"},{"id":"lBVqv5BL","text":"К младшим по званию допустимо обращаться на «ты»"},{"id":"h5UoTGJ9","text":"Вместо звания можно называть только фамилию"},{"id":"jnpvAEya","text":"Допускается обращение по прозвищу, если оно не оскорбительно"},{"id":"zcjOyyd","text":"Перед воинским званием добавляется слово «товарищ»"},{"id":"T5RebZgj","text":"По вопросам военной службы военнослужащие обращаются друг к другу на «Вы»"}]', '["cwPlSHTp","zcjOyyd","T5RebZgj"]', '', 1, 5630, '{"meta":{"article":"Статья 8, ч. 8.3","explanation":"Ч. 8.3, пп. 1–2; п. 3 запрещает искажение званий, клички, прозвища, фамильярность.","quote":"1) по вопросам военной службы военнослужащие должны обращаться друг к другу на \"Вы\", к гражданским лицам должны обращаться на “Вы” в любом случае;","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q007', NULL, 'medium', 1, 'fz_gossluzhba', 'Статья 8, ч. 8.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q007');
