INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Разрешено ли использовать повседневную форму одежды (китель) при задержании, розыске, приводе, патруле?', '[{"id":"cEaAypIM","text":"Да, но только для офицеров"},{"id":"DoQrRoxp","text":"Да, это обязательно"},{"id":"Gvboo2D","text":"Да, при наличии знаков различия"},{"id":"ezzLQAF","text":"Нет, это запрещено"}]', '["ezzLQAF"]', '', 2, 5740, '{"meta":{"article":"Статья 30, ч. 30.2","explanation":"Ч. 30.2.","quote":"Государственным служащим запрещается использовать форменную повседневную форму одежды (кителя) при выполнении задач, связанных с оперативной работой (задержания, розыск, привод, патруль и т.д.)","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gossluzhba-q027', NULL, 'vp', 2, 'fz_gossluzhba', 'Статья 30, ч. 30.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q027');
