INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является основанием для наложения запрета на работу в госорганизациях без судебного решения по 54-ФЗ?', '[{"id":"iK3tSnZ","text":"Кража денежных средств работником государственной организации"},{"id":"E2Qrjbvt","text":"Не отработка 7 дней на руководящих должностях, провал работы на руководящих должностях"},{"id":"rIpWfrqp","text":"Совершение любого административного правонарушения"},{"id":"Nm0GEbR9","text":"Увольнение по собственному желанию"},{"id":"H4Oi10Dc","text":"Получение одного замечания"},{"id":"bYum60ej","text":"Кража государственного имущества работником государственной организации"}]', '["iK3tSnZ","E2Qrjbvt","bYum60ej"]', '', 2, 5760, '{"meta":{"article":"Статья 37, ч. 37.1","explanation":"Ч. 37.1.","quote":"2) кража денежных средств работником государственной организации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q031', NULL, 'full', 2, 'fz_gossluzhba', 'Статья 37, ч. 37.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Неотработка скольких дней на руководящей должности является основанием для запрета на работу в госорганизациях без суда?', '[]', '[]', '', 1, 5770, '{"meta":{"article":"Статья 37, ч. 37.1 п. 3","explanation":"П. 3 ч. 37.1.","quote":"3) не отработка 7 (семи) дней на руководящих должностях в государственной организации","difficulty":"1"},"answer":7,"tolerance":0,"unit":"дней"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q032', NULL, 'full', 1, 'fz_gossluzhba', 'Статья 37, ч. 37.1 п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q032');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'За что могут вручаться ведомственные награды?', '[{"id":"zgyAa9E8","text":"Проявление доблести, мужества и самоотдачи при выполнении служебных обязанностей"},{"id":"cgrZpLGv","text":"Достижения в профессиональной деятельности"},{"id":"01ZU4q28","text":"За наличие родственных связей с руководителем"},{"id":"L9W4vmlg","text":"За уплату добровольного взноса в организацию"},{"id":"HpImkUW7","text":"Автоматически за каждые 7 дней службы"},{"id":"i4ETz3l0","text":"Значительный вклад в развитие и совершенствование государственной службы"}]', '["zgyAa9E8","cgrZpLGv","i4ETz3l0"]', '', 2, 5780, '{"meta":{"article":"Статья 38, ч. 38.2","explanation":"Ч. 38.2, пп. 1–3 (п. 4 — иные заслуги, имеющие значение для госслужбы).","quote":"3) проявление доблести, мужества и самоотдачи при выполнении служебных обязанностей;","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q037', NULL, 'medium', 2, 'fz_gossluzhba', 'Статья 38, ч. 38.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Во время доставления задержанного рядовой ВП громко называет его нецензурными словами и сравнивает с животным на глазах у прохожих.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Рядовой обращается к сержанту ВП: «Слышь, Серый, ты чё?» Сержант отвечает рядовому тем же тоном.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир роты хочет повысить старшего прапорщика до младшего лейтенанта, хотя у того нет военного билета. «Билет оформим потом».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Наряд ВП выезжает на задержание дезертира. Один из офицеров надел повседневный китель. Позже он даёт интервью телеканалу в полевой форме.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Военнослужащий ВП пришёл на службу в форме подразделения ССО с их нашивками, «потому что она удобнее». Акта руководителя нет.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сотрудник штаба (госслужащий) пришёл на службу в шортах, со светящимися кроссовками, видимой татуировкой на шее и с ирокезом.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сержант ВП украл из кассы части денежные средства. Командир хочет сразу «запретить ему работу в госструктурах».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин с непогашенной судимостью по статье, указанной в ч. 5 ст. 12 ПК, хочет поступить по контракту в 1-ю мсбр, а затем — в государственную больницу.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир бригады издал приказ о лишении воинского звания генерал-майора, служащего в бригаде, и о понижении майора до капитана.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что понимается под воздушным пространством Российской Федерации по 95-ФЗ?', '[{"id":"ACXPaLG","text":"Воздушное пространство над территорией РФ, в том числе над внутренними водами и территориальным морем"},{"id":"NL61472Y","text":"Только воздушное пространство над сушей Российской Федерации, без водных пространств"},{"id":"h8bBY4uB","text":"Воздушное пространство над городом и посадочными площадками государственных организаций"},{"id":"7h8V8P5","text":"Воздушное пространство только над закрытыми и охраняемыми территориями"}]', '["ACXPaLG"]', '', 1, 5880, '{"meta":{"article":"Статья 1, ч. 1.1","explanation":"Ч. 1.1 прямо включает внутренние воды и территориальное море.","quote":"1.1. Под воздушным пространством Российской Федерации понимается воздушное пространство над территорией Российской Федерации, в том числе воздушное пространство над внутренними водами и территориальным морем.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q001', NULL, 'medium', 1, 'fz_vozduh', 'Статья 1, ч. 1.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Перемещение каких материальных объектов прямо названо в определении использования воздушного пространства (ч. 1.2)?', '[{"id":"ICxhVoLa","text":"Парашютистов"},{"id":"BsCTIfyx","text":"Беспилотных аэростатов"},{"id":"ynZSyWFU","text":"Воздушных судов"},{"id":"2rBAH0C4","text":"Наземного транспорта на автомагистралях"},{"id":"YHNv8fCS","text":"Ракет"}]', '["ynZSyWFU","YHNv8fCS"]', '', 2, 5890, '{"meta":{"article":"Статья 1, ч. 1.2","explanation":"В ч. 1.2 перечислены воздушные суда, ракеты и «другие объекты», а также иная деятельность, связанная с безопасностью воздушного движения.","quote":"осуществляются перемещение в воздушном пространстве различных материальных объектов (воздушных судов, ракет и других объектов), а также другая деятельность, связанная с безопасностью воздушного движения.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q002', NULL, 'full', 2, 'fz_vozduh', 'Статья 1, ч. 1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие категории пользователей воздушного пространства выделяет ч. 2.2 ст. 2?', '[{"id":"CYJUKr2N","text":"Журналисты аккредитованных СМИ"},{"id":"qSpHKeRT","text":"Сотрудники иных государственных организаций"},{"id":"3sDtg29","text":"Иностранные граждане и лица без гражданства"},{"id":"T5OpRMAl","text":"Граждане Российской Федерации"},{"id":"PhTaoweD","text":"Сотрудники частных охранных предприятий"},{"id":"4VrdMy4n","text":"Члены Правительства РФ, члены Правительства Федерального округа РФ"}]', '["qSpHKeRT","T5OpRMAl","4VrdMy4n"]', '', 2, 5900, '{"meta":{"article":"Статья 2, ч. 2.2","explanation":"Три категории: а) граждане РФ; б) члены Правительства РФ и Правительства ФО; в) сотрудники иных госорганизаций.","quote":"а) граждане Российской Федерации; б) члены Правительства Российской Федерации, члены Правительства Федерального округа Российской Федерации;; в) сотрудники иных государственных организаций.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q004', NULL, 'full', 2, 'fz_vozduh', 'Статья 2, ч. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько категорий пользователей воздушного пространства выделяет ч. 2.2 ст. 2 95-ФЗ?', '[]', '[]', '', 1, 5910, '{"meta":{"article":"Статья 2, ч. 2.2","explanation":"Пункты а), б), в).","quote":"2.2. Выделяются следующие категории пользователей воздушного пространства, требования к которым различны согласно настоящему Федеральному закону:","difficulty":"1"},"answer":3,"tolerance":0,"unit":"категории"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q005', NULL, 'medium', 1, 'fz_vozduh', 'Статья 2, ч. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какое воздушное движение предусматривает обеспечить организация использования воздушного пространства (ч. 3.1)?', '[{"id":"wWDsPXHX","text":"Круглосуточное"},{"id":"jBONAe9Y","text":"Регулярное"},{"id":"DugXiow","text":"Скоростное"},{"id":"1xeBfUzx","text":"Безопасное"},{"id":"zZTao452","text":"Экономичное"},{"id":"oGQopL1","text":"Бесплатное"}]', '["jBONAe9Y","1xeBfUzx","zZTao452"]', '', 1, 5920, '{"meta":{"article":"Статья 3, ч. 3.1","explanation":"Ч. 3.1: безопасного, экономичного и регулярного воздушного движения.","quote":"3.1. Организация использования воздушного пространства предусматривает обеспечение безопасного, экономичного и регулярного воздушного движения.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q006', NULL, 'full', 1, 'fz_vozduh', 'Статья 3, ч. 3.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что включает в себя организация использования воздушного пространства (ч. 3.2)?', '[{"id":"BIUL5p5","text":"Обслуживание (управление) воздушного движения сотрудниками государственных организаций и гражданами РФ"},{"id":"Moe49wMh","text":"Выдачу лицензий пилотам гражданских воздушных судов"},{"id":"DWdTXd6n","text":"Организацию потоков воздушного движения и безопасности запретных зон"},{"id":"CcKUZ6yx","text":"Сертификацию посадочных площадок жилых домов"},{"id":"w28zmjM","text":"Регистрацию и учёт частных вертолётов"}]', '["BIUL5p5","DWdTXd6n"]', '', 2, 5930, '{"meta":{"article":"Статья 3, ч. 3.2","explanation":"Ч. 3.2 содержит ровно два пункта: а) обслуживание (управление) движения; б) организация потоков и безопасности запретных зон.","quote":"а) обслуживание (управление) воздушного движения сотрудниками государственных организаций и гражданами Российской Федерации; б) организацию потоков воздушного движения и безопасности запретных зон.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q007', NULL, 'vp', 2, 'fz_vozduh', 'Статья 3, ч. 3.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Откуда по общему правилу осуществляются взлёт и посадка воздушных судов сотрудников государственных организаций?', '[{"id":"08zYmK7z","text":"С автомагистрали при условии перекрытия движения"},{"id":"umOxAVwa","text":"Строго с посадочной площадки государственных организаций"},{"id":"W0j3DCQS","text":"С любой дворовой территории при отсутствии людей"},{"id":"bOnVHHNx","text":"С любой площадки, включая крыши жилых домов"}]', '["umOxAVwa"]', '', 1, 5940, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1: «строго с посадочной площадки государственных организаций».","quote":"4.1. Взлет и посадка воздушных судов сотрудников государственных организаций осуществляется строго с посадочной площадки государственных организаций.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q008', NULL, 'medium', 1, 'fz_vozduh', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Куда ч. 4.1 ст. 4 не допускает посадку воздушных судов (иначе как в порядке, предусмотренном законом)?', '[{"id":"hDytAX4U","text":"На специализированные объекты взлёта и посадки"},{"id":"1IaCVQb","text":"На жилые дома"},{"id":"sccp3a15","text":"На вертолётные площадки больниц"},{"id":"o3VSBw6","text":"На автомобильные дороги"},{"id":"DdmqySJX","text":"На автомагистрали"},{"id":"0WEDJocL","text":"На посадочные площадки государственных организаций"}]', '["1IaCVQb","o3VSBw6","DdmqySJX"]', '', 1, 5950, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Запрет ч. 4.1: автомагистрали, автомобильные дороги, жилые дома.","quote":"Не допускается посадка воздушных судов на автомагистрали, автомобильные дороги, жилые дома иначе как в порядке, предусмотренном настоящим Федеральным законом.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q009', NULL, 'full', 1, 'fz_vozduh', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях сотрудники госорганизаций вправе совершить посадку на любые территории и объекты (ч. 4.2)?', '[{"id":"N0wtkuP","text":"Оказание экстренной или неотложной медицинской помощи"},{"id":"vb3SwTyO","text":"Устное разрешение любого старшего по званию"},{"id":"J2XFUuQg","text":"Отсутствие свободной площадки у своей организации"},{"id":"UbrCOeY5","text":"Сокращение времени в пути до места службы"},{"id":"gf3Sd800","text":"Вынужденная необходимость в проведении оперативных мероприятий"},{"id":"etY3p","text":"Проведение спасательных операций"}]', '["N0wtkuP","gf3Sd800","etY3p"]', '', 2, 5960, '{"meta":{"article":"Статья 4, ч. 4.2","explanation":"Ч. 4.2: оперативные мероприятия, экстренная/неотложная медпомощь, спасательные операции или иные мероприятия по перечню Правительства ФО.","quote":"посадка связана с вынужденной необходимостью в проведении оперативных мероприятий, оказания экстренной или неотложной медицинской помощи, проведении спасательных операций или иных мероприятий","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q010', NULL, 'medium', 2, 'fz_vozduh', 'Статья 4, ч. 4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q010');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'С каких мест иные граждане РФ вправе осуществлять взлёт и посадку (ч. 4.3)?', '[{"id":"6ntuebsa","text":"С дворовых территорий"},{"id":"w4sMseWi","text":"С посадочных площадок жилых домов"},{"id":"5pwgC6d","text":"Со специализированных объектов взлёта и посадки"},{"id":"ynQZlffe","text":"С охраняемых территорий при наличии пропуска"},{"id":"OiMwewR3","text":"С КПП войсковых частей"},{"id":"gwZLJO1s","text":"С автомобильных дорог при отсутствии движения"}]', '["6ntuebsa","w4sMseWi","5pwgC6d"]', '', 2, 5970, '{"meta":{"article":"Статья 4, ч. 4.3","explanation":"Ч. 4.3 — кроме охраняемых и закрытых территорий.","quote":"4.3. Иные граждане Российской Федерации вправе осуществлять взлет и посадку с посадочных площадок жилых домов, дворовых территорий, специализированных объектов взлета и посадки, кроме охраняемых и закрытых территорий","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q012', NULL, 'full', 2, 'fz_vozduh', 'Статья 4, ч. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q012');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин сажает свой частный вертолёт на крышу жилого дома (не на посадочную площадку). Как это оценивается по ч. 4.3?', '[{"id":"4UIhI0g0","text":"Разрешено при уведомлении в частоту государственных структур"},{"id":"XsJvA1bL","text":"Запрещено: посадка воздушных судов в собственности физлиц на жилые дома запрещена"},{"id":"7XzKQiT","text":"Разрешено, если дом не является охраняемой территорией"},{"id":"cGxhP8tv","text":"Разрешено, т.к. гражданские пилоты не обязаны уведомлять о посадке"}]', '["XsJvA1bL"]', '', 3, 5980, '{"meta":{"article":"Статья 4, ч. 4.3","explanation":"Ч. 4.3 разрешает посадку на посадочные площадки жилых домов, но прямо запрещает посадку частных судов на жилые дома.","quote":"Запрещена посадка воздушных судов в собственности физических лиц на автомагистрали, автомобильные дороги, жилые дома.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q013', NULL, 'vp', 3, 'fz_vozduh', 'Статья 4, ч. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какие порядки использования воздушного пространства устанавливаются правилами (ч. 5.1)?', '[{"id":"WgORUUVR","text":"Лицензионный или свободный"},{"id":"TibJbFGU","text":"Заявительный или регистрационный"},{"id":"24SkSTbh","text":"Разрешительный или уведомительный"},{"id":"ZZBqU3E","text":"Разрешительный или запретительный"}]', '["24SkSTbh"]', '', 1, 5990, '{"meta":{"article":"Статья 5, ч. 5.1","explanation":"Ч. 5.1.","quote":"устанавливается разрешительный или уведомительный порядок использования воздушного пространства.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q014', NULL, 'medium', 1, 'fz_vozduh', 'Статья 5, ч. 5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q014');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте порядок использования воздушного пространства с его содержанием.', '[]', '[]', '', 2, 6000, '{"meta":{"article":"Статья 5, ч. 5.2; Статья 6, ч. 6.2","explanation":"Ч. 5.2 и 6.2.","quote":"6.2. Уведомительный порядок представляет собой направления запроса и уведомления о взлете и дальнейшем полете над территорией города. Направление уведомления осуществляется в частоту государственных структур.","difficulty":"2"},"pairs":[{"l":{"id":"f4rLqns","text":"Разрешительный порядок"},"r":{"id":"1DA6SHQT","text":"Выдача разрешения на полёт над определённой территорией"}},{"l":{"id":"qe6h72ff","text":"Уведомительный порядок"},"r":{"id":"Xt1mbuOD","text":"Направление запроса и уведомления о взлёте и дальнейшем полёте над территорией города"}},{"l":{"id":"BCSlWMHx","text":"Канал направления уведомления"},"r":{"id":"bxg55gl","text":"Частота государственных структур"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q015', NULL, 'vp', 2, 'fz_vozduh', 'Статья 5, ч. 5.2; Статья 6, ч. 6.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q015');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кому выдаётся разрешение на пролёт над запретной территорией?', '[{"id":"PXCxJKbS","text":"Сотрудникам ЧОП и СМИ"},{"id":"4oNQpqXl","text":"Любым гражданам при наличии лицензии пилота"},{"id":"2j8wWFdU","text":"Только сотрудникам государственных организаций"},{"id":"E3TCvjmQ","text":"Только членам Правительства ФО"}]', '["2j8wWFdU"]', '', 1, 6010, '{"meta":{"article":"Статья 5, ч. 5.3","explanation":"Ч. 5.3, первое предложение.","quote":"5.3. Разрешение на пролет над запретной территорией выдается только сотрудникам государственных организаций.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q016', NULL, 'full', 1, 'fz_vozduh', 'Статья 5, ч. 5.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Может ли воздушное судно в собственности физического лица пролетать над закрытой или охраняемой территорией (например, над В/Ч)?', '[{"id":"kmCzqwvV","text":"Да, при уведомлении в частоту госструктур"},{"id":"ETc29g1b","text":"Нет, пролёт таким судам запрещён"},{"id":"5B1AxI","text":"Да, с разрешения любого военнослужащего на КПП"},{"id":"cC8qoMAe","text":"Да, если полёт проходит на большой высоте"}]', '["ETc29g1b"]', '', 1, 6020, '{"meta":{"article":"Статья 5, ч. 5.3","explanation":"Ч. 5.3, второе предложение.","quote":"Воздушным судам в собственности физических лиц запрещен пролет над закрытыми и охраняемыми территориями согласно законодательству о закрытых и охраняемых территориях.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q017', NULL, 'medium', 1, 'fz_vozduh', 'Статья 5, ч. 5.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе выдать разрешение на пролёт над закрытой и охраняемой территорией (ч. 5.4)?', '[{"id":"QATkKWm","text":"Руководители территориальных подразделений органов государственной власти и их заместители"},{"id":"SBY9Joa","text":"Диспетчер гражданской авиации"},{"id":"eHQngO05","text":"Губернатор Федерального округа РФ и Вице-губернаторы ФО"},{"id":"QHMVobY0","text":"Председатель Государственной думы единолично"},{"id":"6RIo1Hos","text":"Руководители соответствующего федерального органа исполнительной власти"},{"id":"YzntiCDg","text":"Любой пилот госструктуры с допуском"}]', '["QATkKWm","eHQngO05","6RIo1Hos"]', '', 3, 6030, '{"meta":{"article":"Статья 5, ч. 5.4","explanation":"Перечень ч. 5.4 также включает уполномоченных руководителей (начальников) подразделений территориальных органов.","quote":"5.4. Разрешение на пролет над закрытой и охраняемой территорией выдается Губернатором Федерального округа Российской Федерации и Вице-губернаторами Федерального округа, руководителями соответствующего федерального органа исполнительной власти, руководителями территориальных подразделений органов государственной власти","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q018', NULL, 'full', 3, 'fz_vozduh', 'Статья 5, ч. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите элементы запроса на разрешение о пролёте над запретной зоной в порядке, установленном формой ч. 6.1.', '[]', '[]', '', 2, 6040, '{"meta":{"article":"Статья 6, ч. 6.1","explanation":"Форма ч. 6.1.","quote":"[№-вертолета][Состав: “количество пассажиров”] Пилот “Должность/звание” “Имя Фамилия” запрашивает разрешение пролета над запретной зоной ... (Название зоны).","difficulty":"2"},"items":[{"id":"YnZD7fU9","text":"[№-вертолёта]"},{"id":"BkiFyfMH","text":"[Состав: «количество пассажиров»]"},{"id":"KQhAYtfl","text":"Пилот «Должность/звание» «Имя Фамилия»"},{"id":"DJoeDjMB","text":"запрашивает разрешение пролёта над запретной зоной … (Название зоны)"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q020', NULL, 'full', 2, 'fz_vozduh', 'Статья 6, ч. 6.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q020');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что указывается в блоке [Состав: …] запроса пилота?', '[{"id":"SAKPfafi","text":"Вид груза на борту"},{"id":"emYtQRuE","text":"Количество пассажиров"},{"id":"x1Zj0l4","text":"Номер воинской части"},{"id":"iWEj94bZ","text":"Позывной пилота"}]', '["emYtQRuE"]', '', 1, 6050, '{"meta":{"article":"Статья 6, ч. 6.1","explanation":"Форма: [Состав: “количество пассажиров”]; в примере — «Состав: 01».","quote":"[Состав: “количество пассажиров”]","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q021', NULL, 'full', 1, 'fz_vozduh', 'Статья 6, ч. 6.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой элемент есть в форме запроса о взлёте (ч. 6.3), но отсутствует в форме запроса на пролёт над запретной зоной (ч. 6.1)?', '[{"id":"39Y92T8Z","text":"[№-вертолёта]"},{"id":"abyQQfG","text":"[Код доступа]"},{"id":"t0IvZ4bg","text":"Имя и фамилия пилота"},{"id":"Q387xU4t","text":"[Состав: «количество пассажиров»]"}]', '["abyQQfG"]', '', 3, 6060, '{"meta":{"article":"Статья 6, ч. 6.1, 6.3","explanation":"Форма 6.3: [№-вертолета]|[Состав][Код доступа] Пилот…; форма 6.1 кода доступа не содержит.","quote":"[№-вертолета]|[Состав: “количество пассажиров”][Код доступа] Пилот “Имя Фамилия” запрашивает разрешение на взлет (посадку) с посадочной площадки структуры … (Название структуры).","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q022', NULL, 'vp', 3, 'fz_vozduh', 'Статья 6, ч. 6.1, 6.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте вид сообщения пилота с ключевой формулировкой по форме ст. 6.', '[]', '[]', '', 2, 6070, '{"meta":{"article":"Статья 6, ч. 6.1, 6.3, 6.4","explanation":"Запрос — «запрашивает», уведомление — «осуществляет».","quote":"[№-вертолета]|[Состав: “количество пассажиров”][Код доступа] Пилот “Имя Фамилия” осуществляет взлет (посадку) с посадочной площадки структуры … (Название структуры).","difficulty":"2"},"pairs":[{"l":{"id":"jiK9PGYp","text":"Запрос на пролёт над запретной зоной (6.1)"},"r":{"id":"3KLlDVv9","text":"«запрашивает разрешение пролета над запретной зоной»"}},{"l":{"id":"NUzNnIpx","text":"Запрос о взлёте (посадке) (6.3)"},"r":{"id":"n4LfDyOq","text":"«запрашивает разрешение на взлет (посадку) с посадочной площадки структуры»"}},{"l":{"id":"0SwNFiYm","text":"Уведомление о взлёте и посадке (6.4)"},"r":{"id":"J4cY3Ixy","text":"«осуществляет взлет (посадку) с посадочной площадки структуры»"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q023', NULL, 'full', 2, 'fz_vozduh', 'Статья 6, ч. 6.1, 6.3, 6.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязан сделать пилот воздушного судна госорганизации перед взлётом?', '[{"id":"GI608SI8","text":"Ничего, если взлёт с площадки своей организации"},{"id":"xqOn6Zw","text":"Получить разрешение диспетчера аэропорта"},{"id":"2ItZ0C6n","text":"Уведомить о взлёте в частоту государственных структур"},{"id":"1xxyMOgq","text":"Получить письменное разрешение Губернатора"}]', '["2ItZ0C6n"]', '', 1, 6080, '{"meta":{"article":"Статья 7, ч. 7.1","explanation":"Ч. 7.1.","quote":"7.1. Перед осуществлением взлета, пилот воздушного судна государственной организации обязан уведомить о взлете в частоту государственных структур.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q024', NULL, 'medium', 1, 'fz_vozduh', 'Статья 7, ч. 7.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q024');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник органов Правительства ФО садится на посадочную площадку В/Ч. Каков его порядок?', '[{"id":"ihDZXmZl","text":"Посадка запрещена без разрешения командира части"},{"id":"qVvSQfMz","text":"Посадка без уведомления и без запроса"},{"id":"LjMyo0aS","text":"Посадка с уведомлением; запрашивать разрешение он не обязан"},{"id":"HbAjjgO","text":"Обязан запросить разрешение у дежурного по части"}]', '["LjMyo0aS"]', '', 2, 6090, '{"meta":{"article":"Статья 7, ч. 7.3","explanation":"Ч. 7.3.","quote":"7.3. Сотрудники органов Правительства Федерального округа Российской Федерации осуществляют посадку на любые посадочные площадки государственных организаций с уведомлением о посадке. Сотрудники органов Правительства Федерального округа Российской Федерации не обязаны запрашивать разрешение на посадку.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q027', NULL, 'full', 2, 'fz_vozduh', 'Статья 7, ч. 7.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой номер вертолёта закреплён за ВС РФ (Армия) в таблице ст. 8?', '[{"id":"331eiK2m","text":"№-GRF/2209-13"},{"id":"gg2uCjWA","text":"№-RNG/2703-41"},{"id":"U4CDULE5","text":"№-RAF/4145-40"},{"id":"OJmTKjfw","text":"№-MOI/1001-42"}]', '["U4CDULE5"]', '', 1, 6100, '{"meta":{"article":"Статья 8","explanation":"Таблица ст. 8.","quote":"| ВС РФ (Армия) | №-RAF/4145-40 | T/L **/ |","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q028', NULL, 'full', 1, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q028');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте структуру с номером её вертолёта по ст. 8.', '[]', '[]', '', 2, 6110, '{"meta":{"article":"Статья 8","explanation":"Таблица ст. 8.","quote":"| ГУ МВД (Полиция) | №-MOI/1001-42 | T/L **/ |","difficulty":"2"},"pairs":[{"l":{"id":"zwi5kRlj","text":"Правительство"},"r":{"id":"6CSGfVr","text":"№-GRF/2209-13"}},{"l":{"id":"Uauh2Wf","text":"ГУ МВД (Полиция)"},"r":{"id":"MJ66WFwX","text":"№-MOI/1001-42"}},{"l":{"id":"dO9rc8RQ","text":"ФСВНГ (Росгвардия)"},"r":{"id":"AeumMyCb","text":"№-RNG/2703-41"}},{"l":{"id":"jqsSswvy","text":"Москва-Live"},"r":{"id":"vjbFQDe2","text":"№-MLV/0810-11"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q029', NULL, 'full', 2, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько государственных структур перечислено в таблице номеров вертолётов и кодов доступа ст. 8?', '[]', '[]', '', 2, 6120, '{"meta":{"article":"Статья 8","explanation":"Правительство, ФСБ, ГУ МВД, ФСВНГ, ВС РФ, ОМС, Москва-Live.","quote":"Каждая государственная структура имеет свой вертолет и свои коды доступа на осуществления взлета и посадки.","difficulty":"2"},"answer":7,"tolerance":0,"unit":"структур"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q030', NULL, 'vp', 2, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Для какой структуры в ст. 8 код доступа указан открыто как «T/L 8800/3g»?', '[{"id":"4W9v5Z2L","text":"ВС РФ (Армия)"},{"id":"gpoGO1l","text":"Москва-Live"},{"id":"xHTFJNiw","text":"ФСБ"},{"id":"wNTvtz0A","text":"ОМС"}]', '["wNTvtz0A"]', '', 3, 6130, '{"meta":{"article":"Статья 8","explanation":"У ОМС — 8800/3g, у Москва-Live — 5535/2g; у остальных код скрыт (**/).","quote":"| ОМС | №RMS/2106-12 | T/L 8800/3g |","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q031', NULL, 'medium', 3, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Обязаны ли пилоты гражданских воздушных судов уведомлять силовые органы о взлёте/посадке?', '[{"id":"MM027lU","text":"Да, всегда в частоту госструктур"},{"id":"vcHyzEYO","text":"Да, только при полёте над городом"},{"id":"AMe9b9Zf","text":"Да, только при наличии пассажиров"},{"id":"FuebgfzN","text":"Нет, они имеют право не уведомлять"}]', '["FuebgfzN"]', '', 1, 6140, '{"meta":{"article":"Статья 10","explanation":"Ст. 10.","quote":"Пилоты гражданских воздушных судов имеют право не уведомлять компетентные силовые органы о взлете/посадке своего воздушного транспорта.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q033', NULL, 'medium', 1, 'fz_vozduh', 'Статья 10', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Вертолёт госструктуры взлетел без уведомления. Расположите действия сотрудников силовых органов по ч. 11.1 в правильном порядке.', '[]', '[]', '', 2, 6150, '{"meta":{"article":"Статья 11, ч. 11.1","explanation":"Ч. 11.1: сначала требование о посадке, огонь — только при неподчинении.","quote":"11.1. В случае, если уведомления на взлет не осуществлялось, сотрудники силовых государственных органов выдвигают требование о посадке воздушного судна, в случае неподчинения законным требованиям - разрешается открытие огня на поражение","difficulty":"2"},"items":[{"id":"Jys8Tpl","text":"Установить, что уведомление о взлёте не осуществлялось"},{"id":"J9uvtoba","text":"Выдвинуть требование о посадке воздушного судна"},{"id":"BYyvQ2TS","text":"При неподчинении законным требованиям — открыть огонь на поражение"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q034', NULL, 'full', 2, 'fz_vozduh', 'Статья 11, ч. 11.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Несанкционированно взлетевший вертолёт находится над запретной территорией (В/Ч). Что вправе сделать сотрудники правоохранительных органов по ч. 11.2?', '[{"id":"bKy8rzWb","text":"Только сообщить в частоту и ждать посадки"},{"id":"qv9nYkUx","text":"Открыть огонь лишь после разрешения Губернатора"},{"id":"Uz0v7Lpv","text":"Открыть огонь на поражение"},{"id":"GnRAwGUc","text":"Только зафиксировать номер и составить протокол"}]', '["Uz0v7Lpv"]', '', 3, 6160, '{"meta":{"article":"Статья 11, ч. 11.2","explanation":"Ч. 11.2 не содержит условия о предварительном требовании посадки (в отличие от ч. 11.1).","quote":"11.2. В случае, если несанкционированно взлетевший вертолет находится над запретной территорией, сотрудники правоохранительных государственных органов вправе открыть огонь на поражение.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q035', NULL, 'vp', 3, 'fz_vozduh', 'Статья 11, ч. 11.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто несёт ответственность за ранение или смерть членов экипажа несанкционированно взлетевшего вертолёта, по которому открыли огонь сотрудники правоохранительных органов?', '[{"id":"0GMaHePo","text":"Сотрудники, открывшие огонь, ответственность не несут"},{"id":"3iSr3eb","text":"Губернатор как давший разрешение"},{"id":"79yzW3dS","text":"Сотрудники, открывшие огонь, — по общим правилам"},{"id":"vY1upMYv","text":"Командир подразделения, отдавший приказ"}]', '["0GMaHePo"]', '', 2, 6170, '{"meta":{"article":"Статья 11, ч. 11.3","explanation":"Ч. 11.3.","quote":"11.3. В случае ранения или смерти членов экипажа несанкционированно взлетевшего вертолета, ответственность за данные действия сотрудниками правоохранительных органов открывших огонь по воздушному судну не несется.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q036', NULL, 'full', 2, 'fz_vozduh', 'Статья 11, ч. 11.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q036');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какую ответственность несут лица, нарушившие требования 95-ФЗ?', '[{"id":"i8KI1Nf","text":"Только дисциплинарную по уставу организации"},{"id":"jBvJ7va","text":"Никакой, если не было вреда"},{"id":"LyfIgkqD","text":"Согласно законодательству Российской Федерации"},{"id":"BTALfmRN","text":"Только в виде запрета полётов на 7 дней"}]', '["LyfIgkqD"]', '', 1, 6180, '{"meta":{"article":"Статья 11, ч. 11.4","explanation":"Ч. 11.4 — отсылочная норма.","quote":"11.4. Лица, нарушившие требования настоящего Федерального закона, несут ответственность согласно законодательству Российской Федерации.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q037', NULL, 'full', 1, 'fz_vozduh', 'Статья 11, ч. 11.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Военнослужащий ВП несёт службу на КПП В/Ч №12132. Над частью низко пролетает частный вертолёт гражданина, садится на дворовую территорию за забором части не планирует, просто пролетает.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Вертолёт с бортовым номером №-MOI/1001-42 взлетел без уведомления в частоту госструктур и направляется к территории В/Ч. На связь не выходит.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Пилот ВС РФ майор Петров перевозит двух пассажиров и собирается взлететь с площадки В/Ч №12132.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Пилот ФСБ хочет сесть на площадку В/Ч №12132 и выходит в частоту только с фразой «осуществляю посадку».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир В/Ч в отпуске, его заместители отсутствуют. Пилот Росгвардии запрашивает разрешение на пролёт над территорией части.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Вертолёт ВС РФ с ранеными садится на автомобильную дорогу рядом с ДТП, чтобы забрать пострадавших, без запроса разрешения у кого-либо.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин на личном вертолёте взлетает со двора своего дома, не сообщая никому. Патруль ВП спрашивает, почему он не уведомил силовые органы.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: После обстрела несанкционированно взлетевшего вертолёта госструктуры над запретной зоной пилот ранен. Его руководство требует привлечь стрелявшего военнослужащего к ответственности.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Каким актом вводится и отменяется чрезвычайное положение?', '[{"id":"cUJjcdcC","text":"Указом Губернатора Федерального округа РФ"},{"id":"rQWaInwY","text":"Постановлением Законодательного собрания ФО"},{"id":"r4Tjdscl","text":"Приказом руководителя регионального УФСБ"},{"id":"9WRbTzf3","text":"Приказом Министра обороны"}]', '["cUJjcdcC"]', '', 1, 6270, '{"meta":{"article":"Статья 1, ч. 1.2","explanation":"Ч. 1.2.","quote":"1.2. Чрезвычайное положение вводится и отменяется соответствующим указом Губернатора Федерального округа Российской Федерации.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q002', NULL, 'full', 1, 'fkz_rezhimy', 'Статья 1, ч. 1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в часах) может вводиться чрезвычайное положение?', '[]', '[]', '', 1, 6280, '{"meta":{"article":"Статья 2, ч. 2.1","explanation":"Ч. 2.1: не более 48 часов (два дня), не менее 3 часов.","quote":"2.1. Чрезвычайное положение вправе вводится на срок, не превышающий 48 часов (два дня), но не менее, чем на 3 часа, с момента публикации соответствующего указа.","difficulty":"1"},"answer":48,"tolerance":0,"unit":"часов"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q003', NULL, 'medium', 1, 'fkz_rezhimy', 'Статья 2, ч. 2.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q003');
