INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что может вводиться, если в течение срока ЧП его цели не были достигнуты?', '[{"id":"aafvDtEs","text":"Режим военного положения"},{"id":"mJDMvc38","text":"Повторное ЧП на тот же срок без ограничений"},{"id":"w0kv4WFN","text":"Режим КТО на 7 дней"},{"id":"QK3z77R5","text":"Комендантский час на неограниченный срок"}]', '["aafvDtEs"]', '', 2, 6310, '{"meta":{"article":"Статья 2, ч. 2.2","explanation":"Ч. 2.2; также п. 4 ч. 13.2 — недостижение целей ЧП как причина военного положения.","quote":"В случае, если в течение этого срока цели введения чрезвычайного положения не были достигнуты, может вводиться режим военного положения","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q006', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 2, ч. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие обстоятельства относятся к основаниям введения чрезвычайного положения (ст. 3)?', '[{"id":"gZYAnsf","text":"Попытка насильственного изменения конституционного строя, захвата власти, теракты"},{"id":"e3lOC7V","text":"Ухудшение криминогенной обстановки"},{"id":"Z4YRUx5b","text":"Агрессия против РФ или непосредственная угроза агрессии"},{"id":"oGvYpKBQ","text":"Участившиеся случаи хищения государственного имущества"},{"id":"5yOKJ09a","text":"Похищение человека, захват заложника"},{"id":"p99Orsb","text":"Проведение рейда в отношении преступной группировки"},{"id":"r69UzgT7","text":"ЧС природного и/или технического характера, требующие масштабных аварийно-спасательных работ"}]', '["gZYAnsf","e3lOC7V","oGvYpKBQ","r69UzgT7"]', '', 2, 6320, '{"meta":{"article":"Статья 3","explanation":"Агрессия — основание военного положения (ч. 13.1), похищение и рейд — основания КТО (ч. 18.2).","quote":"1) ухудшение криминогенной обстановки на территории Российской Федерации или отдельных её субъектов; 2) участившиеся случаи хищения государственного имущества;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q007', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие органы исключены из-под руководства ФСБ в период ЧП (ч. 4.1)?', '[{"id":"OsVFH0pb","text":"Органы внутренних дел"},{"id":"uMhk8xcG","text":"Военные структуры"},{"id":"nJbfwCi3","text":"Органы Следственного Комитета"},{"id":"od21vrF","text":"Медицинские структуры"},{"id":"Zrt4HKQ","text":"Органы прокуратуры"}]', '["nJbfwCi3","Zrt4HKQ"]', '', 3, 6330, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1: «за исключением органов Следственного Комитета, органов прокуратуры».","quote":"руководство действиями всех правоохранительных, за исключением органов Следственного Комитета, органов прокуратуры, гражданских, медицинских, военных и иных государственных (федеральных) структур","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q009', NULL, 'vp', 3, 'fkz_rezhimy', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'ЧП введено на всей территории РФ. В чьё оперативное подчинение передаются все войска и воинские формирования?', '[{"id":"0ZgR3QJ","text":"Министра обороны"},{"id":"miW9qF6","text":"Председателя Совета Федерации"},{"id":"6xc1wj5S","text":"Руководителя регионального УФСБ"},{"id":"z6tJPzE8","text":"Губернатора Федерального округа РФ"}]', '["z6tJPzE8"]', '', 2, 6340, '{"meta":{"article":"Статья 4, ч. 4.2","explanation":"Ч. 4.2.","quote":"4.2. При введении чрезвычайного положения на всей территории Российской Федерации все войска и воинские формирования, а также силовые государственные структуры передаются в оперативное подчинение Губернатору Федерального округа Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q010', NULL, 'vp', 2, 'fkz_rezhimy', 'Статья 4, ч. 4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q010');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Силы и средства каких органов используются для обеспечения режима ЧП (ч. 5.2)?', '[{"id":"zEOLwzAN","text":"Федеральных органов безопасности"},{"id":"YvWPyPeg","text":"Политических партий"},{"id":"N9S36a8F","text":"Вооружённых сил РФ"},{"id":"zBvnr3E","text":"Органов внутренних дел"},{"id":"QSDRSe98","text":"Частных охранных предприятий"},{"id":"jLpfNa08","text":"Средств массовой информации"},{"id":"niCn0Ubp","text":"Войск национальной гвардии"}]', '["zEOLwzAN","N9S36a8F","zBvnr3E","niCn0Ubp"]', '', 2, 6350, '{"meta":{"article":"Статья 5, ч. 5.2","explanation":"Ч. 5.2 также называет силы и средства государственных медицинских учреждений.","quote":"5.2. Для обеспечения режима чрезвычайного положения используются силы и средства органов внутренних дел, федеральных органов безопасности, войск национальной гвардии Российской Федерации, вооруженные силы Российской Федерации","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q012', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 5, ч. 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q012');
