INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие меры может предусматривать указ о введении ЧП (ст. 7)?', '[{"id":"EhNkQMqV","text":"Приостановление деятельности частных организаций"},{"id":"rd3fFACj","text":"Введение карантина"},{"id":"1SAIzqG2","text":"Принудительное перемещение граждан на территории без ЧП"},{"id":"j4gpgPNO","text":"Задержание и арест граждан за нарушение указов"},{"id":"liasoQwa","text":"Ограничение движения транспортных средств и их обыск"},{"id":"EhPfI18W","text":"Введение военной цензуры"},{"id":"CmDBm1Ah","text":"Проверка документов, личный обыск, обыск вещей, жилища и ТС"}]', '["EhNkQMqV","rd3fFACj","liasoQwa","CmDBm1Ah"]', '', 2, 6370, '{"meta":{"article":"Статья 7","explanation":"Пп. 5, 6, 9, 11 ст. 7; перемещение граждан, военная цензура и задержание/арест — меры военного положения (пп. 7–9 ст. 14).","quote":"5) ограничение движения транспортных средств и осуществление их обыска; 6) приостановление деятельности частных организаций;","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q016', NULL, 'medium', 2, 'fkz_rezhimy', 'Статья 7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие полномочия имеет комендант территории ЧП (ч. 10.2)?', '[{"id":"k8ARwn4c","text":"Издаёт приказы и распоряжения, обязательные для всех организаций, граждан и командиров силовых органов"},{"id":"qZWytGy","text":"Назначает судей на территории ЧП"},{"id":"dxCytYe","text":"Продлевает ЧП свыше 48 часов"},{"id":"tjHFMli7","text":"Отменяет указ Губернатора о ЧП"},{"id":"Pl15GRcd","text":"Оповещает население через СМИ о порядке выполнения мер"},{"id":"sI2or3kw","text":"Выдворяет за пределы территории лиц, нарушающих режим ЧП"},{"id":"inkGyXh","text":"Определяет особый режим въезда и выезда"}]', '["k8ARwn4c","Pl15GRcd","sI2or3kw","inkGyXh"]', '', 2, 6380, '{"meta":{"article":"Статья 10, ч. 10.2","explanation":"Ч. 10.2, пп. 1–4.","quote":"3) выдворяет в установленном порядке за пределы территории, на которой введено чрезвычайное положение, лиц, нарушающих режим чрезвычайного положения;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q020', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 10, ч. 10.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q020');
