INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите этапы введения военного положения в порядке ст. 12.', '[]', '[]', '', 2, 6400, '{"meta":{"article":"Статья 12, ч. 12.1–12.4","explanation":"Ч. 12.1–12.4.","quote":"12.3. Указ Губернатора Федерального округа Российской Федерации о введении военного положения незамедлительно передается на утверждение Законодательным Собранием Федерального округа.","difficulty":"2"},"items":[{"id":"7AmatbJp","text":"Губернатор ФО издаёт указ о введении военного положения"},{"id":"a4Q5Cf73","text":"Губернатор незамедлительно сообщает о введении Законодательному Собранию ФО"},{"id":"qxFE1dR","text":"Указ незамедлительно передаётся на утверждение Законодательным Собранием ФО"},{"id":"IjsgG5zq","text":"Если указ не утверждён — он прекращает действие по истечении 24 часов"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q025', NULL, 'medium', 2, 'fkz_rezhimy', 'Статья 12, ч. 12.1–12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Через сколько часов прекращает действие указ о введении военного положения, не утверждённый Законодательным Собранием ФО?', '[]', '[]', '', 2, 6410, '{"meta":{"article":"Статья 12, ч. 12.4","explanation":"Ч. 12.4.","quote":"не утвержденный Законодательным Собранием Федерального округа, прекращает действие по истечению двадцати четырех (24) часов с момента принятия такого решения","difficulty":"2"},"answer":24,"tolerance":0,"unit":"часа"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q026', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 12, ч. 12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Не ранее скольких дней разрешается повторно ввести военное положение после прекращения указа в связи с неутверждением?', '[]', '[]', '', 3, 6420, '{"meta":{"article":"Статья 12, ч. 12.4","explanation":"Ч. 12.4.","quote":"повторно ввести режим военного положения разрешается не ранее семи (7) дней с момента прекращения действия указа","difficulty":"3"},"answer":7,"tolerance":0,"unit":"дней"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q027', NULL, 'medium', 3, 'fkz_rezhimy', 'Статья 12, ч. 12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является иными причинами для введения военного положения (ч. 13.2)?', '[{"id":"uM9ZfOo6","text":"ЧС технического характера"},{"id":"3AyQGcfM","text":"Недостижение целей введения режима ЧП"},{"id":"59kuLmE5","text":"Похищение человека"},{"id":"xKQoCE7o","text":"Попытка совершения государственного переворота"},{"id":"NEuS7Ym3","text":"Угроза жизни высших чинов госструктур, Правительства ФО или Губернатора"},{"id":"UKwbxiP9","text":"Участившиеся случаи хищения госимущества"}]', '["3AyQGcfM","xKQoCE7o","NEuS7Ym3"]', '', 2, 6430, '{"meta":{"article":"Статья 13, ч. 13.2","explanation":"Ч. 13.2 (также п. 3 — повышенная активность криминогенной организации, подрывающая безопасность). Хищения и ЧС — основания ЧП (ст. 3), похищение — КТО.","quote":"1) попытка совершения государственного переворота; 2) угроза жизни высших чинов государственных структур, Правительства Федерального округа или Губернатора Федерального округа Российской Федерации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q028', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 13, ч. 13.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q028');
