INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На сколько лет лишения свободы наказывается побег из-под задержания по ч. 1 ст. 87 УК?', '[]', '[]', '', 2, 7380, '{"meta":{"article":"УК, статья 87, ч. 87.1","explanation":"Ч. 1 ст. 87 УК.","quote":"Наказывается лишением свободы на срок четырех лет","difficulty":"2"},"answer":4,"tolerance":0,"unit":"года"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-118', 'r6-uk87-pobeg', 'vp', 2, 'uk', 'УК, статья 87, ч. 87.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-118');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кому военнослужащие ССО передают задержанного при коде-3, если военнослужащие ВП в части есть?', '[{"id":"h0glOeNI","text":"Роте охраны и обеспечения"},{"id":"6X7d8UP8","text":"Медицинской роте"},{"id":"tqVVdhRe","text":"Военнослужащим ВП"},{"id":"pt8ALHb1","text":"Военному комиссариату"}]', '["tqVVdhRe"]', '', 2, 7390, '{"meta":{"article":"Внутренний устав, п. 10.15 «а»","explanation":"П. 10.15 «а» устава; при отсутствии ВП — самостоятельно вызывают правоохранительные органы.","quote":"при необходимости производят задержание с дальнейшей передачей военнослужащим ВП","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-119', 'r6-ustav-kod3-peredacha', 'vp', 2, 'vu', 'Внутренний устав, п. 10.15 «а»', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-119');
