INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'blanks_select', 'Заполните пропуск в ч. 12.4 ФКЗ: указ о введении военного положения, не утверждённый Законодательным Собранием Федерального округа, …', '[]', '[]', '', 3, 7620, '{"meta":{"article":"ФКЗ, ст. 12, ч. 12.4","explanation":"ФКЗ, ч. 12.4.","quote":"прекращает действие по истечению двадцати четырех (24) часов с момента принятия такого решения","difficulty":"3"},"content":"… прекращает действие по истечению [[*двадцати четырех (24)|сорока восьми (48)|двенадцати (12)|семидесяти двух (72)]] часов с момента принятия такого решения","parts":["… прекращает действие по истечению ",{"i":0}," часов с момента принятия такого решения"],"blanks":[{"opts":[{"id":"37hwdh9w","text":"двадцати четырех (24)"},{"id":"MMsSneE","text":"сорока восьми (48)"},{"id":"ovI9Gfe","text":"двенадцати (12)"},{"id":"raF4hf7V","text":"семидесяти двух (72)"}],"correct":"37hwdh9w"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz-b02', NULL, 'vp', 3, 'fkz_rezhimy', 'ФКЗ, ст. 12, ч. 12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz-b02');
