INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте п. 29 КПС найдите и отметьте слова о запрете, связанном с рацией.', '[]', '[]', '', 2, 7660, '{"meta":{"article":"КПС, п. 29","explanation":"КПС, п. 29.","quote":"игнорировать запросы о состоянии поста в рацию; … своевременно не докладывать о состоянии поста;","difficulty":"2"},"content":"29. При несении постовой службы запрещается:\nтерять концентрацию, отвлекаться на телефон, иные электронные средства, на разговоры;\nоставлять вооружение без контроля, убирать его из рук;\n[[игнорировать запросы о состоянии поста в рацию;]]\nсвоевременно не докладывать о состоянии поста;","tokens":[{"t":"29."},{"t":"При"},{"t":"несении"},{"t":"постовой"},{"t":"службы"},{"t":"запрещается:"},{"br":1},{"t":"терять"},{"t":"концентрацию,"},{"t":"отвлекаться"},{"t":"на"},{"t":"телефон,"},{"t":"иные"},{"t":"электронные"},{"t":"средства,"},{"t":"на"},{"t":"разговоры;"},{"br":1},{"t":"оставлять"},{"t":"вооружение"},{"t":"без"},{"t":"контроля,"},{"t":"убирать"},{"t":"его"},{"t":"из"},{"t":"рук;"},{"br":1},{"t":"игнорировать","c":1},{"t":"запросы","c":1},{"t":"о","c":1},{"t":"состоянии","c":1},{"t":"поста","c":1},{"t":"в","c":1},{"t":"рацию;","c":1},{"br":1},{"t":"своевременно"},{"t":"не"},{"t":"докладывать"},{"t":"о"},{"t":"состоянии"},{"t":"поста;"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-kps-f01', NULL, 'medium', 2, 'kps', 'КПС, п. 29', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-f01');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте п. 2 ч. 10.1 ПК отметьте, что предъявляют сотрудники, личность которых засекречена.', '[]', '[]', '', 3, 7670, '{"meta":{"article":"ПК, ст. 10, ч. 10.1, п. 2","explanation":"ПК, ч. 10.1, п. 2: жетон, его номер и позывной.","quote":"2) идентифицировать себя: сотрудник предоставляет удостоверение, называет должность, звание, фамилию; сотрудники, находящиеся при исполнении обязанностей, предусматривающих засекречивание своей личности предоставляют жетон, называют его номер и позывной;","difficulty":"3"},"content":"2) идентифицировать себя: сотрудник предоставляет удостоверение, называет должность, звание, фамилию; сотрудники, находящиеся при исполнении обязанностей, предусматривающих засекречивание своей личности предоставляют [[жетон,]] называют его номер и позывной;","tokens":[{"t":"2)"},{"t":"идентифицировать"},{"t":"себя:"},{"t":"сотрудник"},{"t":"предоставляет"},{"t":"удостоверение,"},{"t":"называет"},{"t":"должность,"},{"t":"звание,"},{"t":"фамилию;"},{"t":"сотрудники,"},{"t":"находящиеся"},{"t":"при"},{"t":"исполнении"},{"t":"обязанностей,"},{"t":"предусматривающих"},{"t":"засекречивание"},{"t":"своей"},{"t":"личности"},{"t":"предоставляют"},{"t":"жетон,","c":1},{"t":"называют"},{"t":"его"},{"t":"номер"},{"t":"и"},{"t":"позывной;"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-f01', NULL, 'vp', 3, 'pk', 'ПК, ст. 10, ч. 10.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-f01');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте отметьте предельную длительность телефонного звонка задержанного.', '[]', '[]', '', 3, 7680, '{"meta":{"article":"ПК, ст. 8, ч. 8.1, п. 5","explanation":"ПК, ч. 8.1, п. 5.","quote":"5) требовать предоставить возможность провести один (1) телефонный звонок любому лицу на выбор задержанного, не превышающий двух (2) минут.","difficulty":"3"},"content":"5) требовать предоставить возможность провести один (1) телефонный звонок любому лицу на выбор задержанного, не превышающий [[двух (2) минут.]]","tokens":[{"t":"5)"},{"t":"требовать"},{"t":"предоставить"},{"t":"возможность"},{"t":"провести"},{"t":"один"},{"t":"(1)"},{"t":"телефонный"},{"t":"звонок"},{"t":"любому"},{"t":"лицу"},{"t":"на"},{"t":"выбор"},{"t":"задержанного,"},{"t":"не"},{"t":"превышающий"},{"t":"двух","c":1},{"t":"(2)","c":1},{"t":"минут.","c":1}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-f02', NULL, 'vp', 3, 'pk', 'ПК, ст. 8, ч. 8.1, п. 5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-f02');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В перечне мер обеспечения производства (ВУ, п. 5.4) отметьте предельный срок гауптвахты.', '[]', '[]', '', 2, 7690, '{"meta":{"article":"ВУ, п. 5.4 «в»","explanation":"ВУ, п. 5.4, подп. «в».","quote":"в) гауптвахта на срок не более 30 минут","difficulty":"2"},"content":"а) задержание;\nб) доставление;\nв) гауптвахта на срок [[не более 30 минут]] (подозреваемые и обвиняемые военнослужащие содержатся на гауптвахтах в случаях и порядке, которые предусмотрены Процессуальным кодексом Российской Федерации, и иными нормативными правовыми актами Российской Федерации);","tokens":[{"t":"а)"},{"t":"задержание;"},{"br":1},{"t":"б)"},{"t":"доставление;"},{"br":1},{"t":"в)"},{"t":"гауптвахта"},{"t":"на"},{"t":"срок"},{"t":"не","c":1},{"t":"более","c":1},{"t":"30","c":1},{"t":"минут","c":1},{"t":"(подозреваемые"},{"t":"и"},{"t":"обвиняемые"},{"t":"военнослужащие"},{"t":"содержатся"},{"t":"на"},{"t":"гауптвахтах"},{"t":"в"},{"t":"случаях"},{"t":"и"},{"t":"порядке,"},{"t":"которые"},{"t":"предусмотрены"},{"t":"Процессуальным"},{"t":"кодексом"},{"t":"Российской"},{"t":"Федерации,"},{"t":"и"},{"t":"иными"},{"t":"нормативными"},{"t":"правовыми"},{"t":"актами"},{"t":"Российской"},{"t":"Федерации);"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-f01', NULL, 'medium', 2, 'vu', 'ВУ, п. 5.4 «в»', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-f01');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте ст. 3 ФКЗ отметьте, чему должны угрожать обстоятельства для введения чрезвычайного положения.', '[]', '[]', '', 2, 7700, '{"meta":{"article":"ФКЗ, ст. 3","explanation":"ФКЗ, ст. 3.","quote":"Чрезвычайное положение вводится лишь при наличии обстоятельств, которые представляют собой непосредственную угрозу жизни и безопасности граждан или конституционному строю Российской Федерации.","difficulty":"2"},"content":"Чрезвычайное положение вводится лишь при наличии обстоятельств, которые представляют собой непосредственную угрозу [[жизни и безопасности граждан]] или [[конституционному строю]] Российской Федерации.","tokens":[{"t":"Чрезвычайное"},{"t":"положение"},{"t":"вводится"},{"t":"лишь"},{"t":"при"},{"t":"наличии"},{"t":"обстоятельств,"},{"t":"которые"},{"t":"представляют"},{"t":"собой"},{"t":"непосредственную"},{"t":"угрозу"},{"t":"жизни","c":1},{"t":"и","c":1},{"t":"безопасности","c":1},{"t":"граждан","c":1},{"t":"или"},{"t":"конституционному","c":1},{"t":"строю","c":1},{"t":"Российской"},{"t":"Федерации."}],"partial":true}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz-f01', NULL, 'full', 2, 'fkz_rezhimy', 'ФКЗ, ст. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz-f01');
